INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13126, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坚实", "is_correct": true, "explanation": "坚实与“疏松”相对，指质地结实、不松散。"}, {"text": "清澈", "is_correct": false, "explanation": "与“疏松”没有反义关系，“清澈”指水或天空等清亮透明。"}, {"text": "响亮", "is_correct": false, "explanation": "与“疏松”没有反义关系，“响亮”指声音大而清楚。"}, {"text": "干净", "is_correct": false, "explanation": "与“疏松”没有反义关系，“干净”指没有污物。"}], "correct_answer": "坚实", "explanations": {"坚实": "坚实与“疏松”相对，指质地结实、不松散。", "清澈": "与“疏松”没有反义关系，“清澈”指水或天空等清亮透明。", "响亮": "与“疏松”没有反义关系，“响亮”指声音大而清楚。", "干净": "与“疏松”没有反义关系，“干净”指没有污物。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a4c6ac7-6d86-4528-8bff-d960de24857d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13126, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指土壤、岩石等结构松散，不紧密。", "primary_collocate": null, "pronunciation": "shū sōng", "ipa": "ʂu˥ sʊŋ˥", "syllable_count": 2, "sentences": [{"text": "整个过程历时三至六个月，视气候与管理精度而定，终产物呈深褐色、质地疏松、具森林土壤特有清香，即标志腐熟完成。", "target_word": "疏松", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这块地的土很疏松，种花很容易。", "target_word": "疏松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蚯蚓在地下钻来钻去，让土变得疏松。", "target_word": "疏松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种石头很疏松，里面有很多小洞。", "target_word": "疏松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民把地翻了一遍，土就变得疏松了。", "target_word": "疏松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疏松的土壤里，空气和水都容易进去。", "target_word": "疏松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙子比黏土疏松，水很快就流下去了。", "target_word": "疏松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的岩石很疏松，一碰就会掉下小石子。", "target_word": "疏松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土太硬了，种子长不好，要先把它弄疏松。", "target_word": "疏松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山坡上的土很疏松，下大雨时容易滑下来。", "target_word": "疏松", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "疏鬆", "label": "繁体"}], "register": "中性", "sense_fingerprint": "土壤、岩石等结构松散、不紧密", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb6f056b-9b65-490b-8dc3-4791e2f44aeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13126, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "疏松", "is_correct": true, "explanation": "正确答案。疏松（shū sōng）指土壤、岩石等结构松散，不紧密。"}, {"text": "输送", "is_correct": false, "explanation": "shū sòng 与 shū sōng 声调不同（第四声与第一声），意思是运送、输送，与“结构松散”无关。"}, {"text": "疏通", "is_correct": false, "explanation": "tōng 与 sōng 声母不同（t 与 s），意思是使不通的地方通开，与本词义不同。"}, {"text": "酥松", "is_correct": false, "explanation": "sū 与 shū 声母不同（s 与 sh），意思是松软酥脆，多用于食物，与本词义不同。"}], "explanations": {"疏松": "正确答案。疏松（shū sōng）指土壤、岩石等结构松散，不紧密。", "输送": "shū sòng 与 shū sōng 声调不同（第四声与第一声），意思是运送、输送，与“结构松散”无关。", "疏通": "tōng 与 sōng 声母不同（t 与 s），意思是使不通的地方通开，与本词义不同。", "酥松": "sū 与 shū 声母不同（s 与 sh），意思是松软酥脆，多用于食物，与本词义不同。"}, "sentence_index": null, "correct_answer": "疏松"}, "level_3": {"options": [{"text": "疏松", "is_correct": true, "explanation": "“疏松”表示结构松散、空隙多，符合腐熟完成后终产物的质地。"}, {"text": "坚硬", "is_correct": false, "explanation": "语义：腐熟完成的产物应当松软，说质地坚硬与之矛盾。"}, {"text": "黏稠", "is_correct": false, "explanation": "搭配：“黏稠”多用于液体或糊状物，不用来形容固体土壤的质地。"}, {"text": "腥臭", "is_correct": false, "explanation": "语义：句中说它具有“特有清香”，腥臭与之正相反。"}], "explanations": {"疏松": "“疏松”表示结构松散、空隙多，符合腐熟完成后终产物的质地。", "坚硬": "语义：腐熟完成的产物应当松软，说质地坚硬与之矛盾。", "黏稠": "搭配：“黏稠”多用于液体或糊状物，不用来形容固体土壤的质地。", "腥臭": "语义：句中说它具有“特有清香”，腥臭与之正相反。"}, "sentence_index": 0, "correct_answer": "疏松"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个人的心思很疏松，做事总是丢三落四。", "explanation": "疏松指土壤、岩石等物质的结构松散，不能用来形容人的心思或做事。"}, {"text": "他绷紧的肌肉终于疏松下来了。", "explanation": "这里应该用〈松弛〉。疏松指土壤、岩石等物质结构松散，肌肉放松要用松弛。"}, {"text": "这段时间大家的学习很疏松。", "explanation": "这里应该用〈松懈〉。疏松只用于土壤、岩石等物质，形容人做事不认真要用松懈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a4c6ac7-6d86-4528-8bff-d960de24857d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13126, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "疏松", "is_correct": true, "explanation": "“疏松”指沙子颗粒间空隙大，比黏土更容易透水，与“水很快就流下去了”一致。"}, {"text": "紧实", "is_correct": false, "explanation": "语义：“紧实”指密实、空隙少，若沙子比黏土紧实，水就不会很快流下去，与句意矛盾。"}, {"text": "滑腻", "is_correct": false, "explanation": "搭配：“滑腻”多指油脂、泥浆等滑而黏的东西，不用来比较沙子。"}, {"text": "细腻", "is_correct": false, "explanation": "语义：沙子颗粒比黏土粗，说沙子细腻与事实不符。"}], "explanations": {"疏松": "“疏松”指沙子颗粒间空隙大，比黏土更容易透水，与“水很快就流下去了”一致。", "紧实": "语义：“紧实”指密实、空隙少，若沙子比黏土紧实，水就不会很快流下去，与句意矛盾。", "滑腻": "搭配：“滑腻”多指油脂、泥浆等滑而黏的东西，不用来比较沙子。", "细腻": "语义：沙子颗粒比黏土粗，说沙子细腻与事实不符。"}, "sentence_index": 6, "correct_answer": "疏松"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支队伍的纪律很疏松，经常有人迟到。", "explanation": "这里应该用〈松散〉。疏松只用于土壤、岩石等物质的结构，形容纪律要用松散。"}, {"text": "这个地区的人口很疏松，村子之间隔得很远。", "explanation": "这里应该用〈稀疏〉。疏松指土壤、岩石的结构，人口少而分散要用稀疏。"}, {"text": "这件外套很疏松，穿在身上很舒服。", "explanation": "这里应该用〈宽松〉。疏松只用于土壤、岩石等物质，形容衣服肥大要用宽松。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a4c6ac7-6d86-4528-8bff-d960de24857d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13126, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨后，林子里的土变地疏松了，踩上去软软的。", "corrected_sentence": "雨后，林子里的土变得疏松了，踩上去软软的。", "error_description": "助词错误：动词“变”后面接补语“疏松”时要用“得”，应说“变得疏松”，不能说“变地疏松”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a4c6ac7-6d86-4528-8bff-d960de24857d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13126, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农田里有一大片疏松地土地。", "corrected_sentence": "农田里有一大片疏松的土地。", "error_description": "修饰名词时要用“的”，“地”是状语的标记，不能放在名词前，应说“疏松的土地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a4c6ac7-6d86-4528-8bff-d960de24857d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
