INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13127, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在森林里，由落叶、树枝等腐烂后和泥土混在一起形成的土壤。", "primary_collocate": null, "pronunciation": "sēn lín tǔ rǎng", "ipa": "sən˥ lin˧˥ tʰu˨˩˦ ɻɑŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "整个过程历时三至六个月，视气候与管理精度而定，终产物呈深褐色、质地疏松、具森林土壤特有清香，即标志腐熟完成。", "target_word": "森林土壤", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "森林土壤里有很多落叶和小虫子。", "target_word": "森林土壤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林土壤是落叶腐烂以后形成的。", "target_word": "森林土壤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林土壤又黑又软，闻起来有一股清香。", "target_word": "森林土壤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抓了一把森林土壤放进花盆里。", "target_word": "森林土壤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树木长得好，因为森林土壤很肥沃。", "target_word": "森林土壤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨水落下来，森林土壤像海绵一样吸水。", "target_word": "森林土壤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种花要用森林土壤种，长得更好。", "target_word": "森林土壤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "走在森林里，脚下的森林土壤软软的。", "target_word": "森林土壤", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家正在研究不同山上的森林土壤。", "target_word": "森林土壤", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "森林中由落叶枝条腐烂并与泥土混合形成的土壤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb6f056b-9b65-490b-8dc3-4791e2f44aeb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13127, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "森林土壤", "is_correct": true, "explanation": "“森林土壤”指森林中落叶腐烂后形成的土，带有清香，与句意相合。"}, {"text": "沙漠土壤", "is_correct": false, "explanation": "语义：沙漠土壤干燥、缺少有机质，没有森林土壤那种清香。"}, {"text": "海水", "is_correct": false, "explanation": "搭配：“特有清香”多用于植物、土地的气味，不说海水有清香。"}, {"text": "工业废水", "is_correct": false, "explanation": "语义：工业废水气味刺鼻，与“清香”正相反。"}], "explanations": {"森林土壤": "“森林土壤”指森林中落叶腐烂后形成的土，带有清香，与句意相合。", "沙漠土壤": "语义：沙漠土壤干燥、缺少有机质，没有森林土壤那种清香。", "海水": "搭配：“特有清香”多用于植物、土地的气味，不说海水有清香。", "工业废水": "语义：工业废水气味刺鼻，与“清香”正相反。"}, "sentence_index": 0, "correct_answer": "森林土壤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家养了一只森林土壤，它每天都会叫。", "explanation": "这里应该用〈小狗〉。森林土壤是森林里的土，不能养，也不会叫。"}, {"text": "这片森林土壤很茂密，遮住了阳光。", "explanation": "这里应该用〈树林〉。“茂密”形容树木、草木生长得多，不能用来形容土壤。"}, {"text": "这棵大树的森林土壤扎得很深，很难拔起来。", "explanation": "这里应该用〈树根〉。“扎”指根茎伸入土中，土壤本身不会扎进土里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a4c6ac7-6d86-4528-8bff-d960de24857d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13127, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "森林土壤", "is_correct": true, "explanation": "“森林土壤”疏松多孔，能像海绵一样吸水，与句意相合。"}, {"text": "水泥地", "is_correct": false, "explanation": "语义：水泥不吸水，不能像海绵一样吸水。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃致密不透水，与“吸水”矛盾。"}, {"text": "钢板", "is_correct": false, "explanation": "搭配：“像海绵一样吸水”指多孔、松软的东西，钢板是致密金属，不搭配。"}], "explanations": {"森林土壤": "“森林土壤”疏松多孔，能像海绵一样吸水，与句意相合。", "水泥地": "语义：水泥不吸水，不能像海绵一样吸水。", "玻璃": "语义：玻璃致密不透水，与“吸水”矛盾。", "钢板": "搭配：“像海绵一样吸水”指多孔、松软的东西，钢板是致密金属，不搭配。"}, "sentence_index": 6, "correct_answer": "森林土壤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那座山上的森林土壤很高大，远远就能看见。", "explanation": "这里应该用〈树木〉。“高大”形容有高度的东西，土壤不说高大。"}, {"text": "工人正在砍伐森林土壤，准备修路。", "explanation": "这里应该用〈林木〉。“砍伐”用于树木，土壤不能被砍伐。"}, {"text": "这盆森林土壤开得很艳。", "explanation": "这里应该用〈花〉。“开得很艳”形容花朵，土壤不会开花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a4c6ac7-6d86-4528-8bff-d960de24857d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13127, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "树林里那片又黑又软森林土壤，很适合种蘑菇。", "corrected_sentence": "树林里那片又黑又软的森林土壤，很适合种蘑菇。", "error_description": "“又…又…”修饰名词时后面要加“的”，应说“又黑又软的森林土壤”，不能省略“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a4c6ac7-6d86-4528-8bff-d960de24857d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13127, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师带我们去山上取了两条森林土壤。", "corrected_sentence": "老师带我们去山上取了两袋森林土壤。", "error_description": "量词用错：“条”用于细长的物件，土壤要用“袋”计量，应说“两袋森林土壤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a4c6ac7-6d86-4528-8bff-d960de24857d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
