INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13128, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13128, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "清淡的、令人愉悦的香味。", "primary_collocate": null, "pronunciation": "qīng xiāng", "ipa": "tɕʰiŋ˥ ɕjɑŋ˥", "syllable_count": 2, "sentences": [{"text": "整个过程历时三至六个月，视气候与管理精度而定，终产物呈深褐色、质地疏松、具森林土壤特有清香，即标志腐熟完成。", "target_word": "清香", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "雨后的花园里有淡淡的清香。", "target_word": "清香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子里飘出一阵茶叶的清香。", "target_word": "清香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开窗户，桂花的清香飘进了房间。", "target_word": "清香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新米煮熟后，满屋都是米饭的清香。", "target_word": "清香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种绿茶闻起来有一股清香，喝起来很甜。", "target_word": "清香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "竹叶散发着清香，让人心情平静。", "target_word": "清香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢荷花的清香，常常去池边看花。", "target_word": "清香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚洗过的衣服带着一点清香。", "target_word": "清香", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的风里，青草的清香让人想出门。", "target_word": "清香", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股清香", "label": "量词搭配"}, {"form": "一缕清香", "label": "量词搭配"}, {"form": "清香扑鼻", "label": "四字格"}], "register": "书面", "sense_fingerprint": "清香：清淡而令人愉悦的香味（花、茶、草木等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88bcbd-fe2c-4dba-ab0f-04f6851766bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13128, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "清香", "is_correct": true, "explanation": "本词，指清淡而令人愉悦的香味。"}, {"text": "轻响", "is_correct": false, "explanation": "轻响（qīng xiǎng）与清香（qīng xiāng）第二个音节声调不同（第三声与第一声），意思是轻微的声响。"}, {"text": "清鲜", "is_correct": false, "explanation": "清鲜（qīng xiān）与清香（qīng xiāng）末尾韵母不同（an 与 ang），意思是清爽新鲜。"}, {"text": "倾向", "is_correct": false, "explanation": "倾向（qīng xiàng）与清香（qīng xiāng）第二个音节声调不同（第四声与第一声），意思是心理或行为上的偏向。"}], "explanations": {"清香": "本词，指清淡而令人愉悦的香味。", "轻响": "轻响（qīng xiǎng）与清香（qīng xiāng）第二个音节声调不同（第三声与第一声），意思是轻微的声响。", "清鲜": "清鲜（qīng xiān）与清香（qīng xiāng）末尾韵母不同（an 与 ang），意思是清爽新鲜。", "倾向": "倾向（qīng xiàng）与清香（qīng xiāng）第二个音节声调不同（第四声与第一声），意思是心理或行为上的偏向。"}, "sentence_index": null, "correct_answer": "清香"}, "level_3": {"options": [{"text": "清香", "is_correct": true, "explanation": "清香指特有的清淡香味，正是腐熟完成的标志。"}, {"text": "硬度", "is_correct": false, "explanation": "语义：前文说终产物“质地疏松”，“硬度”与之矛盾，不能作为腐熟完成的特征。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：“噪音”是声音，不能被闻到，与句中说的气味特征不符。"}, {"text": "酸臭味", "is_correct": false, "explanation": "语义：森林土壤的气味清淡宜人，“酸臭味”与之相反，不会是腐熟完成的标志。"}], "explanations": {"清香": "清香指特有的清淡香味，正是腐熟完成的标志。", "硬度": "语义：前文说终产物“质地疏松”，“硬度”与之矛盾，不能作为腐熟完成的特征。", "噪音": "语义：“噪音”是声音，不能被闻到，与句中说的气味特征不符。", "酸臭味": "语义：森林土壤的气味清淡宜人，“酸臭味”与之相反，不会是腐熟完成的标志。"}, "sentence_index": 0, "correct_answer": "清香"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑完步，身上一股清香，熏得大家直躲。", "explanation": "这里应该用〈汗味〉。清香指清淡宜人的香味，运动后的汗臭气味要说汗味，不能说清香。"}, {"text": "屋子里满是清香，呛得人直咳嗽。", "explanation": "这里应该用〈烟味〉。清香指清淡宜人的香味，不能用来形容呛人的烟气。"}, {"text": "鱼市里全是清香。", "explanation": "这里应该用〈腥味〉。清香指清淡宜人的香味，鱼市的气味要说腥味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "清香", "is_correct": true, "explanation": "清香指清淡宜人的香味，竹叶散发的正是这种气味，与“让人心情平静”一致。"}, {"text": "寒气", "is_correct": false, "explanation": "语义：“寒气”是冷的气息，不是香味，与“让人心情平静”的感受相反。"}, {"text": "铁锈味", "is_correct": false, "explanation": "语义：铁锈味令人不快，与“让人心情平静”矛盾。"}, {"text": "电流", "is_correct": false, "explanation": "搭配：“散发”不能和“电流”搭配，电流不是能被散发出来的气味。"}], "explanations": {"清香": "清香指清淡宜人的香味，竹叶散发的正是这种气味，与“让人心情平静”一致。", "寒气": "语义：“寒气”是冷的气息，不是香味，与“让人心情平静”的感受相反。", "铁锈味": "语义：铁锈味令人不快，与“让人心情平静”矛盾。", "电流": "搭配：“散发”不能和“电流”搭配，电流不是能被散发出来的气味。"}, "sentence_index": 6, "correct_answer": "清香"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冰箱里的剩菜馊了，屋里一股清香。", "explanation": "这里应该用〈馊味〉。清香指清淡宜人的香味，剩菜变质的气味要说馊味。"}, {"text": "医院的清香很刺鼻。", "explanation": "这里应该用〈消毒水味〉。清香是清淡宜人的香味，不能用“刺鼻”来形容。"}, {"text": "下水道飘出一阵清香。", "explanation": "这里应该用〈臭气〉。清香指清淡宜人的香味，下水道的气味令人厌恶，应说臭气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗外飘来一个清香，是桂花开了。", "corrected_sentence": "窗外飘来一阵清香，是桂花开了。", "error_description": "量词错误：“清香”作名词时用“阵”或“股”，不能用“个”，应改为“一阵清香”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "茶壶里飘出了一个清香，大家都围了过来。", "corrected_sentence": "茶壶里飘出了一阵清香，大家都围了过来。", "error_description": "量词错误：“清香”作名词时用“阵”或“股”，不能用“个”，应改为“一阵清香”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
