INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13129, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示在程度上大大超过某事物", "primary_collocate": null, "pronunciation": "yuǎn", "ipa": "ɥɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "他的速度远比我快。", "target_word": "远", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次考试远比上次难。", "target_word": "远", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今年的客人远多于去年。", "target_word": "远", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "现在的手机功能远超十年前的电脑。", "target_word": "远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个牌子的手机远比其他品牌贵。", "target_word": "远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的价格远高于别的店。", "target_word": "远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北京的人口远大于这个小城。", "target_word": "远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实际的情况远比我们想的复杂。", "target_word": "远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他花的时间远超我的想象，真让人吃惊。", "target_word": "远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法的效果远好于以前的办法。", "target_word": "远", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "远远", "label": "重叠"}, {"form": "遠", "label": "繁体"}], "register": "中性", "sense_fingerprint": "程度上大大超过，常说远比、远超", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40f895ac-25cd-46d5-9ed8-238277971775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13129, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "远", "is_correct": true, "explanation": "远：程度上大大超过，常说“远比”“远超”。"}, {"text": "院", "is_correct": false, "explanation": "yuàn（第四声）与 yuǎn（第三声）声调不同，意思是院子。"}, {"text": "怨", "is_correct": false, "explanation": "yuàn（第四声）与 yuǎn（第三声）声调不同，意思是怨恨。"}, {"text": "园", "is_correct": false, "explanation": "yuán（第二声）与 yuǎn（第三声）声调不同，意思是花园。"}, {"text": "圆", "is_correct": false, "explanation": "yuán（第二声）与 yuǎn（第三声）声调不同，意思是圆形。"}], "explanations": {"远": "远：程度上大大超过，常说“远比”“远超”。", "院": "yuàn（第四声）与 yuǎn（第三声）声调不同，意思是院子。", "怨": "yuàn（第四声）与 yuǎn（第三声）声调不同，意思是怨恨。", "园": "yuán（第二声）与 yuǎn（第三声）声调不同，意思是花园。", "圆": "yuán（第二声）与 yuǎn（第三声）声调不同，意思是圆形。"}, "sentence_index": null, "correct_answer": "远"}, "level_3": {"options": [{"text": "远", "is_correct": true, "explanation": "远：程度大大超过，与“比我快”搭配，句意通顺。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”不能直接放在“比”字句前，不说“很比我快”。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”不能直接放在“比”字句前，不说“非常比我快”。"}, {"text": "太", "is_correct": false, "explanation": "语法：“太”不能直接修饰“比”字短语，不说“太比我快”。"}], "explanations": {"远": "远：程度大大超过，与“比我快”搭配，句意通顺。", "很": "语法：“很”不能直接放在“比”字句前，不说“很比我快”。", "非常": "语法：“非常”不能直接放在“比”字句前，不说“非常比我快”。", "太": "语法：“太”不能直接修饰“比”字短语，不说“太比我快”。"}, "sentence_index": 0, "correct_answer": "远"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个办法的效果远好一点。", "explanation": "这里应该用〈稍〉。远表示程度大大超过，与“一点”表示的微小差距矛盾，应说“稍好一点”。"}, {"text": "他的水平远比我高一点。", "explanation": "这里应该用〈只〉。远表示程度大大超过，与“一点”表示的微小差距矛盾，应说“只比我高一点”。"}, {"text": "两人的差距远小一点。", "explanation": "这里应该用〈略〉。远表示程度大大超过，与“一点”表示的轻微差别矛盾，应说“略小一点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13129, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "远", "is_correct": true, "explanation": "远：程度上大大超过，常说“远比”“远超”。"}, {"text": "元", "is_correct": false, "explanation": "yuán（第二声）与 yuǎn（第三声）声调不同，意思是钱的单位。"}, {"text": "员", "is_correct": false, "explanation": "yuán（第二声）与 yuǎn（第三声）声调不同，意思是人员。"}, {"text": "冤", "is_correct": false, "explanation": "yuān（第一声）与 yuǎn（第三声）声调不同，意思是冤枉。"}, {"text": "原", "is_correct": false, "explanation": "yuán（第二声）与 yuǎn（第三声）声调不同，意思是原来。"}], "explanations": {"远": "远：程度上大大超过，常说“远比”“远超”。", "元": "yuán（第二声）与 yuǎn（第三声）声调不同，意思是钱的单位。", "员": "yuán（第二声）与 yuǎn（第三声）声调不同，意思是人员。", "冤": "yuān（第一声）与 yuǎn（第三声）声调不同，意思是冤枉。", "原": "yuán（第二声）与 yuǎn（第三声）声调不同，意思是原来。"}, "sentence_index": null, "correct_answer": "远"}, "level_3": {"options": [{"text": "远", "is_correct": true, "explanation": "远：程度大大超过，与“北京的人口大于这个小城”搭配，句意通顺。"}, {"text": "挺", "is_correct": false, "explanation": "语法：“挺”修饰形容词，不能修饰“大于”这类比较说法，不说“挺大于”。"}, {"text": "真", "is_correct": false, "explanation": "语法：“真”表示感叹，修饰形容词，不能修饰“大于”，不说“真大于”。"}, {"text": "特别", "is_correct": false, "explanation": "语法：“特别”修饰形容词，不能修饰“大于”，不说“特别大于”。"}], "explanations": {"远": "远：程度大大超过，与“北京的人口大于这个小城”搭配，句意通顺。", "挺": "语法：“挺”修饰形容词，不能修饰“大于”这类比较说法，不说“挺大于”。", "真": "语法：“真”表示感叹，修饰形容词，不能修饰“大于”，不说“真大于”。", "特别": "语法：“特别”修饰形容词，不能修饰“大于”，不说“特别大于”。"}, "sentence_index": 6, "correct_answer": "远"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校离我家很远，每天要坐一个小时车。", "explanation": "这里的远指距离长，与“近”相对，不表示程度大大超过。"}, {"text": "他和我家的亲戚关系很远，平时不来往。", "explanation": "这里的远指亲属关系疏远，不表示程度大大超过。"}, {"text": "远处的山上有一座寺庙。", "explanation": "这里的远指地点距离长，不表示程度大大超过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13129, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆车的油耗低远于同类车型。", "corrected_sentence": "这辆车的油耗远低于同类车型。", "error_description": "语序错误：“远”修饰“低”，应放在“低”前，说“远低于”，不能说“低远于”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13129, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的成绩远我好。", "corrected_sentence": "她的成绩远比我好。", "error_description": "漏字错误：比较句“远比”中的“比”不能省，应说“远比我好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5902e340-2bee-43e1-992e-695af26e6eca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
