INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13130, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指水流发源的地方；比喻事物的根源或起源。", "primary_collocate": null, "pronunciation": "yuán tóu", "ipa": "ɥɛn˧˥ tʰoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "首先，它从源头显著减少垃圾清运量，缓解市政处理压力，是公民践行环境责任的具体表达。", "target_word": "源头", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这条河的源头在高高的山上。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长江的源头在青藏高原。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要解决问题，先要找到问题的源头。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水污染的源头是上游的工厂。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们沿着小溪向上走，想找到溪水的源头。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谣言的源头很难查清楚。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种思想的源头可以追到两千年前。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要把污染的源头管好。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水清不清，要看源头干不干净。", "target_word": "源头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "源頭", "label": "繁体"}, {"form": "源头活水", "label": "四字格"}, {"form": "一个源头", "label": "量词搭配"}], "register": "书面", "sense_fingerprint": "源头：河流发源之处；比喻事物的根源、起源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88bcbd-fe2c-4dba-ab0f-04f6851766bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13130, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "源头", "is_correct": true, "explanation": "源头指事情的起始之处，这里说垃圾从源头减少，与句意相符。"}, {"text": "结局", "is_correct": false, "explanation": "语义：“结局”是结果，不能作为减少垃圾的起点，与“从……减少”矛盾。"}, {"text": "大气", "is_correct": false, "explanation": "语义：大气不是产生垃圾的地方，“从大气减少垃圾清运量”说不通。"}, {"text": "利润", "is_correct": false, "explanation": "搭配：“利润”不能作为减少垃圾的来源，“从利润减少垃圾清运量”搭配不当。"}], "explanations": {"源头": "源头指事情的起始之处，这里说垃圾从源头减少，与句意相符。", "结局": "语义：“结局”是结果，不能作为减少垃圾的起点，与“从……减少”矛盾。", "大气": "语义：大气不是产生垃圾的地方，“从大气减少垃圾清运量”说不通。", "利润": "搭配：“利润”不能作为减少垃圾的来源，“从利润减少垃圾清运量”搭配不当。"}, "sentence_index": 0, "correct_answer": "源头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电影院的源头在大厅左边，走过去就能出去。", "explanation": "这里应该用〈出口〉。源头指水流发源之处或事物的根源，建筑的出入口要说出口，不能说源头。"}, {"text": "这次比赛的源头很精彩，球迷们都兴奋起来。", "explanation": "这里应该用〈开端〉。源头指事物的来源，比赛刚开始的阶段要说开端，不能说源头。"}, {"text": "这场雨的源头很大，下了一整天。", "explanation": "这里应该用〈雨势〉。源头指事物的来源，雨下得大还是小要说雨势，不能说源头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13130, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "源头", "is_correct": true, "explanation": "源头指事情的起始之处，谣言的起始之处难以查清，符合句意。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”不能说“查清楚”，“谣言的速度很难查清楚”搭配不当。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能被查清楚，句子不成立。"}, {"text": "重量", "is_correct": false, "explanation": "语义：谣言没有重量，无法说它的重量很难查清楚。"}], "explanations": {"源头": "源头指事情的起始之处，谣言的起始之处难以查清，符合句意。", "速度": "搭配：“速度”不能说“查清楚”，“谣言的速度很难查清楚”搭配不当。", "颜色": "搭配：“颜色”不能被查清楚，句子不成立。", "重量": "语义：谣言没有重量，无法说它的重量很难查清楚。"}, "sentence_index": 6, "correct_answer": "源头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "句子的源头要加标点。", "explanation": "这里应该用〈句末〉。源头指事物的来源，标点要加在句子末尾，应说句末，不能说源头。"}, {"text": "这次会议的源头很长，大家都累了。", "explanation": "这里应该用〈时长〉。源头指事物的来源，会议持续的时间要说时长，不能说源头。"}, {"text": "这条河的源头在大海，很长很长。", "explanation": "这里应该用〈终点〉。源头指水流发源之处，流入大海的地方是河流的终点，不能说源头在大海。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在河边找到了一条源头，水很清。", "corrected_sentence": "我在河边找到了一个源头，水很清。", "error_description": "量词错误：“源头”作名词时用“个”，不能用长条形事物的量词“条”，应改为“一个源头”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "调查人员终于找到了事故的一把源头。", "corrected_sentence": "调查人员终于找到了事故的一个源头。", "error_description": "量词错误：“源头”作名词时用“个”，“把”多用于有柄的器具，不能用来计量源头，应改为“一个源头”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '30e01f3b-6813-4633-bc7a-b4a3994fd854') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
