INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13131, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13131, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "将居民日常生活产生的废弃物集中收集并运输到处理场所的过程。", "primary_collocate": null, "pronunciation": "lā jī qīng yùn", "ipa": "la˥ tɕi˥ tɕʰiŋ˥ yn˥˩", "syllable_count": 4, "sentences": [{"text": "首先，它从源头显著减少垃圾清运量，缓解市政处理压力，是公民践行环境责任的具体表达。", "target_word": "垃圾清运", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们小区的垃圾清运每天早上六点开始。", "target_word": "垃圾清运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雪以后，垃圾清运变慢了。", "target_word": "垃圾清运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市政部门负责全市的垃圾清运工作。", "target_word": "垃圾清运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的垃圾清运很及时。", "target_word": "垃圾清运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "垃圾清运不及时，街道就会很脏。", "target_word": "垃圾清运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年的时候，垃圾清运也不停。", "target_word": "垃圾清运", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了做好垃圾清运，工人们半夜就起床了。", "target_word": "垃圾清运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾清运一停，楼下马上就有味道了。", "target_word": "垃圾清运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的垃圾清运做得很好。", "target_word": "垃圾清运", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "垃圾清運", "label": "繁体"}], "register": "中性", "sense_fingerprint": "垃圾收集并运往处理场所的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4307e-1e69-472e-8d40-ee700134ec59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13131, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "垃圾清运", "is_correct": true, "explanation": "正确：指收集并运走居民垃圾的过程，可与“减少……量”搭配，且符合“从源头减量”的语境。"}, {"text": "公园绿地", "is_correct": false, "explanation": "语义：减少公园绿地与“从源头减量”“践行环境责任”的语境相悖。"}, {"text": "图书借阅", "is_correct": false, "explanation": "语义：借阅量与“缓解市政处理压力”和环境责任无关。"}, {"text": "游客接待", "is_correct": false, "explanation": "搭配：“减少”虽可接“接待量”，但与前文环境处理语境不搭。"}], "explanations": {"垃圾清运": "正确：指收集并运走居民垃圾的过程，可与“减少……量”搭配，且符合“从源头减量”的语境。", "公园绿地": "语义：减少公园绿地与“从源头减量”“践行环境责任”的语境相悖。", "图书借阅": "语义：借阅量与“缓解市政处理压力”和环境责任无关。", "游客接待": "搭配：“减少”虽可接“接待量”，但与前文环境处理语境不搭。"}, "sentence_index": 0, "correct_answer": "垃圾清运"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "楼下堆满了垃圾清运，臭味一直飘到楼上。", "explanation": "清运是把垃圾运走的动作或过程，不是堆在地上的废物本身，所以不能说“堆满”。"}, {"text": "这条河被垃圾清运淹没了。", "explanation": "清运是把垃圾运走的过程，不能指淹没河道的垃圾本身。"}, {"text": "他是个很认真的垃圾清运。", "explanation": "指人时应说〈垃圾清运工〉。“垃圾清运”表示行为，不能直接用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13131, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "垃圾清运", "is_correct": true, "explanation": "正确：指垃圾收运的工作，可以在“过年的时候……也不停”中作主语。"}, {"text": "春节", "is_correct": false, "explanation": "语义：春节是节日，不是可以“不停”的工作或活动。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子是食物，不能“不停”运转，与句意不合。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“礼物也不停”搭配不当，礼物不是持续进行的过程。"}], "explanations": {"垃圾清运": "正确：指垃圾收运的工作，可以在“过年的时候……也不停”中作主语。", "春节": "语义：春节是节日，不是可以“不停”的工作或活动。", "饺子": "语义：饺子是食物，不能“不停”运转，与句意不合。", "礼物": "搭配：“礼物也不停”搭配不当，礼物不是持续进行的过程。"}, "sentence_index": 6, "correct_answer": "垃圾清运"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天都对书架进行垃圾清运。", "explanation": "清运的对象必须是垃圾，不能用来指整理书架。"}, {"text": "这首歌的垃圾清运很好听。", "explanation": "清运是把垃圾运走的过程，不能用来形容歌曲。"}, {"text": "我们明天去垃圾清运玩儿。", "explanation": "清运是过程，不是地点，不能用来指游玩的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13131, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们小区每天早上把垃圾清运很及时。", "corrected_sentence": "我们小区每天早上垃圾清运很及时。", "error_description": "误用“把”字句：“把”字句需要动作补足语（如“把垃圾清运完”），此处“把垃圾清运”后只接形容词，应删去“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13131, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只垃圾清运很及时。", "corrected_sentence": "这次垃圾清运很及时。", "error_description": "量词错误：垃圾清运是一次行为，应说“这次”，不能用量词“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
