INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13132, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指城市管理事务，包括公共交通、环境卫生、公共设施等政府职能。", "primary_collocate": null, "pronunciation": "shì zhèng", "ipa": "ʂɻ̩˥˩ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "首先，它从源头显著减少垃圾清运量，缓解市政处理压力，是公民践行环境责任的具体表达。", "target_word": "市政", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "市政部门正在修这条路。", "target_word": "市政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在市政部门工作了十年。", "target_word": "市政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市政工作包括修路、扫街和管理公园。", "target_word": "市政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥是市政的新项目。", "target_word": "市政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市民可以给市政部门提意见。", "target_word": "市政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市政人员每天早上打扫街道。", "target_word": "市政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路灯坏了，请拨打市政热线。", "target_word": "市政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市政建设让城市变得更方便。", "target_word": "市政", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她学的是市政管理，以后想为城市工作。", "target_word": "市政", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "城市管理事务及政府职能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4307e-1e69-472e-8d40-ee700134ec59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13132, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "市政", "is_correct": true, "explanation": "正确：指城市管理事务，即本题释义所说的市政。"}, {"text": "时政", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是时事政治。"}, {"text": "施政", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是施行政务。"}, {"text": "市镇", "is_correct": false, "explanation": "zhèn 与 zhèng 韵尾不同，意思是城镇。"}], "explanations": {"市政": "正确：指城市管理事务，即本题释义所说的市政。", "时政": "shí（第二声）与 shì（第四声）声调不同，意思是时事政治。", "施政": "shī（第一声）与 shì（第四声）声调不同，意思是施行政务。", "市镇": "zhèn 与 zhèng 韵尾不同，意思是城镇。"}, "sentence_index": null, "correct_answer": "市政"}, "level_3": {"options": [{"text": "市政", "is_correct": true, "explanation": "正确：“市政处理压力”指城市管理事务中的处理工作，与语境吻合。"}, {"text": "课堂", "is_correct": false, "explanation": "语义：课堂与城市废弃物处理无关，“课堂处理压力”不成立。"}, {"text": "个人", "is_correct": false, "explanation": "语义：个人不是城市层面的管理系统，与“缓解……处理压力”的公共语境不符。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋与城市废弃物处理的语境无关。"}], "explanations": {"市政": "正确：“市政处理压力”指城市管理事务中的处理工作，与语境吻合。", "课堂": "语义：课堂与城市废弃物处理无关，“课堂处理压力”不成立。", "个人": "语义：个人不是城市层面的管理系统，与“缓解……处理压力”的公共语境不符。", "海洋": "语义：海洋与城市废弃物处理的语境无关。"}, "sentence_index": 0, "correct_answer": "市政"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我住在市政，离公司很近。", "explanation": "这里应该用〈市区〉。市政指城市管理事务，不指地点。"}, {"text": "市政应该遵守交通规则。", "explanation": "这里应该用〈市民〉。市政指管理事务，不是遵守规则的人。"}, {"text": "他是一位市政，每天骑车上班。", "explanation": "指人时应说〈市政人员〉。“市政”本身不表示人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13132, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市政", "is_correct": true, "explanation": "正确：“市政人员每天早上打扫街道”中，市政指城市管理事务，与打扫街道相符。"}, {"text": "农业", "is_correct": false, "explanation": "语义：农业人员不负责打扫街道，与句意不合。"}, {"text": "医疗", "is_correct": false, "explanation": "语义：医疗人员的工作与打扫街道无关。"}, {"text": "外交", "is_correct": false, "explanation": "语义：外交人员的工作与每天打扫街道无关。"}], "explanations": {"市政": "正确：“市政人员每天早上打扫街道”中，市政指城市管理事务，与打扫街道相符。", "农业": "语义：农业人员不负责打扫街道，与句意不合。", "医疗": "语义：医疗人员的工作与打扫街道无关。", "外交": "语义：外交人员的工作与每天打扫街道无关。"}, "sentence_index": 6, "correct_answer": "市政"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们坐市政去上班，很方便。", "explanation": "这里应该用〈公交车〉。市政是城市管理事务，不是交通工具。"}, {"text": "他在市政里养了一只猫。", "explanation": "市政指管理事务，不是可以住人或养动物的地方，不能说“在市政里”。"}, {"text": "这家餐厅的市政很好吃。", "explanation": "市政指管理事务，不是食物，不能用来形容味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13132, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很市政部门负责管理公园。", "corrected_sentence": "市政部门负责管理公园。", "error_description": "修饰错误：副词“很”不能修饰定语“市政”，应直接说“市政部门”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个项目很市政。", "corrected_sentence": "这个项目属于市政。", "error_description": "词性错误：市政作名词，一般不能直接被“很”修饰作谓语；应说“属于市政”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
