INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13134, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13134, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "实行、实践，指把想法或承诺变成实际行动。", "primary_collocate": null, "pronunciation": "jiàn xíng", "ipa": "tɕjɛn˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "首先，它从源头显著减少垃圾清运量，缓解市政处理压力，是公民践行环境责任的具体表达。", "target_word": "践行", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他说到做到，一直在践行自己的诺言。", "target_word": "践行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要践行绿色生活的理念。", "target_word": "践行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用实际行动践行了志愿者的承诺。", "target_word": "践行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司承诺减少用纸，现在正在践行。", "target_word": "践行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要践行节约粮食的理念，就从吃完饭菜开始。", "target_word": "践行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常说，学习要践行，不能只说不做。", "target_word": "践行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他十年来一直践行低碳出行的理念。", "target_word": "践行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班同学践行了环保的约定。", "target_word": "践行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "真正的爱国，要在生活中践行。", "target_word": "践行", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "践行了", "label": "完成体"}, {"form": "践行着", "label": "持续体"}, {"form": "践行过", "label": "经历体"}, {"form": "踐行", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把想法或承诺付诸实际行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4307e-1e69-472e-8d40-ee700134ec59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13134, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "践行", "is_correct": true, "explanation": "正确：践行 jiàn xíng，意为把想法或承诺变成实际行动。"}, {"text": "现行", "is_correct": false, "explanation": "xiàn（第四声）与 jiàn（第四声）声母不同（x 对 j），现行意思是当前施行的。"}, {"text": "现形", "is_correct": false, "explanation": "xiàn（第四声）与 jiàn（第四声）声母不同（x 对 j），现形意思是显露原形。"}, {"text": "减刑", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）声调不同，后字 xíng 相同，减刑意思是减少刑期。"}], "explanations": {"践行": "正确：践行 jiàn xíng，意为把想法或承诺变成实际行动。", "现行": "xiàn（第四声）与 jiàn（第四声）声母不同（x 对 j），现行意思是当前施行的。", "现形": "xiàn（第四声）与 jiàn（第四声）声母不同（x 对 j），现形意思是显露原形。", "减刑": "jiǎn（第三声）与 jiàn（第四声）声调不同，后字 xíng 相同，减刑意思是减少刑期。"}, "sentence_index": null, "correct_answer": "践行"}, "level_3": {"options": [{"text": "践行", "is_correct": true, "explanation": "正确：“践行”指把环境责任付诸实际行动，与“具体表达”相符。"}, {"text": "违背", "is_correct": false, "explanation": "语义：“违背”是违反，与“环境责任的具体表达”的肯定含义相反。"}, {"text": "回避", "is_correct": false, "explanation": "语义：“回避”是躲开，与“公民……的具体表达”的积极语义不符。"}, {"text": "干", "is_correct": false, "explanation": "语域：“干”是口语词，与这句书面语的语域不搭。"}], "explanations": {"践行": "正确：“践行”指把环境责任付诸实际行动，与“具体表达”相符。", "违背": "语义：“违背”是违反，与“环境责任的具体表达”的肯定含义相反。", "回避": "语义：“回避”是躲开，与“公民……的具体表达”的积极语义不符。", "干": "语域：“干”是口语词，与这句书面语的语域不搭。"}, "sentence_index": 0, "correct_answer": "践行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师让我们在农田里践行种菜的技术。", "explanation": "这里应该用〈实践〉。“践行”多指把理念、承诺付诸行动，具体的操作技术要用“实践”。"}, {"text": "公司终于践行了那份合同。", "explanation": "这里应该用〈履行〉。合同属于法律上的义务，要说“履行”；“践行”用于理念、承诺、诺言。"}, {"text": "他很快就践行了作业。", "explanation": "这里应该用〈完成〉。作业是具体的学习任务，要说“完成”；“践行”指把想法、承诺变成实际行动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13134, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "践行", "is_correct": true, "explanation": "正确：“践行”指把道理落实到行动中，与“不能只说不做”相呼应。"}, {"text": "空谈", "is_correct": false, "explanation": "语义：“空谈”指只说不做，与“不能只说不做”的要求正好相反。"}, {"text": "夸耀", "is_correct": false, "explanation": "语义：“夸耀”是炫耀，与学习需要落实的行动无关，句意不通。"}, {"text": "扮演", "is_correct": false, "explanation": "搭配：“扮演”要带角色或人物作宾语，不能说“学习要扮演”。"}], "explanations": {"践行": "正确：“践行”指把道理落实到行动中，与“不能只说不做”相呼应。", "空谈": "语义：“空谈”指只说不做，与“不能只说不做”的要求正好相反。", "夸耀": "语义：“夸耀”是炫耀，与学习需要落实的行动无关，句意不通。", "扮演": "搭配：“扮演”要带角色或人物作宾语，不能说“学习要扮演”。"}, "sentence_index": 6, "correct_answer": "践行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "消防员践行了救援任务。", "explanation": "这里应该用〈执行〉。“践行”多指把理念、承诺付诸行动，救援任务要说“执行”。"}, {"text": "双方践行了友好的会谈。", "explanation": "这里应该用〈进行〉。“践行”用于理念、承诺，会谈要说“进行”。"}, {"text": "学校践行了一次校园活动。", "explanation": "这里应该用〈开展〉。“践行”不用于一次具体的活动，活动要说“开展”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她已经践行了了她的承诺。", "corrected_sentence": "她已经践行了她的承诺。", "error_description": "错误：“了”重复出现。正确形式是“践行了”，只用一个“了”表示动作已经完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经把把承诺践行了。", "corrected_sentence": "他已经把承诺践行了。", "error_description": "错误：“把”重复出现。正确形式是“把承诺践行了”，“把”字只用一次，后接宾语再接动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
