INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13136, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指获得的利益或成果。", "primary_collocate": null, "pronunciation": "suǒ dé", "ipa": "suo˨˩ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "其次，所得有机肥用于家庭园艺，可改良土壤团粒结构，提升保水保肥能力，减少对化学肥料的依赖，形成“厨房—土壤—餐桌”的营养回路。", "target_word": "所得", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这次出差，他的所得比想象的多。", "target_word": "所得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民把一年的所得存进了银行。", "target_word": "所得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作一天，他的所得只有一百元。", "target_word": "所得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次旅行，我最大的所得是交了很多朋友。", "target_word": "所得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把读书的所得都写在日记里。", "target_word": "所得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把一生的所得都捐给了学校。", "target_word": "所得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管所得多少，他都很满意。", "target_word": "所得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家按每个人的所得来收税。", "target_word": "所得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次学习，他的所得不少。", "target_word": "所得", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "通过劳动或努力获得的利益、成果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ad4307e-1e69-472e-8d40-ee700134ec59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13136, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所得", "is_correct": true, "explanation": "正确：“所得”此处指（堆肥）得到的，修饰有机肥。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费与有机肥、园艺无关，无法修饰有机肥。"}, {"text": "损耗", "is_correct": false, "explanation": "语义：“损耗”指消耗、减少，与“改良土壤、提升保肥能力”的积极作用相反。"}, {"text": "费用", "is_correct": false, "explanation": "搭配：“费用”指花出去的钱，不能修饰可以用于园艺的有机肥。"}], "explanations": {"所得": "正确：“所得”此处指（堆肥）得到的，修饰有机肥。", "学费": "语义：学费与有机肥、园艺无关，无法修饰有机肥。", "损耗": "语义：“损耗”指消耗、减少，与“改良土壤、提升保肥能力”的积极作用相反。", "费用": "搭配：“费用”指花出去的钱，不能修饰可以用于园艺的有机肥。"}, "sentence_index": 0, "correct_answer": "所得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次投资，他的所得惨重。", "explanation": "这里应该用〈亏损〉。“惨重”修饰的是负面结果，“所得”指获得的收益，不能说惨重。"}, {"text": "这次出差，他拿到了一颗所得。", "explanation": "这里应该用〈笔〉。“所得”多指收益，用“笔”计量；“颗”用于粒状物，不能计量所得。"}, {"text": "这次聚会，他的所得很快乐。", "explanation": "这里应该说〈他很快乐〉。“快乐”形容人的心情，不能用来修饰“所得”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13136, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所得", "is_correct": true, "explanation": "正确：“所得”指老人一生靠劳动获得的积蓄或收益，可以捐给学校。"}, {"text": "债务", "is_correct": false, "explanation": "语义：“债务”是欠别人的钱，不能拿来捐给学校。"}, {"text": "病痛", "is_correct": false, "explanation": "语义：“病痛”是身体的痛苦，不是可以捐出去的东西，句意不通。"}, {"text": "眼泪", "is_correct": false, "explanation": "搭配：“捐”的对象是财物，不能说“捐眼泪”。"}], "explanations": {"所得": "正确：“所得”指老人一生靠劳动获得的积蓄或收益，可以捐给学校。", "债务": "语义：“债务”是欠别人的钱，不能拿来捐给学校。", "病痛": "语义：“病痛”是身体的痛苦，不是可以捐出去的东西，句意不通。", "眼泪": "搭配：“捐”的对象是财物，不能说“捐眼泪”。"}, "sentence_index": 6, "correct_answer": "所得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次投资，他遭受了巨大的所得。", "explanation": "这里应该用〈损失〉。“遭受”搭配负面结果，“所得”指通过努力获得的收益，不能遭受。"}, {"text": "她一直默默承受所得。", "explanation": "这里应该用〈痛苦〉。承受的是痛苦，“所得”不能被承受。"}, {"text": "这笔欠款成了他的所得。", "explanation": "这里应该用〈负担〉。欠款是需要偿还的负担，不是通过努力获得的收益。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这个月拿到了一条不小的所得。", "corrected_sentence": "他这个月拿到了一笔不小的所得。", "error_description": "错误：“所得”前的量词“条”不当，应为“笔”。“条”多用于长条状物或消息，不用于计量收入。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他靠努力换来了一块可观的所得。", "corrected_sentence": "他靠努力换来了一笔可观的所得。", "error_description": "错误：“所得”前的量词“块”不当，应为“笔”。“笔”是计量款项、收入的常用量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec1cc42-6627-400b-af07-ddceb815545b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
