INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13142, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "亲眼看见某件事情的发生。", "primary_collocate": null, "pronunciation": "mù jī", "ipa": "mu˥˩ tɕi˥", "syllable_count": 2, "sentences": [{"text": "更深层次而言，堆肥行为本身构成一种生态认知的具身化训练：当人们亲手将果皮菜叶投入发酵箱，目击其从腐败到重生的蜕变，便不得不重新审视“废弃物”的定义边界——所谓垃圾，或许只是错置位置的资源。", "target_word": "目击", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他在路口目击了一场车祸。", "target_word": "目击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察正在找目击这起事故的人。", "target_word": "目击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上，我目击了小偷翻墙。", "target_word": "目击", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位老人目击了整个抢劫过程。", "target_word": "目击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有目击事情发生，所以不能作证。", "target_word": "目击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在海边目击了一次海上救援。", "target_word": "目击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当时就在现场，目击了爆炸的全过程。", "target_word": "目击", "complexity_tier": "T3", "furigana": "tā dāng shí jiù zài xiàn chǎng, mù jī le bào zhà de quán guò chéng.", "sentence_source": "generated"}, {"text": "邻居目击小偷从窗户爬进了他家。", "target_word": "目击", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己目击的经过都告诉了警察。", "target_word": "目击", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "目击了", "label": "体标"}, {"form": "目击过", "label": "体标"}, {"form": "目击者", "label": "复合"}, {"form": "目擊", "label": "繁体"}], "register": "书面", "sense_fingerprint": "亲眼看见某件事情发生，多用于事故、案件等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1643dd7e-39f0-4480-b4fc-1a9f2c8ab0c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13142, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "目击", "is_correct": true, "explanation": "目击：亲眼看见事情发生。此处指亲眼看到堆肥中物质从腐败到重生的蜕变过程。"}, {"text": "扼杀", "is_correct": false, "explanation": "语义：「扼杀」指压制使其消亡，与「从腐败到重生」的转化以及后文「重新审视」的因果不符。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：「购买」的宾语是商品，不能说购买一个蜕变的过程。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：「嘲笑」是讥讽他人，与人们认真投入堆肥、重新审视废弃物定义的语境不符。"}], "explanations": {"目击": "目击：亲眼看见事情发生。此处指亲眼看到堆肥中物质从腐败到重生的蜕变过程。", "扼杀": "语义：「扼杀」指压制使其消亡，与「从腐败到重生」的转化以及后文「重新审视」的因果不符。", "购买": "搭配：「购买」的宾语是商品，不能说购买一个蜕变的过程。", "嘲笑": "语义：「嘲笑」是讥讽他人，与人们认真投入堆肥、重新审视废弃物定义的语境不符。"}, "sentence_index": 0, "correct_answer": "目击"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我去医院目击生病的奶奶。", "explanation": "这里应该用〈看望〉。看望是去探问人，目击的宾语必须是正在发生的事情，不能是人。"}, {"text": "我在屋里目击了他们的吵架声。", "explanation": "这里应该用〈听到〉。目击靠视觉，只能用于亲眼看见的事情，不能用来表示听见的声音。"}, {"text": "我常常目击未来的生活。", "explanation": "这里应该用〈想象〉。目击指亲眼看见已经发生的事，未来尚未发生，不能被目击。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13142, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "目击", "is_correct": true, "explanation": "目击：亲眼看见事情发生。此处指孩子们亲眼看到海上救援的发生。"}, {"text": "支付", "is_correct": false, "explanation": "搭配：「支付」的宾语是费用或款项，不能说支付一次救援。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：「收藏」的宾语是物品，救援这种事件不能被收藏。"}, {"text": "咒骂", "is_correct": false, "explanation": "语义：「咒骂」是骂人，与孩子们在海边见证救人的情景不符。"}], "explanations": {"目击": "目击：亲眼看见事情发生。此处指孩子们亲眼看到海上救援的发生。", "支付": "搭配：「支付」的宾语是费用或款项，不能说支付一次救援。", "收藏": "搭配：「收藏」的宾语是物品，救援这种事件不能被收藏。", "咒骂": "语义：「咒骂」是骂人，与孩子们在海边见证救人的情景不符。"}, "sentence_index": 6, "correct_answer": "目击"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我目击这个秘密，但是没告诉别人。", "explanation": "这里应该用〈知道〉。目击指亲眼看见事件，秘密不是能被看见的事情，不能用目击。"}, {"text": "他的笑容让我目击了快乐。", "explanation": "这里应该用〈感受〉。目击是亲眼看见事情，快乐是一种感觉，不能被目击。"}, {"text": "我在图书馆目击了一本书。", "explanation": "这里应该用〈看〉。目击的对象必须是发生的事件，一本书只能看，不能目击。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13142, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨晚在巷口目击了一只打斗。", "corrected_sentence": "我昨晚在巷口目击了一场打斗。", "error_description": "「目击」的宾语「打斗」是事件，量词应用「场」，不能用「只」。正确应说「目击了一场打斗」。「只」多用于动物或成对物品中的一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13142, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没有目击了那次事故。", "corrected_sentence": "我没有目击那次事故。", "error_description": "否定句中「目击」后不能再加「了」。「没有」已经表示未发生，应说「我没有目击那次事故」，去掉「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13144, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13144, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13144, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指生命或状态重新开始，比如死后复活或改过自新。", "primary_collocate": null, "pronunciation": "chóng shēng", "ipa": "ʈʂʰʊŋ˧˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "更深层次而言，堆肥行为本身构成一种生态认知的具身化训练：当人们亲手将果皮菜叶投入发酵箱，目击其从腐败到重生的蜕变，便不得不重新审视“废弃物”的定义边界——所谓垃圾，或许只是错置位置的资源。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这场大病之后，他觉得自己像经历了一次重生。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这家老工厂来说，转型就是一次重生。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，干枯的森林迎来了重生。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离婚让她痛苦，也给了她一次重生的机会。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市在战争后获得了重生。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲的是一个人的重生。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这次失败看作重生的开始。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧楼变成了图书馆，也是一种重生。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经历痛苦以后，很多人会有重生的感觉。", "target_word": "重生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一次重生", "label": "量词"}], "register": "中性", "sense_fingerprint": "生命或状态的重新开始（名词用法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8156197-8a74-47f3-bff9-59c094dadc77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13144, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重生", "is_correct": true, "explanation": "正确。“从腐败到重生的蜕变”指从腐烂变为新生，符合句意。"}, {"text": "死亡", "is_correct": false, "explanation": "语义：“蜕变”的结果是新生，“死亡”与之相反，不能作为蜕变的终点。"}, {"text": "衰老", "is_correct": false, "explanation": "语义：“衰老”是走向终结的过程，与“蜕变”所指的新生方向不合。"}, {"text": "乐曲", "is_correct": false, "explanation": "搭配：“从腐败到乐曲的蜕变”不成立，乐曲与物质的分解和更新无关。"}], "explanations": {"重生": "正确。“从腐败到重生的蜕变”指从腐烂变为新生，符合句意。", "死亡": "语义：“蜕变”的结果是新生，“死亡”与之相反，不能作为蜕变的终点。", "衰老": "语义：“衰老”是走向终结的过程，与“蜕变”所指的新生方向不合。", "乐曲": "搭配：“从腐败到乐曲的蜕变”不成立，乐曲与物质的分解和更新无关。"}, "sentence_index": 0, "correct_answer": "重生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个婴儿在一个寒冷的冬天重生了。", "explanation": "这里应该用〈出生〉。重生指生命或状态重新开始，婴儿来到世界应说“出生”。"}, {"text": "这次考试是新学期的重生。", "explanation": "这里应该用〈开端〉。重生强调旧状态结束后重新开始，学期的起点应说“开端”。"}, {"text": "他刚进大学，是重生。", "explanation": "这里应该用〈新生〉。重生指生命或状态重新开始，刚入学的学生应说“新生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13144, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重生", "is_correct": true, "explanation": "正确。“讲的是一个人的重生”说明电影主题是人的重新开始，符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”与电影的主题无关，不能作为电影讲述的内容。"}, {"text": "电量", "is_correct": false, "explanation": "语义：“电量”是电器的概念，不能作为电影讲述的人物主题。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“讲的是……的体温”不成立，体温不能作为电影的主题。"}], "explanations": {"重生": "正确。“讲的是一个人的重生”说明电影主题是人的重新开始，符合句意。", "价格": "语义：“价格”与电影的主题无关，不能作为电影讲述的内容。", "电量": "语义：“电量”是电器的概念，不能作为电影讲述的人物主题。", "体温": "搭配：“讲的是……的体温”不成立，体温不能作为电影的主题。"}, "sentence_index": 6, "correct_answer": "重生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "民主制度的重生始于古希腊。", "explanation": "这里应该用〈诞生〉。民主制度在古希腊首次出现，应说“诞生”；重生指旧事物重新开始，不能用于首次出现。"}, {"text": "我们学校的重生在下周一。", "explanation": "这里应该用〈开学〉。重生指旧状态结束后重新开始，学校新学期开始应说“开学”。"}, {"text": "这台电脑昨天就重生了。", "explanation": "这里应该用〈重启〉。重生指生命或状态重新开始，电脑重新启动应说“重启”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他经历了一把重生。", "corrected_sentence": "他经历了一次重生。", "error_description": "量词错误：“重生”是一次性的经历，应说“一次重生”，这里误用了“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在大病后经历了一棵重生。", "corrected_sentence": "她在大病后经历了一次重生。", "error_description": "量词错误：“重生”是一次性的经历，应说“一次重生”，这里误用了指植物的“棵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
