INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13147, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比喻事物发展的根本或基础。", "primary_collocate": null, "pronunciation": "jī shí", "ipa": "tɕi˥ ʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "这种系统级创新使清洁能源从补充性能源，进化为新型电力系统的基石。", "target_word": "基石", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种认知重构，恰是推动社会向循环经济范式转型的心理基石。", "target_word": "基石", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "诚信是一家公司发展的基石。", "target_word": "基石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的教育是国家未来发展的基石。", "target_word": "基石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "互相信任是朋友之间感情的基石。", "target_word": "基石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些研究为新药的开发奠定了基石。", "target_word": "基石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "健康的身体是学习和工作的基石。", "target_word": "基石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法律是社会公平和稳定的基石。", "target_word": "基石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农业一直是这个国家经济的基石。", "target_word": "基石", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把家庭看作事业成功的基石。", "target_word": "基石", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}], "register": "书面", "sense_fingerprint": "比喻义：事物发展所依靠的根本和基础", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9032895-3c87-4536-a6ce-a44d1ddecd4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13147, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "集市", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，shì 与 shí 的声调也不同，意思是集市。"}, {"text": "基石", "is_correct": true, "explanation": "正确：基石，jī shí，比喻事物发展的根本或基础。"}, {"text": "吉时", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，shí 相同，意思是吉利的时辰。"}, {"text": "几十", "is_correct": false, "explanation": "jǐ（第三声）与 jī（第一声）声调不同，shí 相同，意思是几十。"}, {"text": "记事", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，shì 与 shí 的声调也不同，意思是记录事情。"}], "explanations": {"集市": "jí（第二声）与 jī（第一声）声调不同，shì 与 shí 的声调也不同，意思是集市。", "基石": "正确：基石，jī shí，比喻事物发展的根本或基础。", "吉时": "jí（第二声）与 jī（第一声）声调不同，shí 相同，意思是吉利的时辰。", "几十": "jǐ（第三声）与 jī（第一声）声调不同，shí 相同，意思是几十。", "记事": "jì（第四声）与 jī（第一声）声调不同，shì 与 shí 的声调也不同，意思是记录事情。"}, "sentence_index": null, "correct_answer": "基石"}, "level_3": {"options": [{"text": "坟墓", "is_correct": false, "explanation": "语义：坟墓指埋葬死者的地方，与“进化”所表示的积极发展方向相悖。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是供儿童玩耍的物品，与“系统级创新”的语境不符。"}, {"text": "基石", "is_correct": true, "explanation": "正确：“基石”比喻事物发展的根本，符合“进化为……的基石”的用法。"}, {"text": "大腕", "is_correct": false, "explanation": "语域：“大腕”是口语，指有名望的人，不用于指称电力系统的组成部分。"}], "explanations": {"坟墓": "语义：坟墓指埋葬死者的地方，与“进化”所表示的积极发展方向相悖。", "玩具": "语义：玩具是供儿童玩耍的物品，与“系统级创新”的语境不符。", "基石": "正确：“基石”比喻事物发展的根本，符合“进化为……的基石”的用法。", "大腕": "语域：“大腕”是口语，指有名望的人，不用于指称电力系统的组成部分。"}, "sentence_index": 0, "correct_answer": "基石"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的分数是大家取笑他的基石。", "explanation": "这里应该用〈把柄〉。“把柄”指可以被人拿来取笑或攻击的短处；“基石”指事物发展的根本，不能用来指被人取笑的短处，应说“把柄”。"}, {"text": "他在台上摔了一跤，成了大家的基石。", "explanation": "这里应该用〈笑话〉。“笑话”指被人取笑的事，摔跤让他成了大家取笑的对象；“基石”指事物发展的根本，不能用来指被嘲笑的事，应说“笑话”。"}, {"text": "这个问题成了改革的基石。", "explanation": "这里应该用〈绊脚石〉。基石表示促进发展的根本和基础，这里说的是阻碍改革的问题，应说“绊脚石”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aece2ac-d8f8-4569-a25b-b78398759871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13147, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "急事", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，shì 与 shí 的声调也不同，意思是紧急的事。"}, {"text": "基石", "is_correct": true, "explanation": "正确：基石，jī shí，比喻事物发展的根本或基础。"}, {"text": "吉时", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，shí 相同，意思是吉利的时辰。"}, {"text": "即使", "is_correct": false, "explanation": "jí（第二声）与 jī 声调不同，shǐ（第三声）与 shí 的声调也不同，意思是“即便”。"}, {"text": "纪实", "is_correct": false, "explanation": "jì（第四声）与 jī 声调不同，shí 相同，意思是记录真实的情况。"}], "explanations": {"急事": "jí（第二声）与 jī（第一声）声调不同，shì 与 shí 的声调也不同，意思是紧急的事。", "基石": "正确：基石，jī shí，比喻事物发展的根本或基础。", "吉时": "jí（第二声）与 jī（第一声）声调不同，shí 相同，意思是吉利的时辰。", "即使": "jí（第二声）与 jī 声调不同，shǐ（第三声）与 shí 的声调也不同，意思是“即便”。", "纪实": "jì（第四声）与 jī 声调不同，shí 相同，意思是记录真实的情况。"}, "sentence_index": null, "correct_answer": "基石"}, "level_3": {"options": [{"text": "对手", "is_correct": false, "explanation": "语义：对手指竞争的一方，不能用来说身体是学习和工作的依靠。"}, {"text": "负担", "is_correct": false, "explanation": "语义：负担指累赘，与“健康的身体”的积极含义相反。"}, {"text": "基石", "is_correct": true, "explanation": "正确：“基石”指学习和工作所依靠的根本，与“健康的身体是……的基石”的语境相合。"}, {"text": "哥们儿", "is_correct": false, "explanation": "语域：“哥们儿”是口语中称朋友的词，不能用在这句书面语里指身体。"}], "explanations": {"对手": "语义：对手指竞争的一方，不能用来说身体是学习和工作的依靠。", "负担": "语义：负担指累赘，与“健康的身体”的积极含义相反。", "基石": "正确：“基石”指学习和工作所依靠的根本，与“健康的身体是……的基石”的语境相合。", "哥们儿": "语域：“哥们儿”是口语中称朋友的词，不能用在这句书面语里指身体。"}, "sentence_index": 6, "correct_answer": "基石"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "资金短缺是项目推进的基石。", "explanation": "这里应该用〈障碍〉。基石表示促进发展的根本，而“资金短缺”阻碍项目推进，应说“障碍”。"}, {"text": "这笔债务压得公司喘不过气，成了它的基石。", "explanation": "这里应该用〈包袱〉。“包袱”指沉重的负担，债务压得公司喘不过气，应说“包袱”；“基石”指促进发展的根本，不能用来指压垮公司的负担。"}, {"text": "那次争吵让两人的感情出现了基石。", "explanation": "这里应该用〈裂缝〉。“裂缝”指关系上的破裂痕迹，争吵让感情出现的是裂缝；“基石”指事物发展的根本，不能用来指感情出现的问题，应说“裂缝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aece2ac-d8f8-4569-a25b-b78398759871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13147, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "健康是幸福生活的一只基石。", "corrected_sentence": "健康是幸福生活的一块基石。", "error_description": "量词错误：“基石”应搭配量词“块”，“只”用于动物等，应说“一块基石”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aece2ac-d8f8-4569-a25b-b78398759871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13147, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次改革为国家经济奠定了一只基石。", "corrected_sentence": "这次改革为国家经济奠定了一块基石。", "error_description": "量词错误：“基石”应搭配量词“块”，“只”用于动物等，应说“一块基石”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3aece2ac-d8f8-4569-a25b-b78398759871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13148, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13148, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13148, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从旁帮助、协助。", "primary_collocate": null, "pronunciation": "fǔ zhù", "ipa": "fu˨˩˦ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "因此，自制堆肥不仅是一项园艺辅助技术，更是一种具哲学意涵的生活实践。", "target_word": "辅助", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "老师辅助学生完成了这个实验。", "target_word": "辅助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习时，老师在旁辅助我整理笔记。", "target_word": "辅助", "complexity_tier": "T3", "furigana": "xuéxí shí, lǎoshī zài páng fǔzhù wǒ zhěnglǐ bǐjì.", "sentence_source": "generated"}, {"text": "医生让护士在旁边辅助他。", "target_word": "辅助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子刚学写字时，妈妈在旁辅助。", "target_word": "辅助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区里的邻居在旁辅助老人办理手续。", "target_word": "辅助", "complexity_tier": "T3", "furigana": "shèqū lǐ de línjū zài páng fǔzhù lǎorén bànlǐ shǒuxù.", "sentence_source": "generated"}, {"text": "他只是辅助你，主要工作要你自己做。", "target_word": "辅助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的任务是辅助队长。", "target_word": "辅助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练辅助运动员做每天的练习。", "target_word": "辅助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥在一旁辅助你理解课文。", "target_word": "辅助", "complexity_tier": "T3", "furigana": "gēge zài yīpáng fǔzhù nǐ lǐjiě kèwén.", "sentence_source": "generated"}], "morphological_forms": [{"form": "辅助了", "label": "体标"}, {"form": "辅助过", "label": "体标"}, {"form": "輔助", "label": "繁体"}], "register": "书面", "sense_fingerprint": "从旁协助；也可作定语，指起辅助作用的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8156197-8a74-47f3-bff9-59c094dadc77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13148, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "辅助", "is_correct": true, "explanation": "「辅助」作定语，指起辅助作用的，修饰「技术」，与「园艺」搭配。"}, {"text": "体育", "is_correct": false, "explanation": "语义：园艺与体育无关，「园艺体育技术」讲不通。"}, {"text": "麻醉", "is_correct": false, "explanation": "搭配：「园艺」限定的技术不能与「麻醉」搭配。"}, {"text": "火箭", "is_correct": false, "explanation": "语义：火箭是航天器，不能作为园艺技术的限定语。"}], "explanations": {"辅助": "「辅助」作定语，指起辅助作用的，修饰「技术」，与「园艺」搭配。", "体育": "语义：园艺与体育无关，「园艺体育技术」讲不通。", "麻醉": "搭配：「园艺」限定的技术不能与「麻醉」搭配。", "火箭": "语义：火箭是航天器，不能作为园艺技术的限定语。"}, "sentence_index": 0, "correct_answer": "辅助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个消息辅助我很高兴。", "explanation": "这里应该用〈让〉。辅助指从旁帮忙做事，不能表示使人产生某种情绪。"}, {"text": "妈妈辅助孩子去公园玩。", "explanation": "这里应该用〈陪〉。辅助要帮对方完成一件具体的事，单纯同行玩耍不是辅助。"}, {"text": "队长在比赛中辅助全队下命令。", "explanation": "这里应该用〈指挥〉。辅助指处于从属地位的帮助，全队的领导者不是辅助者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13148, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "辅助", "is_correct": true, "explanation": "「辅助」指从旁帮忙，与「主要工作要你自己做」的语境一致。"}, {"text": "批准", "is_correct": false, "explanation": "语义：「批准」是同意或核准，与「只是……你」的语境不合。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：「嘲笑」表示取笑，与前后的帮助关系不合。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：「拒绝」表示不接受，与「只是……主要工作要你自己做」的帮助语境不合。"}], "explanations": {"辅助": "「辅助」指从旁帮忙，与「主要工作要你自己做」的语境一致。", "批准": "语义：「批准」是同意或核准，与「只是……你」的语境不合。", "嘲笑": "语义：「嘲笑」表示取笑，与前后的帮助关系不合。", "拒绝": "语义：「拒绝」表示不接受，与「只是……主要工作要你自己做」的帮助语境不合。"}, "sentence_index": 6, "correct_answer": "辅助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老人辅助着栏杆走路。", "explanation": "这里应该用〈扶〉。辅助的对象是需要帮忙的人或具体的事，不能用来指用手支撑栏杆。"}, {"text": "警察辅助市民的安全。", "explanation": "这里应该用〈保护〉。辅助的对象是做事的人或任务，不能用来表示保障安全。"}, {"text": "医生辅助了病人的疾病。", "explanation": "这里应该用〈治疗〉。辅助的对象是人或具体任务，不能以疾病为宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13148, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他辅助我了做作业。", "corrected_sentence": "他辅助我做完了作业。", "error_description": "错误：“了”不能放在宾语“我”之后。“了”应附在完成的动作上，正确是“他辅助我做完了作业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13148, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她每天辅助过妈妈做家务。", "corrected_sentence": "她每天辅助妈妈做家务。", "error_description": "错误：「每天」表示经常性的动作，不能与表示经历的「过」同用。正确应为「每天辅助妈妈」，去掉「过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab811291-4a3d-4891-9e44-1f71d26fa5de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
