INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13150, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们在实际生活中进行的各种活动和经验。", "primary_collocate": null, "pronunciation": "shēng huó shí jiàn", "ipa": "ʂɤŋ˥ xuɔ˧˥ ʂʐ̩˧˥ tɕjɛn˥˩", "syllable_count": 4, "sentences": [{"text": "因此，自制堆肥不仅是一项园艺辅助技术，更是一种具哲学意涵的生活实践。", "target_word": "生活实践", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "书本上的知识要在生活实践中学习。", "target_word": "生活实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的好习惯都来自多年的生活实践。", "target_word": "生活实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，生活实践比书本更重要。", "target_word": "生活实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在生活实践里学会了做饭。", "target_word": "生活实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些经验是爷爷从生活实践中得来的。", "target_word": "生活实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把课堂上学的东西用到生活实践里。", "target_word": "生活实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有通过生活实践，我们才能真正懂得这个道理。", "target_word": "生活实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生活实践让他明白了工作不容易。", "target_word": "生活实践", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把自己的生活实践写成了一本书。", "target_word": "生活实践", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生活实践", "label": "原形"}], "register": "书面", "sense_fingerprint": "人们在现实生活中的各种活动和积累的经验", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38096432-dacc-4bd4-bbc5-445f189b8c2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13150, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生活实践", "is_correct": true, "explanation": "生活实践指人们在现实生活中进行的活动和积累的经验，能够被“具哲学意涵的”修饰。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是人们的活动和经验，不能说“一种具哲学意涵的桌子”。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“具哲学意涵的”通常修饰活动、理论或思想，不修饰手机这类器物。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调是电器，与前文的园艺辅助技术及“哲学意涵”的语境都对不上。"}], "explanations": {"生活实践": "生活实践指人们在现实生活中进行的活动和积累的经验，能够被“具哲学意涵的”修饰。", "桌子": "语义：桌子是家具，不是人们的活动和经验，不能说“一种具哲学意涵的桌子”。", "手机": "搭配：“具哲学意涵的”通常修饰活动、理论或思想，不修饰手机这类器物。", "空调": "语义：空调是电器，与前文的园艺辅助技术及“哲学意涵”的语境都对不上。"}, "sentence_index": 0, "correct_answer": "生活实践"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他有一只很好的生活实践，每天都帮家里做事。", "explanation": "这里的量词「只」多用于动物。生活实践是抽象名词，应该用「项」或「种」，这里用「只」是量词误用。"}, {"text": "他把生活实践放在书架上，每天擦一擦。", "explanation": "生活实践指人们的活动和经验，是抽象概念，不能当成实物摆在书架上。"}, {"text": "这门课讲的生活实践都是书本上的公式。", "explanation": "这里把“生活实践”当成了理论或公式来用。生活实践指的是实际生活中的活动和经验，不是书本上的公式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be202aab-e74d-4b40-9621-7fc3b495612c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13150, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生活实践", "is_correct": true, "explanation": "生活实践指实际生活中的活动，与「把课堂上学的东西用到……里」的语境相符。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：钱包是装钱的物品，不是应用课堂知识的场所，句意不通。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘是遮挡光线的织物，“把课堂上学的东西用到窗帘里”说不通。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套是穿戴的物品，“用到手套里”无法承接“课堂上学的东西”，句意不通。"}], "explanations": {"生活实践": "生活实践指实际生活中的活动，与「把课堂上学的东西用到……里」的语境相符。", "钱包": "语义：钱包是装钱的物品，不是应用课堂知识的场所，句意不通。", "窗帘": "语义：窗帘是遮挡光线的织物，“把课堂上学的东西用到窗帘里”说不通。", "手套": "语义：手套是穿戴的物品，“用到手套里”无法承接“课堂上学的东西”，句意不通。"}, "sentence_index": 6, "correct_answer": "生活实践"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的生活实践很漂亮，大家都夸她。", "explanation": "「漂亮」形容外貌或事物的好看，不能修饰抽象的活动和经验，这里搭配不当。"}, {"text": "她的生活实践很高，比同学还高。", "explanation": "「高」说的是高度或身高，生活实践没有高矮之分，这里搭配不当。"}, {"text": "这里的生活实践很便利，附近有超市和医院。", "explanation": "这里把「生活实践」当成了「生活环境」来用，指居住的条件和周围的环境。生活实践指人们实际进行的活动和经验，不能用来说环境便利，这里搭配不当。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be202aab-e74d-4b40-9621-7fc3b495612c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13150, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次旅行是一条很好的生活实践。", "corrected_sentence": "这次旅行是一次很好的生活实践。", "error_description": "“生活实践”是抽象名词，量词应用「次」，不能用「条」。「条」多用于细长的东西，这里是量词误用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be202aab-e74d-4b40-9621-7fc3b495612c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13150, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要生活实践中不断学习。", "corrected_sentence": "我们要在生活实践中不断学习。", "error_description": "介词“在”漏掉了。“在生活实践中”是表示范围的状语，应说“在生活实践中不断学习”，不能省去“在”直接说“生活实践中”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be202aab-e74d-4b40-9621-7fc3b495612c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13151, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
