INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13153, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "双方互相给予、接收对方的东西。", "primary_collocate": null, "pronunciation": "jiāo huàn", "ipa": "tɕjɑʊ˥ xwan˥˩", "syllable_count": 2, "sentences": [{"text": "我们每天都与自然进行物质交换，这种往来维持着生态的平衡。", "target_word": "交换", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "我们交换了电话号码。", "target_word": "交换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友们互相交换礼物。", "target_word": "交换", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想和我交换座位。", "target_word": "交换", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "两个国家交换了意见。", "target_word": "交换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让同学们交换作业本。", "target_word": "交换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下课后，我们交换了笔记。", "target_word": "交换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用旧书交换新书。", "target_word": "交换", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "比赛前，双方队长交换了队旗。", "target_word": "交换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在会上交换了名片。", "target_word": "交换", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "交换了", "label": "完成体"}, {"form": "交换过", "label": "经历体"}, {"form": "交换着", "label": "持续体"}, {"form": "交换机", "label": "复合词"}, {"form": "交换生", "label": "复合词"}], "register": "中性", "sense_fingerprint": "交换：双方互相给出并接收对方的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1643dd7e-39f0-4480-b4fc-1a9f2c8ab0c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13153, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交换", "is_correct": true, "explanation": "物质交换：物质在自然与人类之间相互输入、输出，符合句意。"}, {"text": "消灭", "is_correct": false, "explanation": "语义：「消灭」指彻底除去，与句中双方相互往来的物质关系不符。"}, {"text": "掠夺", "is_correct": false, "explanation": "语义：「掠夺」是单方面强取，与「我们与自然」之间的往来关系相反。"}, {"text": "退化", "is_correct": false, "explanation": "语义：「退化」指变差、衰退，「与自然进行物质退化」不成立，也不表示双方互相往来。"}], "explanations": {"交换": "物质交换：物质在自然与人类之间相互输入、输出，符合句意。", "消灭": "语义：「消灭」指彻底除去，与句中双方相互往来的物质关系不符。", "掠夺": "语义：「掠夺」是单方面强取，与「我们与自然」之间的往来关系相反。", "退化": "语义：「退化」指变差、衰退，「与自然进行物质退化」不成立，也不表示双方互相往来。"}, "sentence_index": 0, "correct_answer": "交换"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老板交换了我的工资。", "explanation": "这里应该用〈扣〉。交换要求双方都给出东西，老板单方面克扣员工工资时应说扣。"}, {"text": "我交换了他的雨伞，他什么也没拿到。", "explanation": "这里应该用〈借〉。交换要求双方都给出东西，只从对方那里拿走雨伞而对方什么也没得到时应说借。"}, {"text": "我把钥匙交换给了妈妈，她什么也没给我。", "explanation": "这里应该用〈交给〉。交换要求双方都给出东西，妈妈没有回报，只是把钥匙交到她手里，应说交给。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13153, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交换", "is_correct": true, "explanation": "交换：双方互相换取，「交换笔记」是常见搭配，符合句意。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」只用于饮品，不能和「笔记」搭配。"}, {"text": "教", "is_correct": false, "explanation": "配价：「教」要求教的对象是人，「教笔记」不成立。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：「穿」用于衣服、鞋袜，不能和「笔记」搭配。"}], "explanations": {"交换": "交换：双方互相换取，「交换笔记」是常见搭配，符合句意。", "喝": "搭配：「喝」只用于饮品，不能和「笔记」搭配。", "教": "配价：「教」要求教的对象是人，「教笔记」不成立。", "穿": "搭配：「穿」用于衣服、鞋袜，不能和「笔记」搭配。"}, "sentence_index": 6, "correct_answer": "交换"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天在书店交换了一本新书。", "explanation": "这里应该用〈买〉。交换需要双方互相给出东西，用钱从书店得到书要说买。"}, {"text": "他给远方的朋友交换了一封信。", "explanation": "这里应该用〈寄〉。单方面把信送给别人要说寄，交换要求双方互相给出。"}, {"text": "老师在课上交换了我们一个问题。", "explanation": "这里应该用〈问〉。交换不能带「人＋事物」双宾语，向人提出问题要说问。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13153, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她和同学交换了一只照片。", "corrected_sentence": "她和同学交换了一张照片。", "error_description": "错误：「一只照片」，「只」用于动物或成对器官中的一个，照片应使用量词「张」。正确：「一张照片」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13153, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在会上交换了一个名片。", "corrected_sentence": "我们在会上交换了一张名片。", "error_description": "错误：「一个名片」，名片是薄而平的东西，量词应用「张」。正确：「交换了一张名片」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b16433f3-74de-4047-99f4-55d68ae2c0e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13157, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开始", "is_correct": true, "explanation": "反义：“停止”与“开始”构成反义关系，一个是不再做，一个是开始做。"}, {"text": "研究", "is_correct": false, "explanation": "无关：“研究”与“停止”既非近义也非反义。"}, {"text": "收集", "is_correct": false, "explanation": "无关：“收集”与“停止”既非近义也非反义。"}, {"text": "参加", "is_correct": false, "explanation": "无关：“参加”与“停止”既非近义也非反义。"}], "correct_answer": "开始", "explanations": {"开始": "反义：“停止”与“开始”构成反义关系，一个是不再做，一个是开始做。", "研究": "无关：“研究”与“停止”既非近义也非反义。", "收集": "无关：“收集”与“停止”既非近义也非反义。", "参加": "无关：“参加”与“停止”既非近义也非反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13157, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "继续", "is_correct": true, "explanation": "反义：“停止”与“继续”构成反义关系，指不停下、持续做下去。"}, {"text": "修理", "is_correct": false, "explanation": "无关：“修理”与“停止”既非近义也非反义。"}, {"text": "整理", "is_correct": false, "explanation": "无关：“整理”与“停止”既非近义也非反义。"}, {"text": "讨论", "is_correct": false, "explanation": "无关：“讨论”与“停止”既非近义也非反义。"}], "correct_answer": "继续", "explanations": {"继续": "反义：“停止”与“继续”构成反义关系，指不停下、持续做下去。", "修理": "无关：“修理”与“停止”既非近义也非反义。", "整理": "无关：“整理”与“停止”既非近义也非反义。", "讨论": "无关：“讨论”与“停止”既非近义也非反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13157, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不再进行某种动作或活动。", "primary_collocate": null, "pronunciation": "tíng zhǐ", "ipa": "tʰiŋ˧˥ ʈʂɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "大家想停止塑料污染。", "target_word": "停止", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他听到铃声，就停止了说话。", "target_word": "停止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说你要停止喝酒。", "target_word": "停止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂必须停止排放污水。", "target_word": "停止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家停止讨论，现在开始考试。", "target_word": "停止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下大雪，比赛停止进行。", "target_word": "停止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请停止使用手机，飞机要起飞了。", "target_word": "停止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司已经停止生产这种手机。", "target_word": "停止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们停止写字，把笔放下。", "target_word": "停止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从没停止过努力。", "target_word": "停止", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "停止了", "label": "完成体"}, {"form": "停止过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "不再进行某个动作或活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0e893e4-8d0e-406f-8cbf-bd8a62472e4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13157, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "停止", "is_correct": true, "explanation": "正确：词目“停止”，意思是不再进行某种动作或活动。"}, {"text": "停职", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是暂时免去职务，与“停止”不同。"}, {"text": "听旨", "is_correct": false, "explanation": "tīng zhǐ（第一声）与 tíng zhǐ 仅首字声调不同，“听旨”指听取君主的旨意，与“停止”意义无关。"}, {"text": "挺直", "is_correct": false, "explanation": "tǐng zhí 与 tíng zhǐ 的两个音节声调都不同，意思是笔直、不弯曲。"}], "explanations": {"停止": "正确：词目“停止”，意思是不再进行某种动作或活动。", "停职": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是暂时免去职务，与“停止”不同。", "听旨": "tīng zhǐ（第一声）与 tíng zhǐ 仅首字声调不同，“听旨”指听取君主的旨意，与“停止”意义无关。", "挺直": "tǐng zhí 与 tíng zhǐ 的两个音节声调都不同，意思是笔直、不弯曲。"}, "sentence_index": null, "correct_answer": "停止"}, "level_3": {"options": [{"text": "停止", "is_correct": true, "explanation": "正确：“停止”表示让污染不再继续，与“大家想……塑料污染”的语境相合。"}, {"text": "制造", "is_correct": false, "explanation": "语义：“想制造塑料污染”与句子反对污染的意思相反。"}, {"text": "参与", "is_correct": false, "explanation": "搭配：“参与”带活动、事务作宾语，不能带“污染”。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”表示喜爱、乐于接受，与“想……塑料污染”的意思相反。"}], "explanations": {"停止": "正确：“停止”表示让污染不再继续，与“大家想……塑料污染”的语境相合。", "制造": "语义：“想制造塑料污染”与句子反对污染的意思相反。", "参与": "搭配：“参与”带活动、事务作宾语，不能带“污染”。", "享受": "语义：“享受”表示喜爱、乐于接受，与“想……塑料污染”的意思相反。"}, "sentence_index": 0, "correct_answer": "停止"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在北京停止了三天。", "explanation": "这里应该用〈停留〉。停止指不再进行某种动作，不能表示在某地待着，那是停留。"}, {"text": "他终于停止了酒瘾。", "explanation": "这里应该用〈戒掉〉。“停止”不能直接带“酒瘾”这类习惯作宾语，戒掉习惯要说“戒掉”。"}, {"text": "这种颜色停止了一年。", "explanation": "这里应该用〈保持〉。停止指不再进行某种动作，不能表示某种状态维持不变，那是保持。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13157, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "停止", "is_correct": true, "explanation": "正确：“停止”表示不再使用，与“飞机要起飞了”的要求相合。"}, {"text": "开始", "is_correct": false, "explanation": "语义：“请开始使用手机”与“飞机要起飞”要求关机的语境相反。"}, {"text": "喝", "is_correct": false, "explanation": "配价：“喝”的宾语应是饮品，不能以“使用手机”这样的动作为宾语。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：“拍”不能带“使用手机”这样的动作作宾语。"}], "explanations": {"停止": "正确：“停止”表示不再使用，与“飞机要起飞了”的要求相合。", "开始": "语义：“请开始使用手机”与“飞机要起飞”要求关机的语境相反。", "喝": "配价：“喝”的宾语应是饮品，不能以“使用手机”这样的动作为宾语。", "拍": "搭配：“拍”不能带“使用手机”这样的动作作宾语。"}, "sentence_index": 6, "correct_answer": "停止"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他顺路停止了我家。", "explanation": "这里应该用〈顺路去〉。停止指不再进行某种动作，不能表示顺道到某人家。"}, {"text": "我把车停止在门口了。", "explanation": "这里应该用〈停放〉。停止不能表示把车辆停在某处，车辆停在某处要说“停放”或“停”。"}, {"text": "他在公园停止了一个下午。", "explanation": "这里应该用〈逗留〉。停止指不再进行某种动作，不能表示在某地待着，那是逗留。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13157, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请大家马上停止了讨论。", "corrected_sentence": "请大家马上停止讨论。", "error_description": "错误：祈使句“请大家马上……”表示要求，“停止”后不能加“了”，应说“请大家马上停止讨论”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13157, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从没停止了学习。", "corrected_sentence": "他从没停止过学习。", "error_description": "错误：“从没”表示从未有过的经历，应用“过”，不能用“了”。应说“他从没停止过学习”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39965f8c-2029-4b18-b670-d29ab1d6e1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
