INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13159, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用水或溶剂等去除物体上的污垢。", "primary_collocate": null, "pronunciation": "xǐ", "ipa": "ɕi˨˩˦", "syllable_count": 1, "sentences": [{"text": "人们可以用布袋子，布袋子可以洗，可以再用。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "吃饭以前，你要先洗手。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服太脏了，我想洗一洗。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天晚上都要洗碗。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裤子已经洗过两次了。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天洗了车，今天又下雨了。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种杯子不能用热水洗。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把青菜洗干净再切。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在河边洗衣服。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服太旧了，洗了很多次，颜色都变了。", "target_word": "洗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "洗了", "label": "体标"}, {"form": "洗过", "label": "体标"}, {"form": "洗洗", "label": "重叠"}], "register": "中性", "sense_fingerprint": "用水或溶剂去除物体上的污垢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '703d6979-3962-4484-92d2-882f13f16783') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13159, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "洗", "is_correct": true, "explanation": "洗（xǐ，第三声），意思是用水去除污垢。"}, {"text": "细", "is_correct": false, "explanation": "声调不同：细是 xì（第四声），与 xǐ（第三声）不同，意思是细小。"}, {"text": "吸", "is_correct": false, "explanation": "声调不同：吸是 xī（第一声），与 xǐ（第三声）不同，意思是吸入。"}, {"text": "西", "is_correct": false, "explanation": "声调不同：西是 xī（第一声），与 xǐ（第三声）不同，意思是西方。"}, {"text": "死", "is_correct": false, "explanation": "声母不同：死是 sǐ，s 与 x 不同，声调相同，意思是死亡。"}, {"text": "戏", "is_correct": false, "explanation": "声调不同：戏是 xì（第四声），与 xǐ（第三声）不同，意思是戏剧。"}], "explanations": {"洗": "洗（xǐ，第三声），意思是用水去除污垢。", "细": "声调不同：细是 xì（第四声），与 xǐ（第三声）不同，意思是细小。", "吸": "声调不同：吸是 xī（第一声），与 xǐ（第三声）不同，意思是吸入。", "西": "声调不同：西是 xī（第一声），与 xǐ（第三声）不同，意思是西方。", "死": "声母不同：死是 sǐ，s 与 x 不同，声调相同，意思是死亡。", "戏": "声调不同：戏是 xì（第四声），与 xǐ（第三声）不同，意思是戏剧。"}, "sentence_index": null, "correct_answer": "洗"}, "level_3": {"options": [{"text": "洗", "is_correct": true, "explanation": "与句中“洗”相同，“可以洗，可以再用”说的是用水去除污垢。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔掉的东西不能再用，与“可以再用”矛盾。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧掉之后不能再用，与“可以再用”矛盾。"}, {"text": "切", "is_correct": false, "explanation": "语义：布袋子若被切开就不能再用，与“可以再用”矛盾。"}], "explanations": {"洗": "与句中“洗”相同，“可以洗，可以再用”说的是用水去除污垢。", "扔": "语义：扔掉的东西不能再用，与“可以再用”矛盾。", "烧": "语义：烧掉之后不能再用，与“可以再用”矛盾。", "切": "语义：布袋子若被切开就不能再用，与“可以再用”矛盾。"}, "sentence_index": 0, "correct_answer": "洗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑完步，用毛巾洗汗。", "explanation": "这里应该用〈擦〉。“擦”用于汗、灰尘等，汗不能说“洗”。"}, {"text": "妈妈用熨斗洗了一下裙子。", "explanation": "这里应该用〈熨〉。“熨”是用熨斗把衣服弄平整，不用水；“洗”指用水去除污垢，不能这样用。"}, {"text": "我每天给花洗水。", "explanation": "这里应该用〈浇〉。“浇”用于给花草等浇水，“洗”不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '500d3285-fe4e-4f39-81a9-59a8a9272a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13159, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "洗", "is_correct": true, "explanation": "洗（xǐ，第三声），意思是用水去除污垢。"}, {"text": "席", "is_correct": false, "explanation": "声调不同：席是 xí（第二声），与 xǐ（第三声）不同，意思是席子。"}, {"text": "系", "is_correct": false, "explanation": "声调不同：系是 xì（第四声），与 xǐ（第三声）不同，意思是系上、联系。"}, {"text": "醒", "is_correct": false, "explanation": "韵母不同：醒是 xǐng，比 xǐ 多了后鼻音 ng，声调相同，意思是醒来。"}], "explanations": {"洗": "洗（xǐ，第三声），意思是用水去除污垢。", "席": "声调不同：席是 xí（第二声），与 xǐ（第三声）不同，意思是席子。", "系": "声调不同：系是 xì（第四声），与 xǐ（第三声）不同，意思是系上、联系。", "醒": "韵母不同：醒是 xǐng，比 xǐ 多了后鼻音 ng，声调相同，意思是醒来。"}, "sentence_index": null, "correct_answer": "洗"}, "level_3": {"options": [{"text": "洗", "is_correct": true, "explanation": "与句中“洗”相同，“不能用热水洗”说的是用热水去除杯子上的污垢。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”的对象不是杯子这类器皿，“这种杯子不能用热水切”搭配不上。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”是把东西扔到地上，与用热水清洁的动作不相符。"}, {"text": "剪", "is_correct": false, "explanation": "配价：“剪”需要剪刀之类的工具，“用热水剪”不成立。"}], "explanations": {"洗": "与句中“洗”相同，“不能用热水洗”说的是用热水去除杯子上的污垢。", "切": "搭配：“切”的对象不是杯子这类器皿，“这种杯子不能用热水切”搭配不上。", "摔": "语义：“摔”是把东西扔到地上，与用热水清洁的动作不相符。", "剪": "配价：“剪”需要剪刀之类的工具，“用热水剪”不成立。"}, "sentence_index": 6, "correct_answer": "洗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天晚上都在手上洗护手霜。", "explanation": "这里应该用〈涂〉。“涂”用于把护手霜抹在皮肤上；“洗”指用水去除污垢，不能用于护手霜。"}, {"text": "妈妈在锅里洗汤，等会儿就能喝了。", "explanation": "这里应该用〈煮〉。“煮”用于加热烹饪食物，汤不能说“洗”。"}, {"text": "她用手洗眼泪，不让别人看见。", "explanation": "这里应该用〈抹〉。“抹”用于擦去眼泪、药膏等，眼泪不能说“洗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '500d3285-fe4e-4f39-81a9-59a8a9272a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13159, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这双鞋脏了，我得把它洗。", "corrected_sentence": "这双鞋脏了，我得把它洗干净。", "error_description": "“把”字句中的“洗”后面要有补语，说“把它洗干净”才完整，只说“把它洗”不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '500d3285-fe4e-4f39-81a9-59a8a9272a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13159, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把被子洗了干净了。", "corrected_sentence": "他把被子洗干净了。", "error_description": "「了」位置错误：结果补语「干净」与动词「洗」之间不能插入「了」，「洗了干净」不成立，应说「他把被子洗干净了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '500d3285-fe4e-4f39-81a9-59a8a9272a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13163, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收钱", "is_correct": true, "explanation": "正确：收钱指接受费用，与“付钱”的意思正相反。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”指随意走动，与“付钱”没有反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "无关：“读书”指阅读，与“付钱”没有反义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "无关：“打扫”指清理，与“付钱”没有反义关系。"}], "correct_answer": "收钱", "explanations": {"收钱": "正确：收钱指接受费用，与“付钱”的意思正相反。", "散步": "无关：“散步”指随意走动，与“付钱”没有反义关系。", "读书": "无关：“读书”指阅读，与“付钱”没有反义关系。", "打扫": "无关：“打扫”指清理，与“付钱”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
