INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13163, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拿出钱来支付费用。", "primary_collocate": null, "pronunciation": "fù qián", "ipa": "fu˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "顾客要付钱才能拿到袋子。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "吃完饭，爸爸去前面付钱。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住酒店要先付钱吗？", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐出租车下车时要付钱。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以用手机付钱。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忘了带钱包，没办法付钱。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完病，我们先去窗口付钱。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我请客，你不用付钱。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友帮我付钱，我回头还他。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租房子要提前一个月付钱。", "target_word": "付钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "付了钱", "label": "体标"}, {"form": "付过钱", "label": "体标"}], "register": "中性", "sense_fingerprint": "拿出钱支付某种费用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a33efdb-f4f8-4a3e-8e16-958ebcfd42fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13163, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "付钱", "is_correct": true, "explanation": "正确：顾客拿袋子之前要支付费用，符合“付钱”的意思。"}, {"text": "收钱", "is_correct": false, "explanation": "语义：顾客是付钱的一方，不能说“收钱”。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与拿到袋子没有逻辑关系，句子说不通。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“拿到袋子”前不说“洗澡”，两者不搭配。"}], "explanations": {"付钱": "正确：顾客拿袋子之前要支付费用，符合“付钱”的意思。", "收钱": "语义：顾客是付钱的一方，不能说“收钱”。", "唱歌": "语义：唱歌与拿到袋子没有逻辑关系，句子说不通。", "洗澡": "搭配：“拿到袋子”前不说“洗澡”，两者不搭配。"}, "sentence_index": 0, "correct_answer": "付钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他中了彩票，付钱了一百万。", "explanation": "这里应该用〈得到〉。「付钱」指支付费用，中彩票得到的钱要用「得到」。"}, {"text": "他靠写书付钱，生活很好。", "explanation": "这里应该用〈赚〉。付钱是支出，靠写书获得收入要用“赚”。"}, {"text": "我们向灾区付钱。", "explanation": "这里应该用〈捐〉。付钱指为买卖或服务支付费用，无偿给灾区钱款要用“捐”，不能说付钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13163, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "付钱", "is_correct": true, "explanation": "正确：看完病后先去窗口付钱，符合语境。"}, {"text": "听歌", "is_correct": false, "explanation": "语义：去窗口听歌与“看完病”的语境无关，句子不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：在窗口睡觉不合情理，与“先去”办事的语境不符。"}, {"text": "种花", "is_correct": false, "explanation": "搭配：窗口不跟“种花”搭配，种花需要土地。"}], "explanations": {"付钱": "正确：看完病后先去窗口付钱，符合语境。", "听歌": "语义：去窗口听歌与“看完病”的语境无关，句子不通。", "睡觉": "语义：在窗口睡觉不合情理，与“先去”办事的语境不符。", "种花": "搭配：窗口不跟“种花”搭配，种花需要土地。"}, "sentence_index": 6, "correct_answer": "付钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师付钱给我，夸我考了满分。", "explanation": "这里应该用〈奖赏〉。付钱是为买卖或服务支付费用，夸奖学生不是交易，不能说付钱。"}, {"text": "强盗抢钱时付了钱。", "explanation": "这里应该用〈掠夺〉。付钱是按规定支付费用，强行夺取钱财要用“掠夺”，不能说“付钱”。"}, {"text": "小偷偷东西时，也付了钱。", "explanation": "这里应该用〈盗窃〉。付钱是合法支付，盗窃是非法拿走别人财物，不能说付钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13163, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "离开超市前，我们要先付钱过。", "corrected_sentence": "离开超市前，我们要先付钱。", "error_description": "“付钱”后多了“过”。“要先付钱”说的是还没做的事，不能加表示经历的“过”。应为“我们要先付钱。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13163, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在咖啡厅坐了一会儿，我们就去付钱着。", "corrected_sentence": "在咖啡厅坐了一会儿，我们就去付钱。", "error_description": "“付钱”后多了“着”。“去”后面接的是即将进行的动作，动词后不能加表示持续的“着”。应为“我们就去付钱。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13166, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "违反", "is_correct": true, "explanation": "反义：「违反」与「遵守」相对，指不依规定行事。"}, {"text": "挑选", "is_correct": false, "explanation": "无关：「挑选」与「遵守」没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "无关：「修理」与「遵守」没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "无关：「散步」与「遵守」没有反义关系。"}], "correct_answer": "违反", "explanations": {"违反": "反义：「违反」与「遵守」相对，指不依规定行事。", "挑选": "无关：「挑选」与「遵守」没有反义关系。", "修理": "无关：「修理」与「遵守」没有反义关系。", "散步": "无关：「散步」与「遵守」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13166, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "违反", "is_correct": true, "explanation": "反义：「违反」与「遵守」相对，指不依规定行事。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：「唱歌」与「遵守」没有反义关系。"}, {"text": "种植", "is_correct": false, "explanation": "无关：「种植」与「遵守」没有反义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "无关：「打扫」与「遵守」没有反义关系。"}], "correct_answer": "违反", "explanations": {"违反": "反义：「违反」与「遵守」相对，指不依规定行事。", "唱歌": "无关：「唱歌」与「遵守」没有反义关系。", "种植": "无关：「种植」与「遵守」没有反义关系。", "打扫": "无关：「打扫」与「遵守」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13166, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "依照规定或命令行动，不违反。", "primary_collocate": null, "pronunciation": "zūn shǒu", "ipa": "tswən˥ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "政府会检查商店有没有遵守规定。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "开车的人都要遵守交通规则。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生应该遵守学校的规定。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公民要遵守法律。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客必须遵守景区的规定。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的人都遵守这条规定。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时，大家都要遵守规则。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军人必须遵守上级的命令。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家遵守图书馆的规定。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机遵守交通规则，路上就安全多了。", "target_word": "遵守", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遵守了", "label": "体标"}, {"form": "遵守着", "label": "体标"}, {"form": "遵守过", "label": "体标"}], "register": "中性", "sense_fingerprint": "依照规定、法律或命令行动而不违反", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a33efdb-f4f8-4a3e-8e16-958ebcfd42fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13166, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遵守", "is_correct": true, "explanation": "正确。「遵守规定」表示依照规定行事，句中“检查有没有……规定”正是考察这一点。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：「提高」用于水平、质量，不能说提高规定。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：句子问的是商店是否依规定办事，「喜欢」表示好感，与“检查”的语境不合。"}, {"text": "修理", "is_correct": false, "explanation": "语义：「修理」指修补器物，不能用于规定。"}], "explanations": {"遵守": "正确。「遵守规定」表示依照规定行事，句中“检查有没有……规定”正是考察这一点。", "提高": "搭配：「提高」用于水平、质量，不能说提高规定。", "喜欢": "语义：句子问的是商店是否依规定办事，「喜欢」表示好感，与“检查”的语境不合。", "修理": "语义：「修理」指修补器物，不能用于规定。"}, "sentence_index": 0, "correct_answer": "遵守"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要遵守房间的干净。", "explanation": "这里应该用〈保持〉。「遵守」的对象是规定、规则或要求，干净的环境要用「保持」。"}, {"text": "孩子应该遵守父母。", "explanation": "这里应该用〈服从〉。「遵守」的对象是规定、法律或命令，指向人时要用「服从」。"}, {"text": "过马路要遵守安全。", "explanation": "这里应该用〈注意〉。「遵守」搭配规则、规定，说到安全时要用「注意安全」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13166, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遵守", "is_correct": true, "explanation": "正确。「遵守规则」表示依规则行事，符合比赛时的语境。"}, {"text": "搬", "is_correct": false, "explanation": "配价：「搬」要求有具体的物体作宾语，不能搬规则。"}, {"text": "烧", "is_correct": false, "explanation": "语义：「烧」指燃烧，与规则无关。"}, {"text": "煮", "is_correct": false, "explanation": "语义：「煮」指烹调食物，与规则无关。"}], "explanations": {"遵守": "正确。「遵守规则」表示依规则行事，符合比赛时的语境。", "搬": "配价：「搬」要求有具体的物体作宾语，不能搬规则。", "烧": "语义：「烧」指燃烧，与规则无关。", "煮": "语义：「煮」指烹调食物，与规则无关。"}, "sentence_index": 6, "correct_answer": "遵守"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要遵守公共财物。", "explanation": "这里应该用〈爱护〉。「遵守」的对象是规定，爱护物品要用「爱护」。"}, {"text": "他已经遵守了这门技术。", "explanation": "这里应该用〈掌握〉。「遵守」用于规定、规则，学会技术、知识要用「掌握」。"}, {"text": "我们要遵守老师的帮助。", "explanation": "这里应该用〈感谢〉。「遵守」指依照规定行事，对别人的帮助要说「感谢」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13166, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天没遵守了学校的约定。", "corrected_sentence": "他昨天没遵守学校的约定。", "error_description": "「没」否定动作时，动词后不能再加「了」。错误在“遵守”后面的“了”；应说「没遵守」，去掉「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13166, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他遵守很认真。", "corrected_sentence": "他遵守得很认真。", "error_description": "动词带程度补语时，中间要加「得」。应说「遵守得很认真」，不能说「遵守很认真」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
