INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13167, 1, 'prompt1_core', '{"pos": "结果补语", "semantic_class": "function", "definition": "全部用尽；完结、完成，常用在动词后，如“用完”。", "primary_collocate": null, "pronunciation": "wán", "ipa": "wan˧˥", "syllable_count": 1, "sentences": [{"text": "我的钱都花完了。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶已经喝完了。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的票全卖完了。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纸用完了，再去买吧。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把饼干吃完了。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包都吃完了，没有剩的。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水快用完了，我去买。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶水我喝完了。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把零钱全花完了。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的米吃完了。", "target_word": "完", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "完了", "label": "体标"}, {"form": "完全", "label": "复合"}, {"form": "完成", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词后结果补语，表示全部用尽、做到头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a33efdb-f4f8-4a3e-8e16-958ebcfd42fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13167, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "完", "is_correct": true, "explanation": "正确。「完」wán 表示全部用尽、完结。"}, {"text": "万", "is_correct": false, "explanation": "wàn（第四声）与 wán（第二声）声调不同，意思是一万。"}, {"text": "晚", "is_correct": false, "explanation": "wǎn（第三声）与 wán（第二声）声调不同，意思是晚上。"}, {"text": "湾", "is_correct": false, "explanation": "wān（第一声）与 wán（第二声）声调不同，意思是海湾。"}, {"text": "王", "is_correct": false, "explanation": "wáng 与 wán 韵母不同（ang／an），意思是国王。"}], "explanations": {"完": "正确。「完」wán 表示全部用尽、完结。", "万": "wàn（第四声）与 wán（第二声）声调不同，意思是一万。", "晚": "wǎn（第三声）与 wán（第二声）声调不同，意思是晚上。", "湾": "wān（第一声）与 wán（第二声）声调不同，意思是海湾。", "王": "wáng 与 wán 韵母不同（ang／an），意思是国王。"}, "sentence_index": null, "correct_answer": "完"}, "level_3": {"options": [{"text": "完", "is_correct": true, "explanation": "正确。「花完」表示钱全部用尽，与“都”呼应。"}, {"text": "好", "is_correct": false, "explanation": "语义：「花好」指花得妥当，不表示钱用尽。"}, {"text": "成", "is_correct": false, "explanation": "语义：「花成」表示变成，与钱用尽的意思不合。"}, {"text": "到", "is_correct": false, "explanation": "配价：「花到」需要说明到达的地点或程度，句中没有这一成分。"}], "explanations": {"完": "正确。「花完」表示钱全部用尽，与“都”呼应。", "好": "语义：「花好」指花得妥当，不表示钱用尽。", "成": "语义：「花成」表示变成，与钱用尽的意思不合。", "到": "配价：「花到」需要说明到达的地点或程度，句中没有这一成分。"}, "sentence_index": 0, "correct_answer": "完"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师完了今天的课。", "explanation": "这里应该用〈上〉。「完」表示用尽，不能直接带宾语「课」来表示上课，应说「上完课」。"}, {"text": "他很快完了作业。", "explanation": "这里不能用「完」直接带宾语「作业」。「完」表示完成时要接在动词后，应说「做完作业」。"}, {"text": "他完了一个月的工资。", "explanation": "这里应该用〈花〉。「完」表示用尽，不能直接带宾语「工资」，要说「花完」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13167, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "完", "is_correct": true, "explanation": "正确。「完」wán 表示全部用尽、完结。"}, {"text": "碗", "is_correct": false, "explanation": "wǎn（第三声）与 wán（第二声）声调不同，意思是碗。"}, {"text": "腕", "is_correct": false, "explanation": "wàn（第四声）与 wán（第二声）声调不同，意思是手腕。"}, {"text": "文", "is_correct": false, "explanation": "wén 与 wán 元音不同（e／a），意思是文字。"}], "explanations": {"完": "正确。「完」wán 表示全部用尽、完结。", "碗": "wǎn（第三声）与 wán（第二声）声调不同，意思是碗。", "腕": "wàn（第四声）与 wán（第二声）声调不同，意思是手腕。", "文": "wén 与 wán 元音不同（e／a），意思是文字。"}, "sentence_index": null, "correct_answer": "完"}, "level_3": {"options": [{"text": "完", "is_correct": true, "explanation": "正确。「用完」表示水全部用尽，与“快”和“去买”呼应。"}, {"text": "错", "is_correct": false, "explanation": "语义：「用错」指用得不对，与快要没了、需要去买的语境不合。"}, {"text": "腻", "is_correct": false, "explanation": "语义：「用腻」指用久了感到厌烦，水不会有这种感觉，与快要没了、需要去买的语境不合。"}, {"text": "断", "is_correct": false, "explanation": "搭配：「用断」多用于线、绳等细长物，不能说「水快用断了」。"}], "explanations": {"完": "正确。「用完」表示水全部用尽，与“快”和“去买”呼应。", "错": "语义：「用错」指用得不对，与快要没了、需要去买的语境不合。", "腻": "语义：「用腻」指用久了感到厌烦，水不会有这种感觉，与快要没了、需要去买的语境不合。", "断": "搭配：「用断」多用于线、绳等细长物，不能说「水快用断了」。"}, "sentence_index": 6, "correct_answer": "完"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把水全完掉了。", "explanation": "这里应该用〈用掉〉或〈用完〉。「完」不能和「掉」并用表示耗尽，应说「用掉」或「用完」。"}, {"text": "他一觉睡完了。", "explanation": "这里应该用〈睡醒〉。「完」强调用尽，不能表示睡醒。"}, {"text": "我们终于完了比赛。", "explanation": "这里应该用〈结束〉。「完」作不及物动词，不能带宾语「比赛」，要用「结束」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13167, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把钱全完用了。", "corrected_sentence": "他把钱全用完了。", "error_description": "结果补语「完」要紧跟在动词后面。应说「用完」，不能说「完用」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13167, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把饭全完吃了。", "corrected_sentence": "她把饭全吃完了。", "error_description": "结果补语「完」要紧跟在动词后面。应说「吃完」，不能说「完吃」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
