INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13170, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "身体出现不健康的状态，比如得了感冒、发烧等疾病。", "primary_collocate": null, "pronunciation": "shēng bìng", "ipa": "ʂɤŋ˥ piŋ˥˩", "syllable_count": 2, "sentences": [{"text": "动物会吃这些垃圾，然后生病。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他昨天生病了，没来上课。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我生病的时候，妈妈照顾我。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太冷，小心别生病。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子生病了，妈妈很着急。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生病了，今天在家休息。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常不吃早饭，容易生病。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很少生病。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶生病住院了。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你生病了就要去看医生。", "target_word": "生病", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生病了", "label": "体标"}, {"form": "生了病", "label": "离合"}, {"form": "生过病", "label": "离合"}], "register": "中性", "sense_fingerprint": "人或动物得病，身体不健康", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a33efdb-f4f8-4a3e-8e16-958ebcfd42fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13170, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生病", "is_correct": true, "explanation": "“生病”与前句“吃垃圾”的因果相合，表示身体不健康。"}, {"text": "康复", "is_correct": false, "explanation": "语义：“康复”指病后恢复健康，前句并没有生病，“然后康复”说不通。"}, {"text": "上学", "is_correct": false, "explanation": "语义：“上学”的主体应是人，“动物上学”说不通。"}, {"text": "毕业", "is_correct": false, "explanation": "搭配：“毕业”的主语一般是学生，不能说“动物毕业”。"}], "explanations": {"生病": "“生病”与前句“吃垃圾”的因果相合，表示身体不健康。", "康复": "语义：“康复”指病后恢复健康，前句并没有生病，“然后康复”说不通。", "上学": "语义：“上学”的主体应是人，“动物上学”说不通。", "毕业": "搭配：“毕业”的主语一般是学生，不能说“动物毕业”。"}, "sentence_index": 0, "correct_answer": "生病"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他切菜时生病了，手流了很多血。", "explanation": "这里应该用〈割伤〉。“生病”指身体因疾病不健康，切菜划伤是外伤，要说“割伤”。"}, {"text": "他打篮球时生病了，腿摔得不能动。", "explanation": "这里应该用〈摔伤〉。“生病”不用于摔倒造成的伤，要说“摔伤”。"}, {"text": "他被车撞后生病了，腿上擦破了一大片皮。", "explanation": "这里应该用〈撞伤〉。“生病”不用于车祸造成的伤，要说“撞伤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13170, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生病", "is_correct": true, "explanation": "“生病”与“不吃早饭”的结果相合，表示身体不健康。"}, {"text": "出院", "is_correct": false, "explanation": "语义：“出院”指离开医院，句中没有住院的前提，“容易出院”说不通。"}, {"text": "升职", "is_correct": false, "explanation": "搭配：“升职”是职场上的晋升，主语应是工作的人，与“不吃早饭”没有关系。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指离开工作岗位，与“不吃早饭”的结果不合。"}], "explanations": {"生病": "“生病”与“不吃早饭”的结果相合，表示身体不健康。", "出院": "语义：“出院”指离开医院，句中没有住院的前提，“容易出院”说不通。", "升职": "搭配：“升职”是职场上的晋升，主语应是工作的人，与“不吃早饭”没有关系。", "退休": "语义：“退休”指离开工作岗位，与“不吃早饭”的结果不合。"}, "sentence_index": 6, "correct_answer": "生病"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她跑步时生病了，脚踝肿得很厉害。", "explanation": "这里应该用〈扭伤〉。“生病”指身体因疾病不舒服，跑步时扭到脚是外伤，要说“扭伤”。"}, {"text": "他从楼梯上摔下来，生病了，膝盖擦破了一大片皮。", "explanation": "这里应该用〈摔伤〉。“生病”不用于摔倒造成的伤，要说“摔伤”。"}, {"text": "他被热汤烫到，生病了，手上起了水泡。", "explanation": "这里应该用〈烫伤〉。“生病”不用于热汤造成的伤，要说“烫伤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13170, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我上周很生病了。", "corrected_sentence": "我上周生病了。", "error_description": "“生病”是动词，不能受程度副词“很”修饰，“很生病”不通。去掉“很”，应为“我上周生病了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13170, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他前天就生病了一场。", "corrected_sentence": "他前天就病了一场。", "error_description": "“生病”是离合词，不能整体带“了一场”。去掉“生”，应为“他前天就病了一场。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1936bb86-542e-4257-af57-a5462b686234') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
