INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13171, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13171, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "纸袋是一种用纸张制成的袋子，常用于购物或包装物品。", "primary_collocate": null, "pronunciation": "zhǐ dài", "ipa": "ʈʂɻ̩˨˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "人们希望以后用纸袋或布袋。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我把买来的面包放进纸袋里了。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个纸袋很结实，可以装三本书。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市给了我一个纸袋，不用塑料袋。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用纸袋装着刚烤好的饼干。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨时纸袋容易湿，不能装书。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈提着一个纸袋去上班。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡店的纸袋上印着一朵小花。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个纸袋可以用很多次。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把礼物放在红色的纸袋里。", "target_word": "纸袋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个纸袋", "label": "量词"}, {"form": "紙袋", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用纸张制成、用于购物或包装的袋子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '840fc245-6719-4ace-a4d0-78c0a43c1a8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13171, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纸袋", "is_correct": true, "explanation": "正确：句中“纸袋”与“布袋”并列，都是可以替代塑料袋的环保袋。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：垃圾桶是用来装垃圾的，不能与“布袋”并列作为可以替代的袋子。"}, {"text": "一次性餐具", "is_correct": false, "explanation": "语义：“或布袋”要求前后都是袋子，一次性餐具不是用来装东西的袋子。"}, {"text": "囊", "is_correct": false, "explanation": "语域：“囊”是书面语，不用于这种口语化的日常环保提议。"}], "explanations": {"纸袋": "正确：句中“纸袋”与“布袋”并列，都是可以替代塑料袋的环保袋。", "垃圾桶": "语义：垃圾桶是用来装垃圾的，不能与“布袋”并列作为可以替代的袋子。", "一次性餐具": "语义：“或布袋”要求前后都是袋子，一次性餐具不是用来装东西的袋子。", "囊": "语域：“囊”是书面语，不用于这种口语化的日常环保提议。"}, "sentence_index": 0, "correct_answer": "纸袋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用纸袋切菜，切得又快又好。", "explanation": "这里应该用〈刀〉。切菜要用刀，纸袋不能用来切菜。"}, {"text": "他咬了一口纸袋，觉得很好吃。", "explanation": "这里应该用〈饼干〉。纸袋是用来装东西的，不能吃，“好吃”应用于食物，要说饼干。"}, {"text": "冬天他戴着纸袋出门，手很暖和。", "explanation": "这里应该用〈手套〉。冬天戴在手上保暖的是手套，纸袋不能让手暖和。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13171, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纸袋", "is_correct": true, "explanation": "正确：“提着”的是一个袋子，纸袋可以拎在手里带去上班。"}, {"text": "老板", "is_correct": false, "explanation": "语义：“老板”是人，不能像袋子一样被“提着”去上班，句意不通。"}, {"text": "小孩", "is_correct": false, "explanation": "语义：“小孩”是人，不能被拎在手里带去上班。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“提”用于能拎在手里的东西，冰箱太大太重，只能说“搬”。"}], "explanations": {"纸袋": "正确：“提着”的是一个袋子，纸袋可以拎在手里带去上班。", "老板": "语义：“老板”是人，不能像袋子一样被“提着”去上班，句意不通。", "小孩": "语义：“小孩”是人，不能被拎在手里带去上班。", "冰箱": "搭配：“提”用于能拎在手里的东西，冰箱太大太重，只能说“搬”。"}, "sentence_index": 6, "correct_answer": "纸袋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用纸袋洗澡，洗得很干净。", "explanation": "这里应该用〈肥皂〉。洗澡要用肥皂或沐浴露，纸袋不能用来洗澡。"}, {"text": "他用纸袋扫地，把屋子打扫得很干净。", "explanation": "这里应该用〈扫把〉。扫地要用扫把，纸袋不能用来扫地。"}, {"text": "他用纸袋喝水，一口一口慢慢喝。", "explanation": "这里应该用〈杯子〉。喝水要用杯子，纸袋不能用来盛水喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13171, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用一张纸袋装了两个苹果。", "corrected_sentence": "他用一个纸袋装了两个苹果。", "error_description": "量词错误：“纸袋”是立体的袋子，量词应用“个”，不能用平面物体的量词“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13171, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把饼干装进纸袋上了。", "corrected_sentence": "她把饼干装进纸袋里了。", "error_description": "方位词错误：把东西装进袋子应说“纸袋里”，“上”表示在表面之上，不能说“纸袋上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
