INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13172, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用布制成的袋子，用于盛装物品。", "primary_collocate": null, "pronunciation": "bù dài", "ipa": "pu˥˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "人们希望以后用纸袋或布袋。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个布袋可以洗，也可以用很多年。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶背着一个蓝色的布袋去市场。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把大米倒进布袋里了。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "布袋用脏了，洗干净还能再用。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买菜时我总带着自己的布袋。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个布袋上绣着一只小猫。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "布袋很软，可以折起来放进包里。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把钱放在布袋里，藏在床下。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校送给每个学生一个布袋。", "target_word": "布袋", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个布袋", "label": "量词"}], "register": "中性", "sense_fingerprint": "用布制成、用来盛装物品的袋子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '840fc245-6719-4ace-a4d0-78c0a43c1a8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13172, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "布袋", "is_correct": true, "explanation": "正确：句中与“纸袋”并列，同为替代塑料袋的环保袋。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：垃圾桶是用来装垃圾的，不能与“纸袋”并列作为可以替代的袋子。"}, {"text": "购物车", "is_correct": false, "explanation": "语义：购物车不是袋子，不能与“纸袋”并列作为替代选择。"}, {"text": "囊", "is_correct": false, "explanation": "语域：“囊”是书面语，不用于这样口语化的日常提议。"}], "explanations": {"布袋": "正确：句中与“纸袋”并列，同为替代塑料袋的环保袋。", "垃圾桶": "语义：垃圾桶是用来装垃圾的，不能与“纸袋”并列作为可以替代的袋子。", "购物车": "语义：购物车不是袋子，不能与“纸袋”并列作为替代选择。", "囊": "语域：“囊”是书面语，不用于这样口语化的日常提议。"}, "sentence_index": 0, "correct_answer": "布袋"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用布袋切西瓜，切成了八块。", "explanation": "这里应该用〈刀〉。切西瓜要用刀，布袋不能用来切东西。"}, {"text": "伤口上盖着布袋，过几天就好了。", "explanation": "这里应该用〈纱布〉。伤口要用纱布包扎，布袋不能用来护理伤口。"}, {"text": "她用布袋梳头，头发梳得很整齐。", "explanation": "这里应该用〈梳子〉。梳头要用梳子，布袋不能用来梳头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13172, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "布袋", "is_correct": true, "explanation": "正确：“上绣着一只小猫”的是布做的袋子，布袋可以绣花。"}, {"text": "纸袋", "is_correct": false, "explanation": "搭配：“绣”只用于布料，纸袋不能绣花。"}, {"text": "垃圾袋", "is_correct": false, "explanation": "语义：垃圾袋是用来装垃圾的，不会有绣花装饰。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“绣”只用于布料，石头不能绣花。"}], "explanations": {"布袋": "正确：“上绣着一只小猫”的是布做的袋子，布袋可以绣花。", "纸袋": "搭配：“绣”只用于布料，纸袋不能绣花。", "垃圾袋": "语义：垃圾袋是用来装垃圾的，不会有绣花装饰。", "石头": "搭配：“绣”只用于布料，石头不能绣花。"}, "sentence_index": 6, "correct_answer": "布袋"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用布袋烧水，水很快就开了。", "explanation": "这里应该用〈水壶〉。烧水要用水壶，布袋不能用来烧水。"}, {"text": "他用布袋盛汤，一口一口喝下去。", "explanation": "这里应该用〈碗〉。盛汤要用碗，布袋不能用来盛汤。"}, {"text": "她戴上布袋看书，眼睛很舒服。", "explanation": "这里应该用〈眼镜〉。“戴”用于眼镜、帽子等，布袋不能戴在眼睛上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用一条布袋装了几本书。", "corrected_sentence": "他用一个布袋装了几本书。", "error_description": "量词错误：布袋是立体的袋子，量词应用“个”，“条”用于细长的物体，不能用于布袋。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶把花生装进布袋上了。", "corrected_sentence": "奶奶把花生装进布袋里了。", "error_description": "方位词错误：把东西装进袋子应说“布袋里”，“上”表示在表面之上，不能说“布袋上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15915be1-baee-4f47-99c7-a327bce43e20') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
