INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13176, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "选择并实施（某种方法、策略、措施等）。", "primary_collocate": null, "pronunciation": "cǎi qǔ", "ipa": "tsʰaɪ²¹⁴ tɕʰy²¹⁴", "syllable_count": 2, "sentences": [{"text": "不同国家采取了不同的监管方法。", "target_word": "采取", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "公司采取了新的办法，解决了问题。", "target_word": "采取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府决定采取措施，保护河水。", "target_word": "采取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到有人受伤，医生马上采取行动。", "target_word": "采取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校采取了很多办法，提高学生的成绩。", "target_word": "采取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面对困难，我们要采取有效的办法。", "target_word": "采取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太热，工厂采取了新的安全措施。", "target_word": "采取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院对这种病采取了特别的治疗方法。", "target_word": "采取", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察没有马上采取行动，而是先等了一会儿。", "target_word": "采取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对不同的学生采取不同的教法。", "target_word": "采取", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "采取了", "label": "完成体"}, {"form": "采取过", "label": "经历体"}, {"form": "採取", "label": "繁体"}], "register": "中性", "sense_fingerprint": "选择并实施某种方法、措施或态度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3530f0c-2ea7-4f92-a396-cbac9f313f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13176, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，“监管方法”不能被吃。"}, {"text": "采取", "is_correct": true, "explanation": "采取：选择并实施某种方法、措施，与“监管方法”搭配，符合句中的语境。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”接衣物，不能说“穿方法”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，与“监管方法”不相容。"}], "explanations": {"吃": "语义：“吃”指进食，“监管方法”不能被吃。", "采取": "采取：选择并实施某种方法、措施，与“监管方法”搭配，符合句中的语境。", "穿": "搭配：“穿”接衣物，不能说“穿方法”。", "唱": "语义：“唱”指发声演唱，与“监管方法”不相容。"}, "sentence_index": 0, "correct_answer": "采取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从桌子上采取了一个苹果。", "explanation": "这里应该用〈拿〉。采取用于方法、措施，从桌上取东西要说“拿”。"}, {"text": "法院采取了判决，结束了案件。", "explanation": "这里应该用〈做出〉。采取针对方法、措施，判决是结果，要说“做出判决”。"}, {"text": "周末我们去果园，采取了很多草莓。", "explanation": "这里应该用〈采摘〉。采取用于方法、措施，摘草莓要说“采摘”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13176, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用，“安全措施”不能被喝。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”指使燃烧，“安全措施”不能被点燃。"}, {"text": "采取", "is_correct": true, "explanation": "采取：选择并实施措施，与“安全措施”搭配，符合句中的语境。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”接帽子、眼镜等，不接“措施”。"}], "explanations": {"喝": "语义：“喝”指饮用，“安全措施”不能被喝。", "点燃": "语义：“点燃”指使燃烧，“安全措施”不能被点燃。", "采取": "采取：选择并实施措施，与“安全措施”搭配，符合句中的语境。", "戴": "搭配：“戴”接帽子、眼镜等，不接“措施”。"}, "sentence_index": 6, "correct_answer": "采取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府采取了通知，要求大家注意安全。", "explanation": "这里应该用〈发出〉。采取用于方法、措施，通知要说“发出”。"}, {"text": "政府采取了新法律，规定了安全标准。", "explanation": "这里应该用〈颁布〉。采取用于方法、措施，法律要说“颁布”。"}, {"text": "我们采取了目标，今年完成了任务。", "explanation": "这里应该用〈实现〉。采取用于方法、措施，目标要说“实现”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没有采取了这个办法。", "corrected_sentence": "他没有采取这个办法。", "error_description": "错误形式是“没有采取了”，正确形式是“没有采取”。“没有”否定已完成的动作时，句中不能再用“了”，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府采取了一把新的措施。", "corrected_sentence": "政府采取了一项新的措施。", "error_description": "量词错误：“措施”应用量词“项”，说“一项新的措施”。量词“把”用于有柄的器具，不能修饰“措施”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13178, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "免费", "is_correct": true, "explanation": "正确。“免费”与“付费”意思相反，指不用付钱就能获得。"}, {"text": "上传", "is_correct": false, "explanation": "上传指把文件送到网络上，与“付费”的意思没有对立关系。"}, {"text": "观看", "is_correct": false, "explanation": "观看指看视频或节目，与“付费”不是反义关系。"}, {"text": "收藏", "is_correct": false, "explanation": "收藏指把喜欢的东西保存起来，与“付费”没有反义关系。"}], "correct_answer": "免费", "explanations": {"免费": "正确。“免费”与“付费”意思相反，指不用付钱就能获得。", "上传": "上传指把文件送到网络上，与“付费”的意思没有对立关系。", "观看": "观看指看视频或节目，与“付费”不是反义关系。", "收藏": "收藏指把喜欢的东西保存起来，与“付费”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13178, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "免费", "is_correct": true, "explanation": "正确。“免费”与“付费”意思相反，指不用付钱。"}, {"text": "分享", "is_correct": false, "explanation": "分享指把东西与别人一起使用，与“付费”不是反义关系。"}, {"text": "评论", "is_correct": false, "explanation": "评论指发表看法，与“付费”没有反义关系。"}, {"text": "转发", "is_correct": false, "explanation": "转发指把内容传给别人，与“付费”没有反义关系。"}], "correct_answer": "免费", "explanations": {"免费": "正确。“免费”与“付费”意思相反，指不用付钱。", "分享": "分享指把东西与别人一起使用，与“付费”不是反义关系。", "评论": "评论指发表看法，与“付费”没有反义关系。", "转发": "转发指把内容传给别人，与“付费”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13178, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指为获得某种商品或服务而支付费用。", "primary_collocate": null, "pronunciation": "fù fèi", "ipa": "fu˥˩ feɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这项规定要求生产者承担更多的延伸责任，还推动产品设计向循环使用转变，让“使用者付费”成了越来越常见的做法。", "target_word": "付费", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "有些国家禁止超市免费提供塑料袋，人们需要付费购买，这样可以减少使用量。", "target_word": "付费", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "看这部电影要先付费。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件的高级功能要付费。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你付费以后就可以下载了。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人愿意为好内容付费。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们要求用户每个月付费一次。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经付费了，请给我发票。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停车场出口处可以用手机付费。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个网站看全文需要付费。", "target_word": "付费", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "付了费", "label": "体标"}, {"form": "付过费", "label": "体标"}, {"form": "付費", "label": "繁体"}, {"form": "付费用户", "label": "复合"}], "register": "中性", "sense_fingerprint": "为得到商品或服务而支付费用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c0440af-c60e-4c64-8601-be0f673c410c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13178, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "付费", "is_correct": true, "explanation": "正确。“使用者付费”指由使用商品或服务的人支付费用，与句中的责任要求和普遍做法相符。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：“使用者跑步”与生产者责任、产品设计的语境毫无关系，不能构成一种收费做法。"}, {"text": "生产", "is_correct": false, "explanation": "语义：“生产”说的是制造，不能表示使用者支付费用。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”与“使用者”搭配不通，不能指这种付费做法。"}], "explanations": {"付费": "正确。“使用者付费”指由使用商品或服务的人支付费用，与句中的责任要求和普遍做法相符。", "跑步": "语义：“使用者跑步”与生产者责任、产品设计的语境毫无关系，不能构成一种收费做法。", "生产": "语义：“生产”说的是制造，不能表示使用者支付费用。", "装饰": "搭配：“装饰”与“使用者”搭配不通，不能指这种付费做法。"}, "sentence_index": 0, "correct_answer": "付费"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每年都向希望工程付费。", "explanation": "这里应该用〈捐款〉。付费指为获得商品或服务交钱，捐助不换取任何东西，不能说付费。"}, {"text": "他因为超速被罚，只好付费。", "explanation": "这里应该用〈交罚款〉。付费指为获得商品或服务交钱，罚款不换取任何服务，不能说付费。"}, {"text": "我们要向英雄付费。", "explanation": "这里应该用〈致敬〉。付费指交钱获得服务，向英雄表达敬意不能用付费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13178, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "付费", "is_correct": true, "explanation": "正确。“要求用户每个月付费一次”指用户按月交费，符合句意。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“要求用户每个月睡觉一次”没有实际意义，与句中的付费要求无关。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：要求用户“每个月吃饭一次”没有实际意义，与句意不合。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：“每个月……一次”不能用来要求结婚这类行为，搭配不通。"}], "explanations": {"付费": "正确。“要求用户每个月付费一次”指用户按月交费，符合句意。", "睡觉": "语义：“要求用户每个月睡觉一次”没有实际意义，与句中的付费要求无关。", "吃饭": "语义：要求用户“每个月吃饭一次”没有实际意义，与句意不合。", "结婚": "搭配：“每个月……一次”不能用来要求结婚这类行为，搭配不通。"}, "sentence_index": 6, "correct_answer": "付费"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在路上捡到一个钱包，就付费交给了警察。", "explanation": "这里应该用〈交给〉。付费指为获得商品或服务交钱，把捡到的东西交给警察是无偿的，不能说付费。"}, {"text": "小猫付费抓老鼠。", "explanation": "搭配：小猫不能付费，“付费”的主体应是人或机构，搭配不通。"}, {"text": "他们每天付费呼吸，很辛苦。", "explanation": "搭配：呼吸是人的本能，不是可以付费获得的服务，搭配不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13178, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你付费过以后才能下载这首歌。", "corrected_sentence": "你付过费以后才能下载这首歌。", "error_description": "体标位置错误：“过”应紧跟动词，应说“付过费”，不能放在“付费”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13178, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "用户付费完以后就可以下载了。", "corrected_sentence": "用户付完费以后就可以下载了。", "error_description": "结果补语位置错误：“完”应紧跟动词，应说“付完费”，不能说“付费完”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
