INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13179, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指使用某物的数量或频率。", "primary_collocate": null, "pronunciation": "shǐ yòng liàng", "ipa": "ʂʐ̩²¹⁴ jʊŋ⁵¹ ljaŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "有些国家禁止超市免费提供塑料袋，人们需要付费购买，这样可以减少使用量。", "target_word": "使用量", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "夏天空调的使用量很大。", "target_word": "使用量", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个月手机的使用量比上个月多。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "塑料袋的使用量一年比一年少。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院药品的使用量需要每天记录。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气越冷，暖气的使用量就越大。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校想知道电脑室的使用量，所以做了记录。", "target_word": "使用量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水的使用量太大，城市可能会缺水。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每月都看一看家里电的使用量。", "target_word": "使用量", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司用新机器以后，纸的使用量少了很多。", "target_word": "使用量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "使用某物的数量或频率", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3530f0c-2ea7-4f92-a396-cbac9f313f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13179, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "形状", "is_correct": false, "explanation": "语义：“减少”说数量变少，“形状”不是可以减少的量。"}, {"text": "使用量", "is_correct": true, "explanation": "使用量：某物用的数量或频率，与“减少”搭配，指用得变少。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指外观，不是可以减少的数量，不能说“减少颜色”。"}, {"text": "作者", "is_correct": false, "explanation": "语义：“作者”指写作的人，不能被减少。"}], "explanations": {"形状": "语义：“减少”说数量变少，“形状”不是可以减少的量。", "使用量": "使用量：某物用的数量或频率，与“减少”搭配，指用得变少。", "颜色": "语义：“颜色”指外观，不是可以减少的数量，不能说“减少颜色”。", "作者": "语义：“作者”指写作的人，不能被减少。"}, "sentence_index": 0, "correct_answer": "使用量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家超市的顾客使用量很多。", "explanation": "这里应该用〈数量〉。使用量指用在物品上的多少，说人的数目要用“数量”。"}, {"text": "这种工具的使用量很广。", "explanation": "这里应该用〈用途〉。使用量只指用的多少，说用处广要用“用途”。"}, {"text": "这条路的使用量很长。", "explanation": "这里应该用〈长度〉。使用量不说长短，说路的长短要用“长度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13179, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性格", "is_correct": false, "explanation": "语义：“性格”指人的个性，不能用来指电脑室。"}, {"text": "使用量", "is_correct": true, "explanation": "使用量：某物用的数量或频率，学校记录的正是这类数据。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人的性情，不能用于电脑室。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的高矮，不能用于电脑室。"}], "explanations": {"性格": "语义：“性格”指人的个性，不能用来指电脑室。", "使用量": "使用量：某物用的数量或频率，学校记录的正是这类数据。", "脾气": "语义：“脾气”指人的性情，不能用于电脑室。", "身高": "语义：“身高”指人的高矮，不能用于电脑室。"}, "sentence_index": 6, "correct_answer": "使用量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵老树的使用量很大。", "explanation": "这里应该用〈树龄〉。使用量指用的多少，说树的年数要用“树龄”。"}, {"text": "孩子的使用量增加了五厘米。", "explanation": "这里应该用〈身高〉。使用量不说人的高矮，孩子长高要用“身高”。"}, {"text": "这次会议的使用量很短。", "explanation": "这里应该用〈时间〉。使用量只说用的多少，说会议长短要用“时间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13179, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月网络的使用量的很大。", "corrected_sentence": "这个月网络的使用量很大。", "error_description": "错误形式是“使用量的很大”，正确形式是“使用量很大”。“使用量”后直接接形容词作谓语时不加“的”，多出的“的”应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13179, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家今年电的使用量大很。", "corrected_sentence": "我家今年电的使用量很大。", "error_description": "错误形式是“使用量大很”，正确形式是“使用量很大”。程度副词“很”应放在形容词“大”之前，不能放在其后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
