INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13180, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以塑料为原料制成的各种物品或商品。", "primary_collocate": null, "pronunciation": "sù liào chǎn pǐn", "ipa": "su˥˩ liɑu˥˩ ʈʂʰan˨˩˦ pʰin˨˩˦", "syllable_count": 4, "sentences": [{"text": "另一些国家完全禁止某些塑料产品，比如塑料吸管和餐具。", "target_word": "塑料产品", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "很多国家想减少塑料产品的使用。", "target_word": "塑料产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料产品很轻，也很便宜。", "target_word": "塑料产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的塑料产品越来越少了。", "target_word": "塑料产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂用石油做原料，每天生产很多塑料产品。", "target_word": "塑料产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料产品用完以后，要放进回收箱。", "target_word": "塑料产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧的塑料产品可以变成新的东西。", "target_word": "塑料产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不再卖一次性塑料产品了。", "target_word": "塑料产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的塑料产品会伤害海洋动物。", "target_word": "塑料产品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要求学生少用塑料产品。", "target_word": "塑料产品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "件", "label": "量词"}, {"form": "塑料產品", "label": "繁体"}], "register": "中性", "sense_fingerprint": "塑料产品:以塑料为原料制成的各种物品或商品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c18457a1-9dcd-4551-8484-b67740909c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13180, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食物", "is_correct": false, "explanation": "语义：塑料吸管和餐具不是食物，“禁止某些食物”与后面的例子矛盾。"}, {"text": "机器", "is_correct": false, "explanation": "语义：塑料吸管和餐具不是机器，“机器”与例子不属于同一类。"}, {"text": "金属", "is_correct": false, "explanation": "搭配：“某些”后接的应是具体物品，“金属”是材料名，不能与“吸管和餐具”并列作被禁对象。"}, {"text": "塑料产品", "is_correct": true, "explanation": "“塑料产品”指以塑料为原料制成的物品，与“塑料吸管和餐具”同类，填入后语义通顺。"}], "explanations": {"食物": "语义：塑料吸管和餐具不是食物，“禁止某些食物”与后面的例子矛盾。", "机器": "语义：塑料吸管和餐具不是机器，“机器”与例子不属于同一类。", "金属": "搭配：“某些”后接的应是具体物品，“金属”是材料名，不能与“吸管和餐具”并列作被禁对象。", "塑料产品": "“塑料产品”指以塑料为原料制成的物品，与“塑料吸管和餐具”同类，填入后语义通顺。"}, "sentence_index": 0, "correct_answer": "塑料产品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天喝很多塑料产品。", "explanation": "这里应该用〈饮料〉。喝的东西要说〈饮料〉，塑料产品是成品，不能用来喝。"}, {"text": "他给我讲了一个塑料产品。", "explanation": "这里应该用〈故事〉。讲的是故事、道理这类内容，塑料产品是物品，不能用来讲。"}, {"text": "这个孩子用一件塑料产品捏了一只小猫。", "explanation": "这里应该用〈橡皮泥〉。捏东西要用可塑的材料，已经成型的塑料产品不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a55bea00-461f-4ed7-af4a-d73c39a0be1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13180, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人", "is_correct": false, "explanation": "语义：人不能被变成“新的东西”，与“旧的”和回收改造的语境不符。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：朋友是人际关系，不是可以回收改造的物品，与“变成新的东西”冲突。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“变成”后接的应是可回收改造的物品，“空气”是不可回收的物质，搭配不当。"}, {"text": "塑料产品", "is_correct": true, "explanation": "“旧的塑料产品”指用过的塑料制品，可以回收改造，与“变成新的东西”相符。"}], "explanations": {"人": "语义：人不能被变成“新的东西”，与“旧的”和回收改造的语境不符。", "朋友": "语义：朋友是人际关系，不是可以回收改造的物品，与“变成新的东西”冲突。", "空气": "搭配：“变成”后接的应是可回收改造的物品，“空气”是不可回收的物质，搭配不当。", "塑料产品": "“旧的塑料产品”指用过的塑料制品，可以回收改造，与“变成新的东西”相符。"}, "sentence_index": 6, "correct_answer": "塑料产品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生给他开了很多塑料产品。", "explanation": "这里应该用〈药品〉。医生开的是药，塑料产品不能治病，也不能开给病人。"}, {"text": "妈妈每天给我们吃一些塑料产品。", "explanation": "这里应该用〈食物〉。人吃的东西要说〈食物〉，塑料产品不能吃。"}, {"text": "这家超市的塑料产品很新鲜。", "explanation": "这里应该用〈食品〉。新鲜形容食物，塑料产品不能说新鲜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a55bea00-461f-4ed7-af4a-d73c39a0be1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店卖一只新的塑料产品。", "corrected_sentence": "这家店卖一件新的塑料产品。", "error_description": "量词错误：“塑料产品”应用“件”或“种”计量；“只”多用于动物或成对东西中的一个（如“一只手”），不能用来计量塑料产品。应说“一件新的塑料产品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a55bea00-461f-4ed7-af4a-d73c39a0be1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了一张塑料产品。", "corrected_sentence": "他买了一件塑料产品。", "error_description": "量词错误：“张”用于纸张、桌子等扁平的东西，“塑料产品”应用“件”计量。应说“一件塑料产品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a55bea00-461f-4ed7-af4a-d73c39a0be1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
