INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13185, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a55bea00-461f-4ed7-af4a-d73c39a0be1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13185, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "押金是为了担保合同或协议的履行而预先支付的钱款，在合同履行完毕后，若无违约情况，可以收回。", "primary_collocate": null, "pronunciation": "yā jīn", "ipa": "ja˥ tɕin˥", "syllable_count": 2, "sentences": [{"text": "在欧洲，一些国家要求商店对塑料瓶收取押金。", "target_word": "押金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "顾客买饮料时多付一点钱，归还空瓶后可以拿回押金。", "target_word": "押金", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "租房子时，房东要先收两千元押金。", "target_word": "押金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "退房以后，房东把押金还给了我。", "target_word": "押金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租自行车要付一百元押金。", "target_word": "押金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弄坏了东西，所以拿不回押金。", "target_word": "押金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店前台说，入住要先交押金。", "target_word": "押金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "押金不是房租，以后还会退给你。", "target_word": "押金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个共享充电宝的押金是九十九元。", "target_word": "押金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把东西还回来，我就把押金退给你。", "target_word": "押金", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "押金制度", "label": "复合"}], "register": "中性", "sense_fingerprint": "押金:为担保合同履行而预先支付、事后可收回的钱款", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c18457a1-9dcd-4551-8484-b67740909c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13185, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "押金", "is_correct": true, "explanation": "正确：押金（yā jīn）是为担保而预先支付、事后可退还的钱。"}, {"text": "压紧", "is_correct": false, "explanation": "压紧（yā jǐn，第三声）与 yā jīn（第一声）声调不同，意思是紧紧按住。"}, {"text": "压惊", "is_correct": false, "explanation": "压惊（yā jīng）与 yā jīn 韵母不同（-ing 与 -in），意思是安慰受惊的人。"}, {"text": "压进", "is_correct": false, "explanation": "压进（yā jìn，第四声）与 yā jīn（第一声）声调不同，意思是压入。"}], "explanations": {"押金": "正确：押金（yā jīn）是为担保而预先支付、事后可退还的钱。", "压紧": "压紧（yā jǐn，第三声）与 yā jīn（第一声）声调不同，意思是紧紧按住。", "压惊": "压惊（yā jīng）与 yā jīn 韵母不同（-ing 与 -in），意思是安慰受惊的人。", "压进": "压进（yā jìn，第四声）与 yā jīn（第一声）声调不同，意思是压入。"}, "sentence_index": null, "correct_answer": "押金"}, "level_3": {"options": [{"text": "押金", "is_correct": true, "explanation": "正确：“收取押金”指先收一笔钱、事后退还，与塑料瓶回收的语境相符。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：“饮料”是瓶中装的东西，不是可以收取的费用，“收取饮料”说不通。"}, {"text": "瓶盖", "is_correct": false, "explanation": "语义：“瓶盖”只是瓶子的部件，不能作为费用被收取。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“收取”后接的应是钱款，“颜色”不能被收取。"}], "explanations": {"押金": "正确：“收取押金”指先收一笔钱、事后退还，与塑料瓶回收的语境相符。", "饮料": "语义：“饮料”是瓶中装的东西，不是可以收取的费用，“收取饮料”说不通。", "瓶盖": "语义：“瓶盖”只是瓶子的部件，不能作为费用被收取。", "颜色": "搭配：“收取”后接的应是钱款，“颜色”不能被收取。"}, "sentence_index": 0, "correct_answer": "押金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每个月交两千元押金。", "explanation": "这里应该用〈房租〉。押金是一次性预付、事后退还的钱，每月定期交的是房租。"}, {"text": "他每个月领押金。", "explanation": "这里应该用〈工资〉。押金是担保用、事后退还的钱，不是按月发放的收入，不能每月领取。"}, {"text": "打车后我给司机一块钱押金。", "explanation": "这里应该用〈小费〉。押金是担保用、事后要退还的钱，给司机的额外感谢钱要用“小费”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a55bea00-461f-4ed7-af4a-d73c39a0be1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13185, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "押金", "is_correct": true, "explanation": "正确：入住酒店要先交的是押金，退房后可以退还。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是领取的报酬，不是入住时交给酒店的钱。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：“交”的对象是钱款或证件，不说“交早餐”。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是交通工具，入住酒店时不可能“交”地铁。"}], "explanations": {"押金": "正确：入住酒店要先交的是押金，退房后可以退还。", "工资": "语义：工资是领取的报酬，不是入住时交给酒店的钱。", "早餐": "搭配：“交”的对象是钱款或证件，不说“交早餐”。", "地铁": "语义：地铁是交通工具，入住酒店时不可能“交”地铁。"}, "sentence_index": 6, "correct_answer": "押金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司裁员后要给员工押金。", "explanation": "这里应该用〈补偿金〉。押金是担保用、事后退还的钱，不是用来补偿员工的钱。"}, {"text": "朋友送给我一笔押金当生日礼物。", "explanation": "这里应该用〈礼金〉。押金是担保用、事后要退还的钱，不能当作赠品送人；送人的贺礼钱要用“礼金”。"}, {"text": "银行每年付给存款人押金。", "explanation": "这里应该用〈利息〉。利息是存款按期产生的收益，押金是担保用的钱，不是银行付给存款人的收益。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a55bea00-461f-4ed7-af4a-d73c39a0be1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13185, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他交了一本押金，下个月就能拿回来。", "corrected_sentence": "他交了一笔押金，下个月就能拿回来。", "error_description": "量词错误：“本”用于书籍等，不能用来计量“押金”，应用量词“笔”。应改为“一笔押金”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a55bea00-461f-4ed7-af4a-d73c39a0be1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13185, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我交了两百个押金，搬出去就能拿回来。", "corrected_sentence": "我交了两百元押金，搬出去就能拿回来。", "error_description": "量词错误：押金的金额应用“元”计量，“个”不能用来计量押金，应说“两百元押金”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a55bea00-461f-4ed7-af4a-d73c39a0be1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
