INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13188, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指已经用尽内容物、没有剩余液体的瓶子。", "primary_collocate": null, "pronunciation": "kōng píng", "ipa": "kʰʊŋ⁵⁵ pʰiŋ³⁵", "syllable_count": 2, "sentences": [{"text": "顾客买饮料时多付一点钱，归还空瓶后可以拿回押金。", "target_word": "空瓶", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "桌子上放着三个空瓶。", "target_word": "空瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝完水后，他把空瓶扔进了垃圾桶。", "target_word": "空瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市门口有一个回收空瓶的机器。", "target_word": "空瓶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些空瓶可以拿去换钱。", "target_word": "空瓶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子把空瓶放在了袋子里。", "target_word": "空瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的床下有很多空瓶。", "target_word": "空瓶", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈每周把空瓶送到回收站。", "target_word": "空瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上的空瓶是昨天晚上留下的。", "target_word": "空瓶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "饭馆的后门放着一排空瓶。", "target_word": "空瓶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个空瓶", "label": "量词"}, {"form": "空瓶子", "label": "复合"}], "register": "中性", "sense_fingerprint": "里面的东西已用完的瓶子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c18457a1-9dcd-4551-8484-b67740909c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13188, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空瓶", "is_correct": true, "explanation": "空瓶是要归还的对象，归还后才能拿回押金，符合句意。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：押金是为空瓶付的，归还饮料并不能拿回押金。"}, {"text": "瓶盖", "is_correct": false, "explanation": "语义：拿回押金要靠交还空瓶，瓶盖不能换回押金。"}, {"text": "硬币", "is_correct": false, "explanation": "搭配：“归还硬币”不成立，硬币不是押金回收的对象。"}], "explanations": {"空瓶": "空瓶是要归还的对象，归还后才能拿回押金，符合句意。", "饮料": "语义：押金是为空瓶付的，归还饮料并不能拿回押金。", "瓶盖": "语义：拿回押金要靠交还空瓶，瓶盖不能换回押金。", "硬币": "搭配：“归还硬币”不成立，硬币不是押金回收的对象。"}, "sentence_index": 0, "correct_answer": "空瓶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌子上放着三条空瓶。", "explanation": "这里应该用〈个〉。空瓶的量词是“个”，“条”用于细长的物体。"}, {"text": "他拿着一张空瓶，站在门口。", "explanation": "这里应该用〈个〉。“张”用于纸张、桌子等扁平物，瓶子应用“个”。"}, {"text": "喝完水后，他把一块空瓶扔进了垃圾桶。", "explanation": "这里应该用〈个〉。“块”用于块状物，瓶子应用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a55bea00-461f-4ed7-af4a-d73c39a0be1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13188, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空瓶", "is_correct": true, "explanation": "空瓶可以放在床下，符合“床下有很多”的句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能放在床下，与“床下”的位置矛盾。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海无法放在床下，与句意冲突。"}, {"text": "云朵", "is_correct": false, "explanation": "搭配：“床下有很多”后接的应是可以放在床下的物品，“云朵”不搭。"}], "explanations": {"空瓶": "空瓶可以放在床下，符合“床下有很多”的句意。", "天空": "语义：天空不能放在床下，与“床下”的位置矛盾。", "大海": "语义：大海无法放在床下，与句意冲突。", "云朵": "搭配：“床下有很多”后接的应是可以放在床下的物品，“云朵”不搭。"}, "sentence_index": 6, "correct_answer": "空瓶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "饭馆的后门放着一本空瓶。", "explanation": "这里应该用〈个〉。瓶子用量词“个”，“本”用于书籍。"}, {"text": "饭馆的后门放着一匹空瓶。", "explanation": "这里应该用〈个〉。“匹”用于马等牲畜，瓶子不能用。"}, {"text": "饭馆的后门放着一座空瓶。", "explanation": "这里应该用〈个〉。“座”用于山、桥等大型物体，瓶子不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a55bea00-461f-4ed7-af4a-d73c39a0be1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋角堆着两根空瓶。", "corrected_sentence": "屋角堆着两个空瓶。", "error_description": "错误：“两根空瓶”；正确：“两个空瓶”。“根”用于细长物，空瓶的量词应为“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a55bea00-461f-4ed7-af4a-d73c39a0be1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门口放着两辆空瓶。", "corrected_sentence": "门口放着两个空瓶。", "error_description": "错误：“两辆空瓶”；正确：“两个空瓶”。“辆”用于车辆，瓶子的量词应为“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a55bea00-461f-4ed7-af4a-d73c39a0be1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13189, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放", "is_correct": true, "explanation": "放：与“拿”构成反义，拿起与放下相对。"}, {"text": "吃", "is_correct": false, "explanation": "“吃”与“拿”没有对立关系，不构成反义。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”与“拿”没有对立关系，不构成反义。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”与“拿”没有对立关系，不构成反义。"}], "correct_answer": "放", "explanations": {"放": "放：与“拿”构成反义，拿起与放下相对。", "吃": "“吃”与“拿”没有对立关系，不构成反义。", "跑": "“跑”与“拿”没有对立关系，不构成反义。", "唱": "“唱”与“拿”没有对立关系，不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13189, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放", "is_correct": true, "explanation": "放：与“拿”构成反义，拿起与放下相对。"}, {"text": "睡", "is_correct": false, "explanation": "“睡”与“拿”没有对立关系，不构成反义。"}, {"text": "写", "is_correct": false, "explanation": "“写”与“拿”没有对立关系，不构成反义。"}, {"text": "看", "is_correct": false, "explanation": "“看”与“拿”没有对立关系，不构成反义。"}], "correct_answer": "放", "explanations": {"放": "放：与“拿”构成反义，拿起与放下相对。", "睡": "“睡”与“拿”没有对立关系，不构成反义。", "写": "“写”与“拿”没有对立关系，不构成反义。", "看": "“看”与“拿”没有对立关系，不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13189, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或其他方式抓住、取用或控制某物。", "primary_collocate": null, "pronunciation": "ná", "ipa": "na˧˥", "syllable_count": 1, "sentences": [{"text": "顾客买饮料时多付一点钱，归还空瓶后可以拿回押金。", "target_word": "拿", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他一手拿着伞，一手拿着包。", "target_word": "拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把桌上的那本书拿给我。", "target_word": "拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手很小，一只手拿不住这个苹果。", "target_word": "拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师手里拿着一支红笔。", "target_word": "拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你拿好票，别弄丢了。", "target_word": "拿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个箱子太重，我一个人拿不动。", "target_word": "拿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从书包里拿出一个本子。", "target_word": "拿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一把拿住了掉下来的杯子。", "target_word": "拿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门的时候别忘了拿钥匙。", "target_word": "拿", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "拿了", "label": "完成体"}, {"form": "拿着", "label": "持续体"}, {"form": "拿过", "label": "经历体"}, {"form": "拿走", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用手抓住、取用或控制某物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8479b504-a8bf-4b67-8890-b098f52c9ff9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13189, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拿", "is_correct": true, "explanation": "拿（ná）：用手抓住或取用某物，是本词。"}, {"text": "那", "is_correct": false, "explanation": "那（nà）与 ná 声调不同（第四声），意思是“那个”。"}, {"text": "哪", "is_correct": false, "explanation": "哪（nǎ）与 ná 声调不同（第三声），意思是“哪里”。"}, {"text": "南", "is_correct": false, "explanation": "南（nán）与 ná 韵母不同（-an 与 -a），意思是“南方”。"}, {"text": "蓝", "is_correct": false, "explanation": "蓝（lán）与 ná 声母不同（l 与 n），意思是“蓝色”。"}, {"text": "麻", "is_correct": false, "explanation": "má 与 ná 声母不同（m 与 n），意思是“麻”。"}], "explanations": {"拿": "拿（ná）：用手抓住或取用某物，是本词。", "那": "那（nà）与 ná 声调不同（第四声），意思是“那个”。", "哪": "哪（nǎ）与 ná 声调不同（第三声），意思是“哪里”。", "南": "南（nán）与 ná 韵母不同（-an 与 -a），意思是“南方”。", "蓝": "蓝（lán）与 ná 声母不同（l 与 n），意思是“蓝色”。", "麻": "má 与 ná 声母不同（m 与 n），意思是“麻”。"}, "sentence_index": null, "correct_answer": "拿"}, "level_3": {"options": [{"text": "拿", "is_correct": true, "explanation": "拿回：取回，指还空瓶后收回押金，与“归还”呼应。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”是付钱获得商品，与“归还空瓶后收回押金”的意思相反。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”只用于食物，不能与“押金”组合，“吃回”不成词。"}, {"text": "花", "is_correct": false, "explanation": "语义：“花”指花费钱财，与收回押金的意思相反。"}], "explanations": {"拿": "拿回：取回，指还空瓶后收回押金，与“归还”呼应。", "买": "语义：“买”是付钱获得商品，与“归还空瓶后收回押金”的意思相反。", "吃": "搭配：“吃”只用于食物，不能与“押金”组合，“吃回”不成词。", "花": "语义：“花”指花费钱财，与收回押金的意思相反。"}, "sentence_index": 0, "correct_answer": "拿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拿起了手，示意大家安静。", "explanation": "这里应该用〈举〉。拿起指握住或取过来某物，抬起手臂要说举起。"}, {"text": "他把外套拿在墙上。", "explanation": "这里应该用〈挂〉。拿表示用手握住或取过来，把衣服悬挂起来要说挂。"}, {"text": "他拿着女儿，笑得很开心。", "explanation": "这里应该用〈抱〉。拿表示用手握住或取过来，抱孩子要说抱，不能说拿着孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13189, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "拿", "is_correct": true, "explanation": "拿（ná）：用手抓住或取用某物，是本词。"}, {"text": "纳", "is_correct": false, "explanation": "纳（nà）与 ná 声调不同（第四声），意思是“缴纳、接受”。"}, {"text": "男", "is_correct": false, "explanation": "男（nán）与 ná 韵母不同（-an 与 -a），意思是“男性”。"}, {"text": "爬", "is_correct": false, "explanation": "pá 与 ná 声母不同（p 与 n），意思是“爬行”。"}, {"text": "茶", "is_correct": false, "explanation": "chá 与 ná 声母不同（ch 与 n），意思是“茶”。"}], "explanations": {"拿": "拿（ná）：用手抓住或取用某物，是本词。", "纳": "纳（nà）与 ná 声调不同（第四声），意思是“缴纳、接受”。", "男": "男（nán）与 ná 韵母不同（-an 与 -a），意思是“男性”。", "爬": "pá 与 ná 声母不同（p 与 n），意思是“爬行”。", "茶": "chá 与 ná 声母不同（ch 与 n），意思是“茶”。"}, "sentence_index": null, "correct_answer": "拿"}, "level_3": {"options": [{"text": "拿", "is_correct": true, "explanation": "拿不动：力气不够，搬不起来，与“箱子太重”呼应。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指唱歌，不能用来说搬不动箱子。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写不动”只说写字写不下去，不能用于搬运重物。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”指跳跃，与搬箱子的情境无关。"}], "explanations": {"拿": "拿不动：力气不够，搬不起来，与“箱子太重”呼应。", "唱": "语义：“唱”指唱歌，不能用来说搬不动箱子。", "写": "搭配：“写不动”只说写字写不下去，不能用于搬运重物。", "跳": "语义：“跳”指跳跃，与搬箱子的情境无关。"}, "sentence_index": 6, "correct_answer": "拿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿开了门，走了进去。", "explanation": "这里应该用〈推〉。拿开指拿走物品，推门要说推开。"}, {"text": "老人拿着墙慢慢走。", "explanation": "这里应该用〈扶〉。拿表示用手持物，扶墙、扶人要说扶。"}, {"text": "他进门后拿了一下灯的开关。", "explanation": "这里应该用〈按〉。拿表示用手握住或取过来，按开关要说按，不能说拿开关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13189, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正拿了伞出门。", "corrected_sentence": "他正拿着伞出门。", "error_description": "“正”表示动作正在进行，应与“着”搭配，说“正拿着伞出门”；“拿了”表示动作已经完成，与“正”的进行义矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13189, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上学的时候别忘了拿过书包。", "corrected_sentence": "上学的时候别忘了拿书包。", "error_description": "“别忘了”提醒将要做的事，不能用表示经历的“过”；应说“别忘了拿书包”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
