INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13191, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "回收率指在一定时间内，回收到的物品数量占可回收物品总量的百分比。", "primary_collocate": null, "pronunciation": "huí shōu lǜ", "ipa": "xweɪ˧˥ ʂoʊ˥˥ ly˥˩", "syllable_count": 3, "sentences": [{"text": "这个方法让塑料瓶的回收率大幅提高。", "target_word": "回收率", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我们学校的废纸回收率很高。", "target_word": "回收率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的垃圾回收率只有百分之三十。", "target_word": "回收率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新规定实施后，旧电池的回收率上升了。", "target_word": "回收率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾分类做得好，回收率就高。", "target_word": "回收率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年玻璃瓶的回收率是百分之六十。", "target_word": "回收率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天冷的时候，这种塑料的回收率会下降。", "target_word": "回收率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们：你们小区的回收率是多少？", "target_word": "回收率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回收率低，是因为大家不愿意分类。", "target_word": "回收率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告说，纸张的回收率比塑料高。", "target_word": "回收率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "垃圾回收率", "label": "复合词"}, {"form": "废纸回收率", "label": "复合词"}], "register": "中性", "sense_fingerprint": "回收物品数量占可回收总量的百分比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8479b504-a8bf-4b67-8890-b098f52c9ff9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13191, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回收率", "is_correct": true, "explanation": "正确：“回收率”指回收物品占可回收总量的百分比，可以大幅提高，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是可以用“大幅提高”衡量的数量或比率，塑料瓶的颜色不能被大幅提高。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”只随时间增长，不是可以被方法大幅提高的指标。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”只用于人或动物，不用于塑料瓶。"}], "explanations": {"回收率": "正确：“回收率”指回收物品占可回收总量的百分比，可以大幅提高，符合句意。", "颜色": "语义：“颜色”不是可以用“大幅提高”衡量的数量或比率，塑料瓶的颜色不能被大幅提高。", "年龄": "语义：“年龄”只随时间增长，不是可以被方法大幅提高的指标。", "体重": "搭配：“体重”只用于人或动物，不用于塑料瓶。"}, "sentence_index": 0, "correct_answer": "回收率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年学校回收了两吨纸，回收率比去年多。", "explanation": "这里应该用〈回收量〉。回收量是回收的数量，可以说“多”；回收率是百分比，应该说“高”或“低”。"}, {"text": "这家工厂的回收率很快。", "explanation": "这里应该用〈回收速度〉。回收率是比例，不能用“快”来形容；应该说回收速度快。"}, {"text": "这个社区的回收率很多。", "explanation": "这里应该用〈回收物〉。回收率是比例，不能用“很多”描述数量；说回收物很多才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13191, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回收率", "is_correct": true, "explanation": "正确：“回收率”是回收比例，天冷时可以下降，符合句意。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”只用于人或动物，塑料没有体温。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”只用于地区或国家，不能用于塑料。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：“成绩”指学习或工作的结果，与塑料的变化无关。"}], "explanations": {"回收率": "正确：“回收率”是回收比例，天冷时可以下降，符合句意。", "体温": "搭配：“体温”只用于人或动物，塑料没有体温。", "人口": "搭配：“人口”只用于地区或国家，不能用于塑料。", "成绩": "语义：“成绩”指学习或工作的结果，与塑料的变化无关。"}, "sentence_index": 6, "correct_answer": "回收率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市的回收率很重，有好几吨。", "explanation": "这里应该用〈回收量〉。回收率是百分比，没有重量；说回收的数量有几吨要用回收量。"}, {"text": "我们小区的回收率很贵。", "explanation": "这里应该用〈回收价格〉。回收率是比例，不能说贵或便宜；说价钱要用回收价格。"}, {"text": "报告说，纸张的回收率比塑料多两吨。", "explanation": "这里应该用〈回收量〉。回收率是百分比，不能用“吨”比较；说多两吨要用回收量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13191, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种电池的回收率被下降了。", "corrected_sentence": "这种电池的回收率下降了。", "error_description": "“被”用错了。“下降”是不及物动词，不能用于被动句，应说“这种电池的回收率下降了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13191, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市的一只回收率很高。", "corrected_sentence": "这个城市的回收率很高。", "error_description": "量词“只”用错了。“只”用于动物或成对的东西，“回收率”是比例，不能用“只”计量，应直接说“这个城市的回收率很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13192, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大幅降低", "is_correct": true, "explanation": "正确：“降低”与“提高”是反义词，“大幅降低”表示大幅减少，与“大幅提高”相对。"}, {"text": "保持", "is_correct": false, "explanation": "无反义关系：“保持”表示维持原样，不是“提高”的反义。"}, {"text": "讨论", "is_correct": false, "explanation": "无反义关系：“讨论”是交换意见，与“提高”没有对立关系。"}, {"text": "旅行", "is_correct": false, "explanation": "无反义关系：“旅行”是出行活动，与“提高”没有对立关系。"}], "correct_answer": "大幅降低", "explanations": {"大幅降低": "正确：“降低”与“提高”是反义词，“大幅降低”表示大幅减少，与“大幅提高”相对。", "保持": "无反义关系：“保持”表示维持原样，不是“提高”的反义。", "讨论": "无反义关系：“讨论”是交换意见，与“提高”没有对立关系。", "旅行": "无反义关系：“旅行”是出行活动，与“提高”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
