INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13192, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大幅度地提升或增加。", "primary_collocate": null, "pronunciation": "dà fú tí gāo", "ipa": "ta˥˩ fu˧˥ tʰi˧˥ kɑʊ˥", "syllable_count": 4, "sentences": [{"text": "这个方法让塑料瓶的回收率大幅提高。", "target_word": "大幅提高", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "学了一年后，他的汉语水平大幅提高。", "target_word": "大幅提高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新政策让工人的工资大幅提高了。", "target_word": "大幅提高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的产品质量大幅提高。", "target_word": "大幅提高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用了新机器，工作效率大幅提高。", "target_word": "大幅提高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步以后，我的身体素质大幅提高了。", "target_word": "大幅提高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的考试通过率大幅提高。", "target_word": "大幅提高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过训练，他的游泳速度大幅提高。", "target_word": "大幅提高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的空气质量大幅提高了。", "target_word": "大幅提高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，只要多练习，你的成绩会大幅提高。", "target_word": "大幅提高", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大幅提高了", "label": "体标"}, {"form": "大幅提高过", "label": "体标"}], "register": "中性", "sense_fingerprint": "水平、质量、效率、比率等大幅度地提升", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8479b504-a8bf-4b67-8890-b098f52c9ff9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13192, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大幅提高", "is_correct": true, "explanation": "正确：“大幅提高”表示比原来高很多，可以用来描述回收率，符合句意。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁”指把具体的东西烧坏，不能用于回收率的变化。"}, {"text": "倒下", "is_correct": false, "explanation": "搭配：“倒下”用于人或具体物体，不能用于回收率。"}, {"text": "跑", "is_correct": false, "explanation": "搭配：“跑”用于人或动物，不能用于回收率。"}], "explanations": {"大幅提高": "正确：“大幅提高”表示比原来高很多，可以用来描述回收率，符合句意。", "烧毁": "语义：“烧毁”指把具体的东西烧坏，不能用于回收率的变化。", "倒下": "搭配：“倒下”用于人或具体物体，不能用于回收率。", "跑": "搭配：“跑”用于人或动物，不能用于回收率。"}, "sentence_index": 0, "correct_answer": "大幅提高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年城市的人口大幅提高了一百万。", "explanation": "这里应该用〈增加〉。人口是数量，要说“增加”；“提高”用于水平、质量。"}, {"text": "工人把书架大幅提高了。", "explanation": "这里应该用〈抬高〉。书架是具体物体，它的高度变化要说“抬高”，“提高”不用于具体物体的高低。"}, {"text": "这个工程的工期大幅提高了。", "explanation": "这里应该用〈缩短〉。工期是时间，变短要说“缩短”；“提高”不能用于工期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13192, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大幅提高", "is_correct": true, "explanation": "正确：“大幅提高”表示通过率比原来高很多，符合句意。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”只用于食物，不能用于通过率。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”用于歌曲或人，不能用于通过率。"}, {"text": "摔碎", "is_correct": false, "explanation": "语义：“摔碎”指打破具体的器物，与通过率的变化无关。"}], "explanations": {"大幅提高": "正确：“大幅提高”表示通过率比原来高很多，符合句意。", "吃掉": "搭配：“吃掉”只用于食物，不能用于通过率。", "唱": "搭配：“唱”用于歌曲或人，不能用于通过率。", "摔碎": "语义：“摔碎”指打破具体的器物，与通过率的变化无关。"}, "sentence_index": 6, "correct_answer": "大幅提高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的长度大幅提高了。", "explanation": "这里应该用〈加长〉。长度变长要说“加长”；“提高”用于水平和质量，不用于长度。"}, {"text": "这次考试的错误大幅提高了。", "explanation": "这里应该用〈增加〉。错误是数量，变多要说“增加”；“提高”用于水平、质量等。"}, {"text": "他的痛苦大幅提高了。", "explanation": "这里应该用〈加剧〉。痛苦是负面的感受，变得更厉害要说“加剧”；“提高”只用于正面的水平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年的服务水平没大幅提高了。", "corrected_sentence": "今年的服务水平大幅提高了。", "error_description": "“没”是否定词，与表示变化已经发生的句末“了”矛盾；应去掉“没”，说“大幅提高了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经过训练，他的游泳速度大幅提高着。", "corrected_sentence": "经过训练，他的游泳速度大幅提高了。", "error_description": "“大幅提高”表示已经发生的变化结果，应用“了”，不能用表示持续的“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
