INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13194, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "增加力量、程度或效果。", "primary_collocate": null, "pronunciation": "jiā qiáng", "ipa": "tɕjɑ˥ tɕʰjɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "亚洲一些城市则加强垃圾分类管理，规定居民必须把塑料垃圾分开投放，否则会被罚款。", "target_word": "加强", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "学校决定加强英语教学。", "target_word": "加强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要加强锻炼，身体才会好。", "target_word": "加强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师提醒大家加强安全意识。", "target_word": "加强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司加强了对新员工的培训。", "target_word": "加强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国决定加强经济合作。", "target_word": "加强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了不再迟到，他加强了时间管理。", "target_word": "加强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察加强了夜里的检查。", "target_word": "加强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，你要加强营养，多吃蔬菜和肉。", "target_word": "加强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市加强交通管理以后，路上不堵了。", "target_word": "加强", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加强了", "label": "体标"}, {"form": "加强过", "label": "体标"}, {"form": "加強", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对管理、合作、锻炼等工作加大力度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8479b504-a8bf-4b67-8890-b098f52c9ff9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13194, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "加强", "is_correct": true, "explanation": "正确答案：加强 jiāqiáng，意思是增加力量、程度或效果。"}, {"text": "假墙", "is_correct": false, "explanation": "假墙 jiǎqiáng 与 jiāqiáng 第一音节声调不同（第三声），意思是假的墙。"}, {"text": "加钱", "is_correct": false, "explanation": "加钱 jiāqián 与 jiāqiáng 第二音节韵母不同（an 与 ang），意思是增加钱。"}, {"text": "假枪", "is_correct": false, "explanation": "假枪 jiǎqiāng 与 jiāqiáng 两个音节声调都不同，意思是玩具枪。"}], "explanations": {"加强": "正确答案：加强 jiāqiáng，意思是增加力量、程度或效果。", "假墙": "假墙 jiǎqiáng 与 jiāqiáng 第一音节声调不同（第三声），意思是假的墙。", "加钱": "加钱 jiāqián 与 jiāqiáng 第二音节韵母不同（an 与 ang），意思是增加钱。", "假枪": "假枪 jiǎqiāng 与 jiāqiáng 两个音节声调都不同，意思是玩具枪。"}, "sentence_index": null, "correct_answer": "加强"}, "level_3": {"options": [{"text": "放松", "is_correct": false, "explanation": "语义：放松是减轻约束，与后文“规定居民必须分开投放、否则罚款”的要求相矛盾。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”搭配环境、房间，不说打扫垃圾分类管理。"}, {"text": "加强", "is_correct": true, "explanation": "加强：增加管理力度，与“规定居民必须分开投放、否则罚款”的要求相符。"}, {"text": "取消", "is_correct": false, "explanation": "语义：取消管理与“规定居民必须分开投放、否则罚款”的要求相矛盾。"}], "explanations": {"放松": "语义：放松是减轻约束，与后文“规定居民必须分开投放、否则罚款”的要求相矛盾。", "打扫": "搭配：“打扫”搭配环境、房间，不说打扫垃圾分类管理。", "加强": "加强：增加管理力度，与“规定居民必须分开投放、否则罚款”的要求相符。", "取消": "语义：取消管理与“规定居民必须分开投放、否则罚款”的要求相矛盾。"}, "sentence_index": 0, "correct_answer": "加强"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的体重加强了三公斤。", "explanation": "这里应该用〈增加〉。加强指力量、程度或效果的加深，体重、人数等数量的增加要用增加。"}, {"text": "这个假期加强了三天。", "explanation": "这里应该用〈延长〉。假期时间的增加要用延长，加强指力量、程度或效果，不说加强假期。"}, {"text": "他的英语水平加强了很多。", "explanation": "这里应该用〈提高〉。水平、质量的上升用提高，加强用于力量、效果、管理等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13194, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放弃", "is_correct": false, "explanation": "语义：放弃时间管理与“为了不再迟到”的目的相反。"}, {"text": "提醒", "is_correct": false, "explanation": "搭配：“提醒”的对象是人，不能说提醒时间管理。"}, {"text": "加强", "is_correct": true, "explanation": "加强：增加时间管理的力度，与“为了不再迟到”的目的相符。"}, {"text": "减弱", "is_correct": false, "explanation": "语义：减弱时间管理与“为了不再迟到”的目的相反。"}], "explanations": {"放弃": "语义：放弃时间管理与“为了不再迟到”的目的相反。", "提醒": "搭配：“提醒”的对象是人，不能说提醒时间管理。", "加强": "加强：增加时间管理的力度，与“为了不再迟到”的目的相符。", "减弱": "语义：减弱时间管理与“为了不再迟到”的目的相反。"}, "sentence_index": 6, "correct_answer": "加强"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司加强了生产规模。", "explanation": "这里应该用〈扩大〉。规模、范围的扩大要用扩大，加强用于力量、管理、效果等。"}, {"text": "这辆车加强了三个座位。", "explanation": "这里应该用〈增加〉。座位的增加要用增加或加装，加强指力量、程度或效果，不说加强座位。"}, {"text": "这次改革加强了农民的收入。", "explanation": "这里应该用〈提升〉。收入、水平的提高用提升或提高，加强不用于收入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13194, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校把英语教学加强。", "corrected_sentence": "学校把英语教学加强了。", "error_description": "“把”字句中，动词“加强”后面要有“了”等成分。应说“学校把英语教学加强了”；只说“学校把英语教学加强”，句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13194, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校的管理加强下来了。", "corrected_sentence": "学校的管理加强起来了。", "error_description": "“加强”后的趋向补语应为“起来”，表示力量、程度逐渐增强；“下来”表示由高到低，与“加强”的方向相反。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34cd3031-bd0f-41c3-beab-80e2954d445f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
