INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13196, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使原本在一起的人或事物不再聚合。", "primary_collocate": null, "pronunciation": "fēn kāi", "ipa": "fən˥ kʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "亚洲一些城市则加强垃圾分类管理，规定居民必须把塑料垃圾分开投放，否则会被罚款。", "target_word": "分开", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "请把红笔和蓝笔分开放。", "target_word": "分开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让两个爱说话的学生分开坐。", "target_word": "分开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈把生肉和蔬菜分开放进冰箱。", "target_word": "分开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们因为工作分开了三年。", "target_word": "分开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两张纸粘在一起，很难分开。", "target_word": "分开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和哥哥小时候从来没有分开过。", "target_word": "分开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打折的衣服和新衣服要分开挂。", "target_word": "分开", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做蛋糕时，要先把蛋黄和蛋白分开。", "target_word": "分开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用手把打架的两个男孩分开了。", "target_word": "分开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分开了", "label": "体标：完成"}, {"form": "分开过", "label": "体标：经历"}, {"form": "分不开", "label": "可能补语（否定）"}], "register": "中性", "sense_fingerprint": "把原本在一起的人或事物分离，各自放置或处理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b90b6993-4408-4414-a5ca-24fcb8214168') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13196, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分开", "is_correct": true, "explanation": "正确：“分开投放”表示按类别分别投放，与“垃圾分类管理”的规定相符。"}, {"text": "混合", "is_correct": false, "explanation": "语义：“混合投放”是把垃圾混在一起，与句中“分类管理”和“必须……否则罚款”的规定相反。"}, {"text": "合并", "is_correct": false, "explanation": "搭配：“合并”多指机构、账目或事物合为一体，不与“投放”的方式搭配，句中也与分类要求相反。"}, {"text": "聚集", "is_correct": false, "explanation": "语义：“聚集”指集中到一处，与“按规定分开投放”的要求相矛盾。"}], "explanations": {"分开": "正确：“分开投放”表示按类别分别投放，与“垃圾分类管理”的规定相符。", "混合": "语义：“混合投放”是把垃圾混在一起，与句中“分类管理”和“必须……否则罚款”的规定相反。", "合并": "搭配：“合并”多指机构、账目或事物合为一体，不与“投放”的方式搭配，句中也与分类要求相反。", "聚集": "语义：“聚集”指集中到一处，与“按规定分开投放”的要求相矛盾。"}, "sentence_index": 0, "correct_answer": "分开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "睡觉前，他分开了房间里的灯。", "explanation": "这里应该用〈关〉。分开表示让原本在一起的人或东西分离，不能用来表示关灯。"}, {"text": "我和朋友分开了一个秘密。", "explanation": "这里应该用〈分享〉。分开指让原本在一起的东西拆开，不表示与别人共同拥有。"}, {"text": "他能分开这个保险箱。", "explanation": "这里应该用〈打开〉。分开指使原本在一起的东西不再聚合，不能用来表示把保险箱打开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6f6f20-c434-4a12-8f01-c3d7bddc666b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13196, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分开", "is_correct": true, "explanation": "正确：“分开过”表示曾经经历过两人分离，与“从来没有”搭配，意思是两人从未分离。"}, {"text": "离婚", "is_correct": false, "explanation": "语义：小时候的孩子不会离婚，句意荒谬。"}, {"text": "坐牢", "is_correct": false, "explanation": "语义：小时候的孩子不会坐牢，句意荒谬。"}, {"text": "长大", "is_correct": false, "explanation": "体貌：“长大”表示结果已经出现，不能用“没有……过”的经历体来说“从来没长大过”。"}], "explanations": {"分开": "正确：“分开过”表示曾经经历过两人分离，与“从来没有”搭配，意思是两人从未分离。", "离婚": "语义：小时候的孩子不会离婚，句意荒谬。", "坐牢": "语义：小时候的孩子不会坐牢，句意荒谬。", "长大": "体貌：“长大”表示结果已经出现，不能用“没有……过”的经历体来说“从来没长大过”。"}, "sentence_index": 6, "correct_answer": "分开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他往水里分开了一些糖。", "explanation": "这里应该用〈放〉。分开指使原本在一起的东西不再聚合，不能表示把糖加进水里。"}, {"text": "他一听这个消息，脸上就分开了笑容。", "explanation": "这里应该用〈露出〉。分开指使原本在一起的东西分离，不能用来表示面部表情的展现。"}, {"text": "这次考试他分开了八十分。", "explanation": "这里应该用〈得〉。分开表示使原本在一起的东西不再聚合，不能用来表示获得分数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6f6f20-c434-4a12-8f01-c3d7bddc666b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13196, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把苹果和香蕉分开得装在两个袋子里。", "corrected_sentence": "他把苹果和香蕉分开装在两个袋子里。", "error_description": "错误形式：“分开得装”。正确形式：“分开装”。“得”不能插在“分开”和“装”之间，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6f6f20-c434-4a12-8f01-c3d7bddc666b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13196, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把两箱苹果分开了了。", "corrected_sentence": "他们把两箱苹果分开了。", "error_description": "错误形式：“分开了了”。正确形式：“分开了”。“了”只能出现一次，多出的一个“了”应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c6f6f20-c434-4a12-8f01-c3d7bddc666b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
