INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13201, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "想要达到的目标或想要实现的结果。", "primary_collocate": null, "pronunciation": "mù dì", "ipa": "mu˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "值得注意的是，该项目的深层目的早已超越单纯的绿化指标。", "target_word": "目的", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "虽然各国政策不同，但目的都是减少塑料垃圾。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他学汉语的目的是去中国工作。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次开会的目的很清楚。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你问这个问题有什么目的？", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的目的是帮助大家学习。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做这件事没有别的目的。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她来这里的目的，我已经知道了。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，学习要有明确的目的。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动的目的是让大家认识新朋友。", "target_word": "目的", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "目的性", "label": "复合"}], "register": "中性", "sense_fingerprint": "做事想要达到的目标或结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77bd49ee-81b2-46c0-a146-5020ea436bdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13201, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指岁数，不能指项目所追求的深层内涵。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”不能与“深层”搭配，“深层”多修饰意义、目的一类的抽象名词。"}, {"text": "目的", "is_correct": true, "explanation": "正确：“目的”指想要达到的目标，与“超越单纯的绿化指标”的语境相符。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”指物体的轻重，不能指项目想要达到的结果。"}], "explanations": {"年龄": "语义：“年龄”指岁数，不能指项目所追求的深层内涵。", "温度": "搭配：“温度”不能与“深层”搭配，“深层”多修饰意义、目的一类的抽象名词。", "目的": "正确：“目的”指想要达到的目标，与“超越单纯的绿化指标”的语境相符。", "重量": "语义：“重量”指物体的轻重，不能指项目想要达到的结果。"}, "sentence_index": 0, "correct_answer": "目的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个目的很重，我搬不动。", "explanation": "这里应该用〈东西〉。「目的」是抽象的，没有轻重，说东西很重应该用「东西」。"}, {"text": "他每天吃很多目的，身体很好。", "explanation": "这里应该用〈饭〉。「目的」是抽象的，不能吃；「饭」才可以吃。"}, {"text": "他有一把目的，很清楚。", "explanation": "这里量词用错。「把」用于有柄的东西，「目的」是抽象的，应该用「个」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13201, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "目的", "is_correct": true, "explanation": "正确：「没有别的目的」指做这件事只有一个想要达到的结果，与句意相符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：「味道」是食物或气味的性质，不能指做事想要达到的目标。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」是外观，不能指做事想要达到的目标。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「价格」指商品值多少钱，不能指做事想要达到的目标。"}], "explanations": {"目的": "正确：「没有别的目的」指做这件事只有一个想要达到的结果，与句意相符。", "味道": "语义：「味道」是食物或气味的性质，不能指做事想要达到的目标。", "颜色": "语义：「颜色」是外观，不能指做事想要达到的目标。", "价格": "语义：「价格」指商品值多少钱，不能指做事想要达到的目标。"}, "sentence_index": 6, "correct_answer": "目的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他来这里只有一根目的。", "explanation": "这里量词用错。「根」用于细长的东西，「目的」是抽象的，应该用「个」。"}, {"text": "他的目的很甜，大家都爱吃。", "explanation": "这里应该用〈糖〉。「糖」可以甜，也可以吃；「目的」是抽象的，没有味道，不能说甜，也不能吃。"}, {"text": "我妈妈每天给我做目的，很好吃。", "explanation": "这里应该用〈饭〉。「做」的对象是饭菜等具体的东西，「目的」是抽象的，不能做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13201, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一条明确的目的。", "corrected_sentence": "他有一个明确的目的。", "error_description": "错误：「一条目的」。正确：「一个目的」。「条」用于细长的东西，「目的」是抽象的，应该用「个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13201, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个活动有两本目的。", "corrected_sentence": "这个活动有两个目的。", "error_description": "错误：「两本目的」。正确：「两个目的」。「本」用于书籍，「目的」是抽象的，应该用「个」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
