INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13208, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为达到某种目的而使用的方法、技巧或途径。", "primary_collocate": null, "pronunciation": "shǒu duàn", "ipa": "ʂoʊ˨˩˦ twan˥˩", "syllable_count": 2, "sentences": [{"text": "在全球环境政策的演进历程中，立法手段日益成为各国应对塑料污染的核心工具。", "target_word": "手段", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这位老师的教学手段很新。", "target_word": "手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了成功，他用了很多手段。", "target_word": "手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察用技术手段找到了小偷。", "target_word": "手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用不正当的手段赚钱。", "target_word": "手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司有很多宣传手段，比如广告。", "target_word": "手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "解决问题要用合法的手段。", "target_word": "手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种手段太危险，我们不能用。", "target_word": "手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代科技给医生带来了新的检查手段。", "target_word": "手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只是用了一点小手段。", "target_word": "手段", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "为达到目的而采用的方法或途径", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4cc9c03-6209-4c9e-868b-ad46e5b5769a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13208, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手段", "is_correct": true, "explanation": "正确：“立法手段”指通过立法这种方法，与“核心工具”相呼应，符合句意。"}, {"text": "原则", "is_correct": false, "explanation": "语义：“原则”是指导思想，不是可以成为核心工具的方法，句意不通。"}, {"text": "目的", "is_correct": false, "explanation": "语义：“目的”是要达到的结果，不能被当作“工具”，与“核心工具”矛盾。"}, {"text": "成果", "is_correct": false, "explanation": "语义：“成果”是取得的结果，不是应对污染的“工具”，与“核心工具”矛盾。"}], "explanations": {"手段": "正确：“立法手段”指通过立法这种方法，与“核心工具”相呼应，符合句意。", "原则": "语义：“原则”是指导思想，不是可以成为核心工具的方法，句意不通。", "目的": "语义：“目的”是要达到的结果，不能被当作“工具”，与“核心工具”矛盾。", "成果": "语义：“成果”是取得的结果，不是应对污染的“工具”，与“核心工具”矛盾。"}, "sentence_index": 0, "correct_answer": "手段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的手段是拿到冠军。", "explanation": "这里应该用〈目标〉。“手段”指达到目的的方法，“拿到冠军”是最终要达到的结果，不能作“手段”。"}, {"text": "这位老人是他要帮助的手段。", "explanation": "这里应该用〈对象〉。“手段”是方法，不能指被帮助的人。"}, {"text": "他把手段放进了书包里。", "explanation": "这里应该用〈工具〉。“手段”是抽象的方法，不是具体的东西，不能放进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13208, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手段", "is_correct": true, "explanation": "正确：“合法的手段”是正当的办法，符合句意。"}, {"text": "诡计", "is_correct": false, "explanation": "语义：诡计本身不合法，“合法的诡计”自相矛盾。"}, {"text": "把戏", "is_correct": false, "explanation": "语域：“把戏”口语色彩重、常带贬义，与这句正式的语境不符。"}, {"text": "贿赂", "is_correct": false, "explanation": "语义：“贿赂”本身违法，“合法的贿赂”自相矛盾。"}], "explanations": {"手段": "正确：“合法的手段”是正当的办法，符合句意。", "诡计": "语义：诡计本身不合法，“合法的诡计”自相矛盾。", "把戏": "语域：“把戏”口语色彩重、常带贬义，与这句正式的语境不符。", "贿赂": "语义：“贿赂”本身违法，“合法的贿赂”自相矛盾。"}, "sentence_index": 6, "correct_answer": "手段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次研究取得了重大手段。", "explanation": "这里应该用〈成果〉。“取得”的对象是成果，“手段”不能被取得。"}, {"text": "他是我最好的手段。", "explanation": "这里应该用〈伙伴〉。“手段”指方法，不能指人。"}, {"text": "他用一把手段解决了问题。", "explanation": "这里应该用〈种〉（一种手段）。“把”用于有柄的器具，不用于“手段”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13208, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们得想一只新手段。", "corrected_sentence": "我们得想一种新手段。", "error_description": "量词错误：“手段”是抽象名词，量词应用“种”，“只”不能用于“手段”。正确：一种新手段。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13208, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想到了许多手段们。", "corrected_sentence": "他想到了许多手段。", "error_description": "词尾错误：“们”只用于指人的名词，“手段”是抽象名词，不能加“们”。正确：许多手段。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98bc4599-a177-4ba4-9fd8-632ff3437f74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
