INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13209, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地球表面未被海洋淹没的部分。", "primary_collocate": null, "pronunciation": "lù dì", "ipa": "lu˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "面对日益严峻的海洋与陆地生态压力，一次性塑料制品因其不可降解性及广泛使用，已成为全球治理的关键靶点。", "target_word": "陆地", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "栖息地碎片化、农药滥用、气候变化以及外来物种入侵，正在协同加速蜜蜂种群的衰退，进而威胁整个陆地生态系统的功能完整性。", "target_word": "陆地", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "地球上海洋比陆地大。", "target_word": "陆地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "坐了很久的船，我们终于看到陆地。", "target_word": "陆地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "陆地上的动物不能在水里生活。", "target_word": "陆地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只鸟飞了一天，终于回到陆地。", "target_word": "陆地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地球表面的陆地约占三分之一。", "target_word": "陆地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海水涨起来，陆地变小了。", "target_word": "陆地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "陆地的面积比海洋小得多。", "target_word": "陆地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "青蛙既能在水里，也能在陆地上生活。", "target_word": "陆地", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块陆地", "label": "量词"}, {"form": "陆地生态系统", "label": "复合"}, {"form": "陸地", "label": "繁体"}], "register": "中性", "sense_fingerprint": "地球表面海洋以外的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c0440af-c60e-4c64-8601-be0f673c410c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13209, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陆地", "is_correct": true, "explanation": "陆地指地球表面未被海洋覆盖的部分，与“海洋”相对，此处指陆地上的生态环境。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”不是生态系统的环境，不能与海洋并列为生态压力的对象。"}, {"text": "地盘", "is_correct": false, "explanation": "语域：“地盘”是口语说法，与这句的书面语体不合。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”是抽象的时长，不指可以承受生态压力的环境。"}], "explanations": {"陆地": "陆地指地球表面未被海洋覆盖的部分，与“海洋”相对，此处指陆地上的生态环境。", "价格": "语义：“价格”不是生态系统的环境，不能与海洋并列为生态压力的对象。", "地盘": "语域：“地盘”是口语说法，与这句的书面语体不合。", "时间": "语义：“时间”是抽象的时长，不指可以承受生态压力的环境。"}, "sentence_index": 0, "correct_answer": "陆地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这艘船在陆地上航行，很快就到了港口。", "explanation": "这里应该用〈大海〉。船在水上航行，应说大海；陆地指与海洋相对的陆上区域，不能用来形容船的航行。"}, {"text": "鲸鱼在陆地上游，很快就潜了下去。", "explanation": "这里应该用〈水里〉。鲸鱼在水中游，应说水里；陆地指地球表面未被海水淹没的部分，不是水域。"}, {"text": "潜水员潜到了陆地。", "explanation": "这里应该用〈海底〉。潜水是潜入水下，应说海底；陆地指海洋之外的地表，不能用来表示潜入水中。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13209, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陆地", "is_correct": true, "explanation": "陆地指地球表面未被海水覆盖的部分，约占地球表面的三分之一。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”不是地表的一部分，不能说约占地球表面的三分之一。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不是地表的一部分，不能说占地球表面的三分之一。"}, {"text": "节奏", "is_correct": false, "explanation": "语义：“节奏”是声音或动作的规律，不能用来说明地表的占比。"}], "explanations": {"陆地": "陆地指地球表面未被海水覆盖的部分，约占地球表面的三分之一。", "空气": "语义：“空气”不是地表的一部分，不能说约占地球表面的三分之一。", "声音": "语义：“声音”不是地表的一部分，不能说占地球表面的三分之一。", "节奏": "语义：“节奏”是声音或动作的规律，不能用来说明地表的占比。"}, "sentence_index": 6, "correct_answer": "陆地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民们承包了很多陆地，种上了庄稼。", "explanation": "这里应该用〈土地〉。承包的对象是土地，陆地指广大的陆上区域，不说“承包陆地”。"}, {"text": "他在城里买了一瓶陆地，准备盖房子。", "explanation": "这里应该用〈地皮〉。“一瓶”只能量液体，陆地指广大的陆上区域，不能这样计量；买来盖房的是地皮。"}, {"text": "我们从北京到上海，坐的是一辆陆地。", "explanation": "这里应该用〈火车〉。“一辆”量的是车，陆地指地表，不是交通工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13209, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "许多鸟类生活陆地上。", "corrected_sentence": "许多鸟类生活在陆地上。", "error_description": "位置错误：“陆地”作处所时要说“在陆地上”，漏掉“在”就不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13209, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海鸟在陆地里筑巢。", "corrected_sentence": "海鸟在陆地上筑巢。", "error_description": "方位词错误：“陆地”作处所时说“陆地上”，不说“陆地里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0088cc3-2428-43e8-adbd-a14e7a6c2b21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
