INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13211, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指生物体内能够与特定药物或信号分子结合，并产生生物学效应的特定结构，通常是蛋白质。", "primary_collocate": null, "pronunciation": "bǎ diǎn", "ipa": "pa²¹⁴ tjɛn²¹⁴", "syllable_count": 2, "sentences": [{"text": "这种药要与细胞里的特定蛋白结合才有效，这种蛋白就是它的靶点。", "target_word": "靶点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药的靶点是一种蛋白质。", "target_word": "靶点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生正在寻找新的癌症药物靶点。", "target_word": "靶点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药物找到靶点以后，才会起作用。", "target_word": "靶点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家发现了这个病的新靶点。", "target_word": "靶点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药只作用于一个靶点，副作用很小。", "target_word": "靶点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员想知道药物的靶点在哪儿。", "target_word": "靶点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找准靶点，是研发新药的第一步。", "target_word": "靶点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个靶点在心脏细胞里很常见。", "target_word": "靶点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药物和靶点结合后，细胞就会有反应。", "target_word": "靶点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "药物靶点", "label": "复合"}, {"form": "靶點", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "医药生物术语，药物或分子在体内结合的结构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09206b64-ef69-428b-a35b-eee9be641633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13211, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "靶点", "is_correct": true, "explanation": "正确：「靶点」指药物作用的特定结构，与“这种蛋白就是它的……”的语境相符。"}, {"text": "原料", "is_correct": false, "explanation": "语义：「原料」指生产用的材料，“这种蛋白就是它的原料”不通，与药物结合的语境不符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」是事物的外观属性，不是药物作用的结构，“它的颜色”不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」不是药物作用的对象，“它的天气”不通，与语境矛盾。"}], "explanations": {"靶点": "正确：「靶点」指药物作用的特定结构，与“这种蛋白就是它的……”的语境相符。", "原料": "语义：「原料」指生产用的材料，“这种蛋白就是它的原料”不通，与药物结合的语境不符。", "颜色": "语义：「颜色」是事物的外观属性，不是药物作用的结构，“它的颜色”不通。", "天气": "语义：「天气」不是药物作用的对象，“它的天气”不通，与语境矛盾。"}, "sentence_index": 0, "correct_answer": "靶点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次治疗的靶点是让病人康复。", "explanation": "这里应该用〈目标〉，表示想达到的结果；靶点指药物作用的特定分子结构，不能用来指治疗的目的。"}, {"text": "他一枪就打中了靶点，大家都为他鼓掌。", "explanation": "这里应该用〈靶心〉，指射击靶子的中心；靶点指药物在体内作用的分子结构，不用于射击。"}, {"text": "这份报告的靶点很清楚，就是降低成本。", "explanation": "这里应该用〈重点〉，表示需要着重关注的部分；靶点专指药物或分子作用的结构，不能指报告的重点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13211, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "靶点", "is_correct": true, "explanation": "正确：「靶点」指药物作用的结构，与“药物的……在哪儿”的询问相符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：「年龄」不是可以问“在哪儿”的事物，填入后“药物的年龄在哪儿”不通，与研究语境矛盾。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「价格」是买卖时的钱数，不能问“在哪儿”，“药物的价格在哪儿”不通。"}, {"text": "语言", "is_correct": false, "explanation": "语义：「语言」指说话的系统，填入后“药物的语言在哪儿”不通，与语境不符。"}], "explanations": {"靶点": "正确：「靶点」指药物作用的结构，与“药物的……在哪儿”的询问相符。", "年龄": "语义：「年龄」不是可以问“在哪儿”的事物，填入后“药物的年龄在哪儿”不通，与研究语境矛盾。", "价格": "语义：「价格」是买卖时的钱数，不能问“在哪儿”，“药物的价格在哪儿”不通。", "语言": "语义：「语言」指说话的系统，填入后“药物的语言在哪儿”不通，与语境不符。"}, "sentence_index": 6, "correct_answer": "靶点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议的靶点是环境问题，大家都很关心。", "explanation": "这里应该用〈焦点〉，表示大家关注的中心问题；靶点专指药物或分子作用的结构，不能指讨论的话题。"}, {"text": "问题的靶点在于资金。", "explanation": "这里应该用〈核心〉，表示事情最关键的部分；靶点是分子结构，不能用来指问题的核心。"}, {"text": "这个城市的靶点在东边。", "explanation": "这里应该用〈中心〉，表示地理上的中央位置；靶点指药物作用的结构，不能指城市的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13211, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究者找到了一只靶点。", "corrected_sentence": "研究者找到了一个靶点。", "error_description": "“靶点”的量词应为“个”，“只”一般用于动物，不能用来数“靶点”，应改为“一个靶点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13211, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究者找到了这些靶点们。", "corrected_sentence": "研究者找到了这些靶点。", "error_description": "“靶点”是事物，不能加“们”表示复数，应删去“们”，说“这些靶点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
