INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13213, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指示、命令；也指上级或权威机构发布的要求执行的正式文件。", "primary_collocate": null, "pronunciation": "zhǐ lìng", "ipa": "ʈʂɨ˨˩˦ liŋ˥˩", "syllable_count": 2, "sentences": [{"text": "政府发出指令，要求各学校暂停上课。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份指令已经送到每个部门了。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长在指令上签了名字。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的新指令贴在门口的墙上。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "指令里写着，明天所有人都要开会。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市里的指令要求医院二十四小时开门。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们仔细读了这份指令。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上级的书面指令必须保存好。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把指令交给了办公室的老师。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份指令的内容，大家都要记住。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条指令", "label": "量词"}, {"form": "一道指令", "label": "量词"}, {"form": "指令集", "label": "复合"}], "register": "中性", "sense_fingerprint": "指令：上级或权威机构发布的要求执行的正式文件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31956932-1185-4de5-add8-d2c55acac8f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13213, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指令", "is_correct": true, "explanation": "正确：指令是上级机关发布的正式文件，与“政府发出”相合。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的工具，政府不能发出钥匙来要求停课。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：“发出”不能搭配“花朵”，“政府发出花朵”说不通。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水是自然降水，不是政府发出的内容，与“要求停课”无关。"}], "explanations": {"指令": "正确：指令是上级机关发布的正式文件，与“政府发出”相合。", "钥匙": "语义：钥匙是开锁的工具，政府不能发出钥匙来要求停课。", "花朵": "搭配：“发出”不能搭配“花朵”，“政府发出花朵”说不通。", "雨水": "语义：雨水是自然降水，不是政府发出的内容，与“要求停课”无关。"}, "sentence_index": 0, "correct_answer": "指令"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "墙上贴着一只指令，大家都在看。", "explanation": "这里应该用〈份〉。〈只〉用于动物或成对的东西，正式文件不能用〈只〉来计量。"}, {"text": "学校发来一份指令，邀请家长参加活动。", "explanation": "这里应该用〈通知〉。指令带有强制性，不能用来邀请家长；邀请和告知要用〈通知〉。"}, {"text": "我们给领导交了一份指令，汇报了本月的销售情况。", "explanation": "这里应该用〈报告〉。指令是上级发出、要求执行的文件，下级不能用它来汇报情况；汇报工作要用〈报告〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13213, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指令", "is_correct": true, "explanation": "正确：指令是书面文件，可以被“仔细读”，与句中的“读”相合。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不能被阅读，与“仔细读”不搭。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：海浪是自然景象，不是文字材料，不能被“读”。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：“仔细读”搭配文字材料，不说“读手套”。"}], "explanations": {"指令": "正确：指令是书面文件，可以被“仔细读”，与句中的“读”相合。", "饼干": "语义：饼干是食品，不能被阅读，与“仔细读”不搭。", "海浪": "语义：海浪是自然景象，不是文字材料，不能被“读”。", "手套": "搭配：“仔细读”搭配文字材料，不说“读手套”。"}, "sentence_index": 6, "correct_answer": "指令"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师给我们发了一支指令，要求认真读。", "explanation": "这里应该用〈份〉。〈支〉用于笔、棍等细长的物体，指令是文件，不能用〈支〉来计量。"}, {"text": "我向老师提出了一个指令，希望推迟考试。", "explanation": "这里应该用〈请求〉。指令是上级或权威机构发布的、必须执行的，学生不能向老师发出指令；希望推迟考试属于〈请求〉。"}, {"text": "我有一个指令，希望明年能去北京。", "explanation": "这里应该用〈愿望〉。指令是要求执行的正式文件，不能用来表达个人的希望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13213, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只指令昨天已经下发到所有学校了。", "corrected_sentence": "这份指令昨天已经下发到所有学校了。", "error_description": "量词错误：指令作为正式文件应用“份”计量。“只”用于动物等，应改为“这份指令”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13213, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "校长仔细看了这本指令。", "corrected_sentence": "校长仔细看了这份指令。", "error_description": "量词错误：指令作为文件应用“份”计量。“本”用于书籍、册子，应改为“这份指令”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13214, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "启用", "is_correct": true, "explanation": "反义：“启用”指开始使用某物，与“禁用”的不准使用正相反。"}, {"text": "修理", "is_correct": false, "explanation": "修理指使物品恢复正常，与禁用没有反义关系，这里不成立。"}, {"text": "研究", "is_correct": false, "explanation": "研究指探究事理，与禁用不构成反义，意思上并不相对。"}, {"text": "清洗", "is_correct": false, "explanation": "清洗指去除污物，与禁用没有反义关系，这里不成立。"}], "correct_answer": "启用", "explanations": {"启用": "反义：“启用”指开始使用某物，与“禁用”的不准使用正相反。", "修理": "修理指使物品恢复正常，与禁用没有反义关系，这里不成立。", "研究": "研究指探究事理，与禁用不构成反义，意思上并不相对。", "清洗": "清洗指去除污物，与禁用没有反义关系，这里不成立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13214, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "启用", "is_correct": true, "explanation": "反义：“启用”指开始使用某物，与“禁用”的不准使用正相反。"}, {"text": "购买", "is_correct": false, "explanation": "购买指付钱获得物品，与禁用没有反义关系，这里不成立。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论指交流意见，与禁用不构成反义，意思上并不相对。"}, {"text": "翻译", "is_correct": false, "explanation": "翻译指把一种语言转换成另一种，与禁用没有反义关系。"}], "correct_answer": "启用", "explanations": {"启用": "反义：“启用”指开始使用某物，与“禁用”的不准使用正相反。", "购买": "购买指付钱获得物品，与禁用没有反义关系，这里不成立。", "讨论": "讨论指交流意见，与禁用不构成反义，意思上并不相对。", "翻译": "翻译指把一种语言转换成另一种，与禁用没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13214, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "规定不准使用某物或某种功能。", "primary_collocate": null, "pronunciation": "jìn yòng", "ipa": "tɕin˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "为了减少垃圾，新规定明确禁用一次性塑料餐具。", "target_word": "禁用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校规定考试时禁用手机。", "target_word": "禁用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种农药对人有害，国家已经禁用了。", "target_word": "禁用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院里禁用明火，请不要抽烟。", "target_word": "禁用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛期间，主办方禁用了这种药物。", "target_word": "禁用", "complexity_tier": "T3", "furigana": "jìn yòng", "sentence_source": "generated"}, {"text": "很多城市禁用一次性塑料袋。", "target_word": "禁用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说考试时禁用电子词典。", "target_word": "禁用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孕妇禁用这种药，吃了会有危险。", "target_word": "禁用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家早就禁用过这种化学品。", "target_word": "禁用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林公园里禁用烟花，防止着火。", "target_word": "禁用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "禁用了", "label": "体标"}, {"form": "禁用过", "label": "体标"}, {"form": "禁用词", "label": "复合"}], "register": "书面", "sense_fingerprint": "官方或规定明令不准使用某物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09206b64-ef69-428b-a35b-eee9be641633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13214, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "禁用", "is_correct": true, "explanation": "正确：「禁用」是规定不准使用，与“为了减少垃圾”的限制语境相符。"}, {"text": "允许", "is_correct": false, "explanation": "语义：「允许」是准许使用，与“为了减少垃圾”的限制目的相反，句意不通。"}, {"text": "推广", "is_correct": false, "explanation": "语义：「推广」是大力普及，与“为了减少垃圾”的限制目的相反。"}, {"text": "生产", "is_correct": false, "explanation": "语义：「生产」是制造，与“为了减少垃圾”的限制目的相反，句意不通。"}], "explanations": {"禁用": "正确：「禁用」是规定不准使用，与“为了减少垃圾”的限制语境相符。", "允许": "语义：「允许」是准许使用，与“为了减少垃圾”的限制目的相反，句意不通。", "推广": "语义：「推广」是大力普及，与“为了减少垃圾”的限制目的相反。", "生产": "语义：「生产」是制造，与“为了减少垃圾”的限制目的相反，句意不通。"}, "sentence_index": 0, "correct_answer": "禁用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "校园里禁用吸烟，请大家遵守。", "explanation": "这里应该用〈禁止〉。禁用多用于物品、药品或功能，不用于吸烟这样的行为。"}, {"text": "这个非法组织已经被政府禁用。", "explanation": "这里应该用〈取缔〉。取缔用于组织、团伙，禁用用于物品、药品或功能。"}, {"text": "我们要禁用浪费，珍惜每一粒粮食。", "explanation": "这里应该用〈杜绝〉。杜绝用于浪费、错误等不良现象，禁用指不准使用某物，不能用于浪费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13214, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "禁用", "is_correct": true, "explanation": "正确：老师规定考试中不准使用电子词典，与句意相符。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”后接的是活动或考试，不能接“电子词典”，句子说不通。"}, {"text": "制造", "is_correct": false, "explanation": "语义：“制造”是生产出东西，老师说的是不准使用，句意不合。"}, {"text": "支持", "is_correct": false, "explanation": "语义：“支持”是赞同或帮助，与老师规定考试中的限制语境不符。"}], "explanations": {"禁用": "正确：老师规定考试中不准使用电子词典，与句意相符。", "参加": "搭配：“参加”后接的是活动或考试，不能接“电子词典”，句子说不通。", "制造": "语义：“制造”是生产出东西，老师说的是不准使用，句意不合。", "支持": "语义：“支持”是赞同或帮助，与老师规定考试中的限制语境不符。"}, "sentence_index": 6, "correct_answer": "禁用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛规定，他被禁用，不能参加决赛。", "explanation": "这里应该用〈禁赛〉，表示取消参赛资格；禁用的对象是物品或功能，不用于运动员。"}, {"text": "保安禁用我进入大楼。", "explanation": "这里应该用〈不准〉。“禁用”的对象是物品或功能，不能直接限制人的行动，应说“不准我进入大楼”。"}, {"text": "这件衣服太大了，妈妈禁用我穿它。", "explanation": "这里应该用〈不许〉。“禁用”针对物品或功能，不能用于人穿衣的行为，应说“不许我穿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13214, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "考场里很禁用电子词典。", "corrected_sentence": "考场里禁用电子词典。", "error_description": "副词错误：“禁用”是动词，前面不能直接加“很”。应去掉“很”，说“考场里禁用电子词典”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13214, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校没禁用了电子词典。", "corrected_sentence": "学校没禁用电子词典。", "error_description": "否定形式错误：用“没”否定时，动词后不能再加“了”。应删去“了”，说“学校没禁用电子词典”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13215, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
