INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13215, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指用于满足人们生活需要的各种物品，比如食物、衣服、家具、电器等。", "primary_collocate": null, "pronunciation": "xiāo fèi pǐn", "ipa": "ɕiɑʊ˥ feɪ˥˩ pʰin˨˩˦", "syllable_count": 3, "sentences": [{"text": "近年来，以欧盟为代表的政治实体推行了系统性监管框架，通过《一次性塑料指令》明确禁用十类常见塑料消费品，如餐具、吸管与发泡餐盒，并要求成员国将指令转化为国内法，实现法律效力的属地化延伸。", "target_word": "消费品", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "衣物从“耐用品”异化为“一次性消费品”，大量未被穿着或仅短时间使用的服装最终被填埋或焚烧，形成巨大的资源浪费。", "target_word": "消费品", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "超市里卖的大多是日常消费品。", "target_word": "消费品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食品和衣服都是生活中的消费品。", "target_word": "消费品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视、冰箱这类家用电器也属于消费品。", "target_word": "消费品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店专门卖各种消费品。", "target_word": "消费品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年前，人们大量购买消费品。", "target_word": "消费品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包是人们每天都要买的消费品。", "target_word": "消费品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对年轻人来说，手机是重要的消费品。", "target_word": "消费品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂生产的消费品要先检查再出售。", "target_word": "消费品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种消费品", "label": "量词"}, {"form": "日用消费品", "label": "复合"}, {"form": "耐用消费品", "label": "复合"}, {"form": "消費品", "label": "繁体"}], "register": "中性", "sense_fingerprint": "满足生活需要的各类物品，如食物、衣服、家具、电器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b3bbd23-8942-4e8f-b366-768ba894f710') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13215, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消费品", "is_correct": true, "explanation": "正确。“消费品”指供人们生活使用的物品，与“餐具、吸管、餐盒”同类，可以被禁用。"}, {"text": "塑料袋", "is_correct": false, "explanation": "语义：“塑料袋”不包括餐具和吸管，与后面“如餐具、吸管与发泡餐盒”的例举不符。"}, {"text": "原材料", "is_correct": false, "explanation": "语义：“原材料”是生产用的原料，不是成品，不能和“餐具、吸管”这类成品并列。"}, {"text": "成本", "is_correct": false, "explanation": "搭配：“禁用”的对象是具体物品，不能说禁用“成本”。"}], "explanations": {"消费品": "正确。“消费品”指供人们生活使用的物品，与“餐具、吸管、餐盒”同类，可以被禁用。", "塑料袋": "语义：“塑料袋”不包括餐具和吸管，与后面“如餐具、吸管与发泡餐盒”的例举不符。", "原材料": "语义：“原材料”是生产用的原料，不是成品，不能和“餐具、吸管”这类成品并列。", "成本": "搭配：“禁用”的对象是具体物品，不能说禁用“成本”。"}, "sentence_index": 0, "correct_answer": "消费品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂生产的消费品主要是机床和钢材。", "explanation": "这里应该用〈商品〉。消费品专指供人们生活使用的东西，机床和钢材不属于这一类。"}, {"text": "这家商店经常征求消费品的意见。", "explanation": "这里应该用〈消费者〉。消费品是物品，不能提意见；提意见的是人，要用〈消费者〉。"}, {"text": "这家公司的消费品包括工业阀门和变压器，主要卖给工厂。", "explanation": "这里应该用〈产品〉。消费品专指供人们生活使用的东西，阀门和变压器是卖给工厂的生产用品，不属于这一类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13215, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消费品", "is_correct": true, "explanation": "正确。“购买”的对象是人们拿来使用的日用物品，即“消费品”。"}, {"text": "春天", "is_correct": false, "explanation": "语义：“购买”的对象是可以拿到手的物品，“春天”是季节，不能拿来买。"}, {"text": "回忆", "is_correct": false, "explanation": "搭配：“购买”不能搭配“回忆”，回忆无法用金钱交易。"}, {"text": "节日", "is_correct": false, "explanation": "语义：“节日”是时间，不是可以购买的东西，与“大量购买”不符。"}], "explanations": {"消费品": "正确。“购买”的对象是人们拿来使用的日用物品，即“消费品”。", "春天": "语义：“购买”的对象是可以拿到手的物品，“春天”是季节，不能拿来买。", "回忆": "搭配：“购买”不能搭配“回忆”，回忆无法用金钱交易。", "节日": "语义：“节日”是时间，不是可以购买的东西，与“大量购买”不符。"}, "sentence_index": 6, "correct_answer": "消费品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个仓库里存放的消费品都是用于实验的仪器。", "explanation": "这里应该用〈物品〉。消费品专指供人们生活使用的东西，实验仪器不属于这一类。"}, {"text": "这个基金的消费品主要是股票和债券。", "explanation": "这里应该用〈资产〉。消费品专指供人们生活使用的东西，股票和债券属于金融资产，不属于这一类。"}, {"text": "这家理发店提供的消费品是剪发和烫发。", "explanation": "这里应该用〈服务〉。消费品指有形的生活物品，剪发、烫发属于服务，不能用“消费品”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13215, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们超市里有很多只消费品。", "corrected_sentence": "我们超市里有很多种消费品。", "error_description": "量词误用：“消费品”是泛指一类物品的名词，数量词应用“种”或“类”。“只”用于具体的单个动物或器物，不能修饰这种泛称。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13215, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些消费品们价格很便宜。", "corrected_sentence": "这些消费品价格很便宜。", "error_description": "词尾误加：“们”只用于指人的名词，“消费品”是物品，不能加“们”，应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
