INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13216, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "物体内部或表面产生大量气泡的现象。", "primary_collocate": null, "pronunciation": "fā pào", "ipa": "fa˥ pʰau˥˩", "syllable_count": 2, "sentences": [{"text": "这种新型塑料在高温加工时会迅速发泡，内部形成大量细小的气孔，因此密度大幅降低，重量也随之减轻。", "target_word": "发泡", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "洗手液遇到水就会发泡。", "target_word": "发泡", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "咖啡店用蒸汽把牛奶发泡。", "target_word": "发泡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种洗发水发泡很快，用一点就够。", "target_word": "发泡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小苏打放进醋里会发泡。", "target_word": "发泡", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这块香皂搓几下就发泡，很好用。", "target_word": "发泡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把塑料加热，让它发泡变轻。", "target_word": "发泡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种牙膏发泡太多，我不喜欢。", "target_word": "发泡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用洗面奶在手心发泡，再洗脸。", "target_word": "发泡", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗衣液倒进水里，搅一搅就发泡。", "target_word": "发泡", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "发泡了", "label": "体标"}, {"form": "发泡剂", "label": "复合"}, {"form": "發泡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物体内部或表面产生大量气泡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09206b64-ef69-428b-a35b-eee9be641633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13216, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "发泡", "is_correct": true, "explanation": "发泡（fā pào）：物体内部或表面产生大量气泡。"}, {"text": "发报", "is_correct": false, "explanation": "发报（fā bào）与 fā pào 声母不同（b/p），声调相同，意思是拍发电报。"}, {"text": "发包", "is_correct": false, "explanation": "发包（fā bāo）与 fā pào 声母送气不同（b/p），声调也不同，意思是把工程等承包出去。"}, {"text": "发票", "is_correct": false, "explanation": "发票（fā piào）比 fā pào 多一个介音 i，意思是开具的收款凭证。"}], "explanations": {"发泡": "发泡（fā pào）：物体内部或表面产生大量气泡。", "发报": "发报（fā bào）与 fā pào 声母不同（b/p），声调相同，意思是拍发电报。", "发包": "发包（fā bāo）与 fā pào 声母送气不同（b/p），声调也不同，意思是把工程等承包出去。", "发票": "发票（fā piào）比 fā pào 多一个介音 i，意思是开具的收款凭证。"}, "sentence_index": null, "correct_answer": "发泡"}, "level_3": {"options": [{"text": "发泡", "is_correct": true, "explanation": "“高温加工时会迅速发泡”指塑料受热后内部产生大量气泡，与后文的气孔和密度降低相符。"}, {"text": "切割", "is_correct": false, "explanation": "语义：切割只是把材料分开，不会在材料内部形成气孔，与句意不符。"}, {"text": "压缩", "is_correct": false, "explanation": "语义：压缩会使体积变小、密度增大，与“密度大幅降低”矛盾。"}, {"text": "打磨", "is_correct": false, "explanation": "语义：“打磨”作用于表面，不会使材料内部形成气孔，与“内部形成细小的气孔”矛盾。"}], "explanations": {"发泡": "“高温加工时会迅速发泡”指塑料受热后内部产生大量气泡，与后文的气孔和密度降低相符。", "切割": "语义：切割只是把材料分开，不会在材料内部形成气孔，与句意不符。", "压缩": "语义：压缩会使体积变小、密度增大，与“密度大幅降低”矛盾。", "打磨": "语义：“打磨”作用于表面，不会使材料内部形成气孔，与“内部形成细小的气孔”矛盾。"}, "sentence_index": 0, "correct_answer": "发泡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服洗完以后，颜色很快就发泡了。", "explanation": "这里应该用〈褪色〉。衣服洗后颜色变淡应说“褪色”；“发泡”指产生气泡，与颜色变化无关，这里词义用错了。"}, {"text": "水放进冰箱里，过一夜就发泡了。", "explanation": "这里应该用〈结冰〉。水遇冷凝固成冰，应说“结冰”；“发泡”指产生大量气泡，与水变成固体无关，这里词义用错了。"}, {"text": "他一生气，脸就发泡了。", "explanation": "这里应该用〈涨红〉。生气时脸色变红应说“涨红”；“发泡”指物体产生气泡，不用来形容脸色，这里词义用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13216, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发泡", "is_correct": true, "explanation": "“让它发泡变轻”指加热后塑料内部产生气泡，体积膨胀、变轻，语境通顺。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：“冷却”与句中的“加热”方向相反，降温也不会让塑料变轻。"}, {"text": "压缩", "is_correct": false, "explanation": "语义：“压缩”会使体积变小、密度变大，与“变轻”相矛盾。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：“打碎”的结果是碎块，不能直接接“变轻”，搭配不当。"}], "explanations": {"发泡": "“让它发泡变轻”指加热后塑料内部产生气泡，体积膨胀、变轻，语境通顺。", "冷却": "语义：“冷却”与句中的“加热”方向相反，降温也不会让塑料变轻。", "压缩": "语义：“压缩”会使体积变小、密度变大，与“变轻”相矛盾。", "打碎": "搭配：“打碎”的结果是碎块，不能直接接“变轻”，搭配不当。"}, "sentence_index": 6, "correct_answer": "发泡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "花苞遇到春天就会发泡。", "explanation": "这里应该用〈开花〉。花苞绽放是植物开放，应说“开花”；“发泡”指物体产生气泡，不能用于植物开放。"}, {"text": "毛衣用热水一洗就发泡了。", "explanation": "这里应该用〈收缩〉。毛衣遇热水变小，应说“收缩”；“发泡”指产生大量气泡，不表示物体缩小。"}, {"text": "这杯咖啡里的糖放进去，很快就发泡了。", "explanation": "这里应该用〈溶解〉。糖溶入水中是分子分散，并不产生泡沫，“发泡”不能用于此情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种沐浴球一放进水里就快很发泡。", "corrected_sentence": "这种沐浴球一放进水里就很快发泡。", "error_description": "语序错误：两个副词的顺序颠倒了，应为“很快”，说“就很快发泡”，不能说“就快很发泡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这罐牛奶用蒸汽一加热就发泡着。", "corrected_sentence": "这罐牛奶用蒸汽一加热就发泡了。", "error_description": "“着”表示状态持续，“一……就……”强调先后相继的结果，应用“了”，说“就发泡了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13217, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13217, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13217, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来盛放饭菜的盒子或容器，通常用于外卖或携带食物。", "primary_collocate": null, "pronunciation": "cān hé", "ipa": "tsʰan˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "近年来，以欧盟为代表的政治实体推行了系统性监管框架，通过《一次性塑料指令》明确禁用十类常见塑料消费品，如餐具、吸管与发泡餐盒，并要求成员国将指令转化为国内法，实现法律效力的属地化延伸。", "target_word": "餐盒", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "外卖的餐盒放在门口。", "target_word": "餐盒", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请把吃完的餐盒扔进垃圾桶。", "target_word": "餐盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个餐盒太小，装不下两个菜。", "target_word": "餐盒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈给我准备了一个餐盒。", "target_word": "餐盒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "餐盒里有米饭、青菜和鸡蛋。", "target_word": "餐盒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的餐盒又干净又结实。", "target_word": "餐盒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把剩菜装进餐盒，带回家了。", "target_word": "餐盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热汤不能装在纸餐盒里，会漏。", "target_word": "餐盒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中午公司送来了二十个餐盒。", "target_word": "餐盒", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "塑料餐盒", "label": "复合"}, {"form": "外卖餐盒", "label": "复合"}], "register": "中性", "sense_fingerprint": "外卖或携带食物用的饭菜容器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09206b64-ef69-428b-a35b-eee9be641633') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13217, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "餐盒", "is_correct": true, "explanation": "餐盒指盛放饭菜的盒子，与餐具、吸管同属被禁的塑料消费品，“发泡餐盒”成立。"}, {"text": "纸巾", "is_correct": false, "explanation": "搭配：“发泡纸巾”不成词，纸巾也不是句中所列的被禁餐饮用品。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱是文字资料，不是实物消费品，与餐具、吸管并列不成立。"}, {"text": "牙刷", "is_correct": false, "explanation": "搭配：“发泡牙刷”不成词，且牙刷不属于句中被禁的一次性餐饮用品。"}], "explanations": {"餐盒": "餐盒指盛放饭菜的盒子，与餐具、吸管同属被禁的塑料消费品，“发泡餐盒”成立。", "纸巾": "搭配：“发泡纸巾”不成词，纸巾也不是句中所列的被禁餐饮用品。", "食谱": "语义：食谱是文字资料，不是实物消费品，与餐具、吸管并列不成立。", "牙刷": "搭配：“发泡牙刷”不成词，且牙刷不属于句中被禁的一次性餐饮用品。"}, "sentence_index": 0, "correct_answer": "餐盒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去那家餐盒吃饭。", "explanation": "这里应该用〈餐厅〉。餐盒是盛放饭菜的盒子，不是吃饭的场所，“去……吃饭”要用餐厅。"}, {"text": "他坐在餐盒前写作业。", "explanation": "这里应该用〈书桌〉。坐着写作业要用书桌，餐盒是盛放饭菜的盒子，不能当桌子用。"}, {"text": "他穿上了那个餐盒。", "explanation": "这里应该用〈衣服〉。穿是穿衣服的动作，要用于衣物；餐盒是盛放饭菜的盒子，不能当作衣服穿在身上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13217, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "餐盒", "is_correct": true, "explanation": "“这家店的餐盒”指店里使用或出售的盒子，可以用“干净又结实”来形容，句意通顺。"}, {"text": "药片", "is_correct": false, "explanation": "语义：药片不是店里的盛放用具，不能用“干净又结实”形容，句子不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”只能说好坏、浓淡，不能用“干净又结实”来形容。"}, {"text": "香烟", "is_correct": false, "explanation": "搭配：“干净”一般不用来形容香烟，“又干净又结实”与香烟搭配不当。"}], "explanations": {"餐盒": "“这家店的餐盒”指店里使用或出售的盒子，可以用“干净又结实”来形容，句意通顺。", "药片": "语义：药片不是店里的盛放用具，不能用“干净又结实”形容，句子不通。", "味道": "搭配：“味道”只能说好坏、浓淡，不能用“干净又结实”来形容。", "香烟": "搭配：“干净”一般不用来形容香烟，“又干净又结实”与香烟搭配不当。"}, "sentence_index": 6, "correct_answer": "餐盒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下雨了，他撑开了餐盒。", "explanation": "这里应该用〈雨伞〉。撑开用来挡雨的是雨伞，餐盒是盛放饭菜的盒子，不能用来挡雨。"}, {"text": "他开着餐盒去上班。", "explanation": "这里应该用〈汽车〉。开着去上班的是汽车等车辆，餐盒是盛放饭菜的盒子，不能当交通工具开。"}, {"text": "她把餐盒插进插座充电。", "explanation": "这里应该用〈充电器〉。插进插座充电的是充电器或插头，餐盒不是电器，不能插入插座。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13217, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给我准备了一块餐盒，让我带去学校。", "corrected_sentence": "妈妈给我准备了一个餐盒，让我带去学校。", "error_description": "量词错误：“块”用于块状物，不能用来数餐盒，应改为“一个餐盒”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13217, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去超市买了三张餐盒，准备装午饭。", "corrected_sentence": "他去超市买了三个餐盒，准备装午饭。", "error_description": "量词错误：“张”用于纸、桌子等平面物，不能用来数餐盒。应该用“个”，说“三个餐盒”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edd4acc1-ddc4-4079-9488-f095966f5c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
