INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13218, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13218, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "组成某个国际组织或团体的各个国家。", "primary_collocate": null, "pronunciation": "chéng yuán guó", "ipa": "ʈʂʰɤŋ˧˥ ɥɛn˧˥ kuɔ˧˥", "syllable_count": 3, "sentences": [{"text": "近年来，以欧盟为代表的政治实体推行了系统性监管框架，通过《一次性塑料指令》明确禁用十类常见塑料消费品，如餐具、吸管与发泡餐盒，并要求成员国将指令转化为国内法，实现法律效力的属地化延伸。", "target_word": "成员国", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "欧盟有二十七个成员国。", "target_word": "成员国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个组织的成员国每年开一次会。", "target_word": "成员国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个成员国都要交会费。", "target_word": "成员国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "联合国有一百九十多个成员国。", "target_word": "成员国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新成员国得到了其他国家的欢迎。", "target_word": "成员国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成员国的代表在会上发了言。", "target_word": "成员国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家想成为欧盟的成员国。", "target_word": "成员国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成员国必须遵守组织的规定。", "target_word": "成员国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议邀请所有成员国派代表参加。", "target_word": "成员国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "成員國", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "国际组织或团体中的成员国家，如欧盟成员国", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5597deb1-751e-4c58-ad43-76c28f29457a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13218, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成员国", "is_correct": true, "explanation": "正确：并要求的对象是国际组织中的国家，只有成员国才需要把指令转化为本国法律。"}, {"text": "个人", "is_correct": false, "explanation": "语义：转化为国内法是国家层面的立法行为，个人无权把欧盟指令转化为法律，句意不通。"}, {"text": "消费者", "is_correct": false, "explanation": "语义：指令约束的是国家，消费者不是立法主体，这里说不通。"}, {"text": "老百姓", "is_correct": false, "explanation": "语域：「老百姓」是口语说法，与句子的书面语风格不合；而且老百姓也无法完成立法转化。"}], "explanations": {"成员国": "正确：并要求的对象是国际组织中的国家，只有成员国才需要把指令转化为本国法律。", "个人": "语义：转化为国内法是国家层面的立法行为，个人无权把欧盟指令转化为法律，句意不通。", "消费者": "语义：指令约束的是国家，消费者不是立法主体，这里说不通。", "老百姓": "语域：「老百姓」是口语说法，与句子的书面语风格不合；而且老百姓也无法完成立法转化。"}, "sentence_index": 0, "correct_answer": "成员国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家健身房的成员国每个月都来锻炼。", "explanation": "这里应该用〈会员〉。成员国指组成国际组织的国家，健身房的成员是个人，要说〈会员〉。"}, {"text": "他是这个乐队的成员国。", "explanation": "这里应该用〈成员〉。成员国只指组成国际组织的国家，乐队的成员是人，不能说成员国。"}, {"text": "这家公司的成员国都是年轻人。", "explanation": "这里应该用〈员工〉。成员国指组成国际组织的国家，公司的工作人员是人，要说〈员工〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13218, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成员国", "is_correct": true, "explanation": "正确：成员国可以派代表参加会议，句中指国际组织中各成员国的代表。"}, {"text": "树木", "is_correct": false, "explanation": "语义：树木不能派代表，也不能在会上发言，与句意矛盾。"}, {"text": "哥们儿", "is_correct": false, "explanation": "语域：「哥们儿」是口语俚语，与书面化的「发了言」不协调。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有代表，更不能在会上发言，句意不通。"}], "explanations": {"成员国": "正确：成员国可以派代表参加会议，句中指国际组织中各成员国的代表。", "树木": "语义：树木不能派代表，也不能在会上发言，与句意矛盾。", "哥们儿": "语域：「哥们儿」是口语俚语，与书面化的「发了言」不协调。", "石头": "语义：石头没有代表，更不能在会上发言，句意不通。"}, "sentence_index": 6, "correct_answer": "成员国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班选了一个成员国去开会。", "explanation": "这里应该用〈代表〉。代表是班里选出的人，成员国指组成国际组织的国家，不能指班里的人。"}, {"text": "这座城市的成员国有两百万。", "explanation": "这里应该用〈居民〉。居民是住在城市里的人，成员国指组成国际组织的国家，不能用来数城市的人口。"}, {"text": "他是这所大学的成员国。", "explanation": "这里应该用〈学生〉。学生是在学校读书的人，成员国指组成国际组织的国家，不能用来指学校里的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13218, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这三个成员国们都签了协议。", "corrected_sentence": "这三个成员国都签了协议。", "error_description": "错误：「这三个成员国」前面已经有数量词「三个」，后面不能再加「们」。名词前有数量词时不能再用「们」，应说「这三个成员国」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13218, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年有两位新成员国加入了欧盟。", "corrected_sentence": "今年有两个新成员国加入了欧盟。", "error_description": "错误：量词用错了。「成员国」指国家，应用量词「个」，「位」只用于人，应说「两个新成员国」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
