INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13220, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "法律效力指法律规范在特定时间、空间内对人们行为产生的强制约束力和保护作用。", "primary_collocate": null, "pronunciation": "fǎ lǜ xiào lì", "ipa": "fa˨˩˦ ly˥˩ ɕjɑʊ˥˩ li˥˩", "syllable_count": 4, "sentences": [{"text": "近年来，以欧盟为代表的政治实体推行了系统性监管框架，通过《一次性塑料指令》明确禁用十类常见塑料消费品，如餐具、吸管与发泡餐盒，并要求成员国将指令转化为国内法，实现法律效力的属地化延伸。", "target_word": "法律效力", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这份合同有法律效力。", "target_word": "法律效力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有签字的文件没有法律效力。", "target_word": "法律效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新法律从明年起有法律效力。", "target_word": "法律效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "口头约定也可能有法律效力。", "target_word": "法律效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院承认这份遗嘱的法律效力。", "target_word": "法律效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宪法的法律效力最高。", "target_word": "法律效力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条规定的法律效力只在本省。", "target_word": "法律效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师问这份协议有没有法律效力。", "target_word": "法律效力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过期的证件失去了法律效力。", "target_word": "法律效力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "法律规范在一定时间和空间内对行为的强制约束力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5597deb1-751e-4c58-ad43-76c28f29457a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13220, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心跳", "is_correct": false, "explanation": "语义：“属地化延伸”说的是约束力的范围，心跳不能被延伸，句意不通。"}, {"text": "法律效力", "is_correct": true, "explanation": "正确。句中延伸的是法律规范的强制约束力，“法律效力”符合语境。"}, {"text": "塑料消费品", "is_correct": false, "explanation": "语义：句中要延伸的是规则的约束力，塑料消费品本身不能被“延伸”。"}, {"text": "外交关系", "is_correct": false, "explanation": "语义：这句话谈的是指令的法律约束力，与外交关系无关。"}], "explanations": {"心跳": "语义：“属地化延伸”说的是约束力的范围，心跳不能被延伸，句意不通。", "法律效力": "正确。句中延伸的是法律规范的强制约束力，“法律效力”符合语境。", "塑料消费品": "语义：句中要延伸的是规则的约束力，塑料消费品本身不能被“延伸”。", "外交关系": "语义：这句话谈的是指令的法律约束力，与外交关系无关。"}, "sentence_index": 0, "correct_answer": "法律效力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "违法的人必须承担法律效力。", "explanation": "这里应该用〈法律责任〉。效力指规则的约束力，违法的人承担的是责任，不能说“承担法律效力”。"}, {"text": "这种药的法律效力很快就出来了。", "explanation": "这里应该用〈药效〉。药物起作用的程度叫药效；“法律效力”只指法律规范的约束力，不能用于药。"}, {"text": "公民必须履行法律效力。", "explanation": "这里应该用〈法律义务〉。效力是规则的约束力，人要履行的是义务，不能说“履行法律效力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13220, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "甜度", "is_correct": false, "explanation": "搭配：“甜度”只用于食物等的味道，不能说“宪法的甜度”。"}, {"text": "法律效力", "is_correct": true, "explanation": "正确。“法律效力”指宪法作为法律规范的约束力，说宪法效力最高，符合句意。"}, {"text": "体温", "is_correct": false, "explanation": "语义：宪法没有体温，这句话与常识不符。"}, {"text": "热量", "is_correct": false, "explanation": "语义：“热量”指能量，不能用来描述宪法的状态。"}], "explanations": {"甜度": "搭配：“甜度”只用于食物等的味道，不能说“宪法的甜度”。", "法律效力": "正确。“法律效力”指宪法作为法律规范的约束力，说宪法效力最高，符合句意。", "体温": "语义：宪法没有体温，这句话与常识不符。", "热量": "语义：“热量”指能量，不能用来描述宪法的状态。"}, "sentence_index": 6, "correct_answer": "法律效力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府给这家公司颁发了法律效力。", "explanation": "这里应该用〈营业许可〉。颁发的对象是证照或许可，“效力”不能被颁发。"}, {"text": "这次培训的法律效力很好。", "explanation": "这里应该用〈效果〉。效力在这里指法律规则的约束力，培训的成效应说效果，不能说“法律效力很好”。"}, {"text": "这台机器的法律效力很高。", "explanation": "这里应该用〈效率〉。效力指法律规则的约束力，机器的工作产出应说效率，不能说“法律效力很高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13220, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项规定是法律效力。", "corrected_sentence": "这项规定有法律效力。", "error_description": "错误形式：“是法律效力”；正确形式：“有法律效力”。“是”表示等同，后接名词；“法律效力”是规则的约束力，表示拥有要用动词“有”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13220, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份协议不有法律效力。", "corrected_sentence": "这份协议没有法律效力。", "error_description": "错误形式：“不有法律效力”；正确形式：“没有法律效力”。“有”的否定只能用“没”，不能用“不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
