INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13222, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指从构思到实现一个物品或系统的过程，包括功能、外观和用户体验的设计。", "primary_collocate": null, "pronunciation": "chǎn pǐn shè jì", "ipa": "ʈʂʰan˨˩ pʰin˨˩ ʂɤ˥˩ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "该立法不仅体现对生产者的延伸责任要求，更推动产品设计向可循环模式转型，形成“污染者付费”的制度逻辑。", "target_word": "产品设计", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "可以预见，未来立法将更强调全生命周期管理，从原料提取、产品设计到废弃物回收，形成闭环控制体系。", "target_word": "产品设计", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "好的产品设计要同时考虑功能和外观。", "target_word": "产品设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司最重视产品设计，每年都投入很多钱。", "target_word": "产品设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学里学的是产品设计。", "target_word": "产品设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款手机的产品设计让用户用起来很方便。", "target_word": "产品设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了改进产品设计，团队收集了很多用户意见。", "target_word": "产品设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次产品设计比赛吸引了很多年轻人参加。", "target_word": "产品设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产品设计出了问题，工厂只好重新做样品。", "target_word": "产品设计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把环保放在产品设计的第一位。", "target_word": "产品设计", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面语", "sense_fingerprint": "从构思到实现产品的功能、外观与体验设计", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5597deb1-751e-4c58-ad43-76c28f29457a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13222, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "产品设计", "is_correct": true, "explanation": "正确：“产品设计”指从构思到实现产品的设计过程，正好是“推动……向可循环模式转型”的对象。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是能被推动转型为生产模式的对象，这样读句子不通。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“转型”说的是生产和循环的模式，不说工资转型，这里搭配不当。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是学生交给学校的钱，不能作为“推动……向可循环模式转型”的对象，这样读不通。"}], "explanations": {"产品设计": "正确：“产品设计”指从构思到实现产品的设计过程，正好是“推动……向可循环模式转型”的对象。", "天气": "语义：天气不是能被推动转型为生产模式的对象，这样读句子不通。", "工资": "搭配：“转型”说的是生产和循环的模式，不说工资转型，这里搭配不当。", "学费": "语义：学费是学生交给学校的钱，不能作为“推动……向可循环模式转型”的对象，这样读不通。"}, "sentence_index": 0, "correct_answer": "产品设计"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座大楼的产品设计很有特色，外墙用了很多玻璃。", "explanation": "这里应该用〈建筑设计〉。产品设计针对可以批量制造的物品，大楼不是产品，应说建筑设计。"}, {"text": "这家工厂每天能卖出很多产品设计。", "explanation": "这里应该用〈商品〉。卖出的应是可以买卖的商品，设计是构思过程，不能像商品一样卖出。"}, {"text": "这座公园的产品设计很有特色，树木和湖水都很美。", "explanation": "这里应该用〈园林设计〉。产品设计针对可以批量制造的物品，公园的布置应说园林设计。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13222, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产品设计", "is_correct": true, "explanation": "正确：“产品设计”是团队要改进的对象，与“为了改进……团队收集用户意见”相符。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的先天身体特征，团队收集用户意见无法用来改进它，这样读不通。"}, {"text": "历史", "is_correct": false, "explanation": "搭配：“改进”通常搭配产品、服务、质量，不说“改进历史”，搭配不当。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：海拔是地理高度，团队无法通过用户意见去改进它。"}], "explanations": {"产品设计": "正确：“产品设计”是团队要改进的对象，与“为了改进……团队收集用户意见”相符。", "身高": "语义：身高是人的先天身体特征，团队收集用户意见无法用来改进它，这样读不通。", "历史": "搭配：“改进”通常搭配产品、服务、质量，不说“改进历史”，搭配不当。", "海拔": "语义：海拔是地理高度，团队无法通过用户意见去改进它。"}, "sentence_index": 6, "correct_answer": "产品设计"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场晚会的产品设计很成功，观众都很满意。", "explanation": "这里应该用〈策划〉。产品设计针对可以制造的物品，晚会的安排应说策划。"}, {"text": "这次产品设计很愉快，我们去了三个城市。", "explanation": "这里应该用〈旅行〉。产品设计指设计物品样子的过程，去了三个城市说明是出行，应说旅行。"}, {"text": "这个产品设计很热闹，人们都出来看灯。", "explanation": "这里应该用〈节日〉。产品设计指设计过程，不能用来形容热闹的庆祝场面，应说节日。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13222, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一个很好产品设计，用起来很方便。", "corrected_sentence": "这是一个很好的产品设计，用起来很方便。", "error_description": "结构错误：“很好”修饰名词时要加“的”，应说“很好的产品设计”，漏掉“的”就不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13222, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这根产品设计很新颖，用户都很喜欢。", "corrected_sentence": "这个产品设计很新颖，用户都很喜欢。", "error_description": "量词错误：“产品设计”是抽象的设计方案，应该用“个”，“根”只用于细长的东西，这里应改为“这个产品设计”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
