INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13223, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指造成环境污染的人、组织或事物。", "primary_collocate": null, "pronunciation": "wū rǎn zhě", "ipa": "u˥ ʐan˨˩ ʈʂɤ˨˩", "syllable_count": 3, "sentences": [{"text": "该立法不仅体现对生产者的延伸责任要求，更推动产品设计向可循环模式转型，形成“污染者付费”的制度逻辑。", "target_word": "污染者", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "污染者应该为自己造成的污染付钱。", "target_word": "污染者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方查出这家工厂是河水的主要污染者。", "target_word": "污染者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要求污染者在一个月内清理河道。", "target_word": "污染者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "污染者不但包括工厂，也包括普通市民。", "target_word": "污染者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照新规定，污染者要缴纳环境费用。", "target_word": "污染者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者调查了这条河最大的污染者。", "target_word": "污染者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "许多污染者没有处理废水就直接排放了。", "target_word": "污染者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁是污染者，谁就应该负责治理。", "target_word": "污染者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车尾气也是城市空气的污染者之一。", "target_word": "污染者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面语", "sense_fingerprint": "造成环境污染的人、组织或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5597deb1-751e-4c58-ad43-76c28f29457a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13223, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "污染者", "is_correct": true, "explanation": "正确：“污染者付费”是“谁污染谁付费”的原则，“污染者”指造成污染的一方。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不会付费，也不是造成污染的一方，这样读不通。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：海拔是地理高度，不能用来指付费的一方。"}, {"text": "东西", "is_correct": false, "explanation": "语域：“东西”口语、泛指，不适合法律术语式的“……付费”。"}], "explanations": {"污染者": "正确：“污染者付费”是“谁污染谁付费”的原则，“污染者”指造成污染的一方。", "天气": "语义：天气不会付费，也不是造成污染的一方，这样读不通。", "海拔": "语义：海拔是地理高度，不能用来指付费的一方。", "东西": "语域：“东西”口语、泛指，不适合法律术语式的“……付费”。"}, "sentence_index": 0, "correct_answer": "污染者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位污染者每天给病人看病，很受欢迎。", "explanation": "这里应该用〈医生〉。污染者指造成污染的一方，给病人看病的应说医生。"}, {"text": "这位污染者每天开车送孩子们上学。", "explanation": "这里应该用〈司机〉。污染者指造成污染的一方，开车接送孩子的应说司机。"}, {"text": "这位污染者做的菜很好吃，大家都爱去那家饭馆。", "explanation": "这里应该用〈厨师〉。污染者指造成污染的一方，做菜的应说厨师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13223, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "污染者", "is_correct": true, "explanation": "正确：“最大的污染者”指对这条河污染最严重的一方，与“调查”的语境相符。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：海拔是地理高度，不是可以被调查的污染方，这样读不通。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格只用于人，“最大的性格”放在这里不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是人或动物的身体特征，不能用来描述一条河，这样读不通。"}], "explanations": {"污染者": "正确：“最大的污染者”指对这条河污染最严重的一方，与“调查”的语境相符。", "海拔": "语义：海拔是地理高度，不是可以被调查的污染方，这样读不通。", "性格": "语义：性格只用于人，“最大的性格”放在这里不通。", "体重": "语义：“体重”是人或动物的身体特征，不能用来描述一条河，这样读不通。"}, "sentence_index": 6, "correct_answer": "污染者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位污染者的声音很好听，很多人都喜欢。", "explanation": "这里应该用〈歌手〉。污染者指造成污染的一方，声音好听、受人喜欢的应说歌手。"}, {"text": "这位污染者很认真，学生都很喜欢他。", "explanation": "这里应该用〈老师〉。污染者指造成污染的一方，教学生的应说老师。"}, {"text": "污染者在路口指挥交通，司机都听他的。", "explanation": "这里应该用〈警察〉。污染者指造成污染的一方，指挥交通的应说警察。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13223, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂是一个很大污染者。", "corrected_sentence": "这家工厂是一个很大的污染者。", "error_description": "结构错误：“很大”修饰名词时要加“的”，应说“很大的污染者”，漏掉“的”就不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13223, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "城市里有一辆主要的污染者。", "corrected_sentence": "城市里有一个主要的污染者。", "error_description": "量词错误：“污染者”应该用“个”，“辆”只用于车辆，这里应改为“一个主要的污染者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31032feb-6efb-4177-9431-e81a1674bbfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
