INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13225, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时间表是用来规划和记录各项活动或任务在特定时间进行的表格或清单。", "primary_collocate": null, "pronunciation": "shí jiān biǎo", "ipa": "ʂɨ˧˥ tɕjɛn˥ pjɑʊ˨˩˦", "syllable_count": 3, "sentences": [{"text": "例如，东南亚某国通过国家环境战略引入全面禁塑时间表，分阶段禁止聚乙烯薄膜与塑料袋流通，并建立地方级执法机制监督商业场所合规情况。", "target_word": "时间表", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个项目的时间表排得很紧。", "target_word": "时间表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把新的时间表发给大家。", "target_word": "时间表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司定好了搬家的时间表。", "target_word": "时间表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照时间表，工厂下个月就要完工。", "target_word": "时间表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们还没有公布修路的时间表。", "target_word": "时间表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次改革的时间表排到了明年。", "target_word": "时间表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理要求大家严格遵守时间表。", "target_word": "时间表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起讨论了学校建新楼的时间表。", "target_word": "时间表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市地铁的开通时间表还没有定。", "target_word": "时间表", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "规划事务进度的时间安排", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eb372b5-146c-44b4-9a82-c006352a078d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13225, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时间表", "is_correct": true, "explanation": "正确。“全面禁塑时间表”指分阶段实施禁塑的时间安排。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图是地理图示，与句中分阶段的时间安排不符。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：菜单是列出菜品的表，与政策的时间安排无关。"}, {"text": "食谱", "is_correct": false, "explanation": "搭配：“食谱”指做菜的配方，不与“全面禁塑”搭配。"}], "explanations": {"时间表": "正确。“全面禁塑时间表”指分阶段实施禁塑的时间安排。", "地图": "语义：地图是地理图示，与句中分阶段的时间安排不符。", "菜单": "语义：菜单是列出菜品的表，与政策的时间安排无关。", "食谱": "搭配：“食谱”指做菜的配方，不与“全面禁塑”搭配。"}, "sentence_index": 0, "correct_answer": "时间表"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司定了一只搬家的时间表。", "explanation": "这里应该用〈个〉。“时间表”作计划义时常用“个”；“只”用于动物或单件物品，不用于计划。"}, {"text": "公司定了一颗搬家的时间表。", "explanation": "这里应该用〈个〉。“颗”用于颗粒或小而圆的东西，不用于计划。"}, {"text": "公司定了一头搬家的时间表。", "explanation": "这里应该用〈个〉。“头”用于牛、猪等动物，不能用于计划安排。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13225, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时间表", "is_correct": true, "explanation": "正确。“这次改革的时间表”指改革的时间安排。"}, {"text": "账本", "is_correct": false, "explanation": "语义：账本指记账的本子，“改革的账本排到了明年”说不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本指教学用书，与改革的时间安排不符。"}, {"text": "地址", "is_correct": false, "explanation": "语义：“地址”指位置，不能“排到明年”，与时间安排无关。"}], "explanations": {"时间表": "正确。“这次改革的时间表”指改革的时间安排。", "账本": "语义：账本指记账的本子，“改革的账本排到了明年”说不通。", "课本": "语义：课本指教学用书，与改革的时间安排不符。", "地址": "语义：“地址”指位置，不能“排到明年”，与时间安排无关。"}, "sentence_index": 6, "correct_answer": "时间表"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个项目的时间表已经吃完了。", "explanation": "这里不能用“时间表”。时间表是计划安排，不能说“吃完”；若指完成程度，应说“进度”。"}, {"text": "这份合同的时间表是五年。", "explanation": "这里应该用〈有效期〉。有效期指时间范围，可以说“是五年”；时间表指安排，不表示期限长度。"}, {"text": "这台机器的时间表是十年。", "explanation": "这里应该用〈寿命〉。寿命指使用年限，“时间表是十年”说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13225, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经理为这次搬家定了一只时间表。", "corrected_sentence": "经理为这次搬家定了一份时间表。", "error_description": "量词错误：“时间表”应用“份”，不能用“只”，“只”用于动物或单件物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13225, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经理发了一把时间表给大家。", "corrected_sentence": "经理发了一张时间表给大家。", "error_description": "量词错误：“时间表”应用“张”，不能用“把”，“把”用于有柄的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
