INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13230, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指人们进行活动、工作、学习等所在的特定地方或空间。", "primary_collocate": null, "pronunciation": "chǎng suǒ", "ipa": "ʈʂʰaŋ˨˩˦ suo̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "图书馆是学习的好场所。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园是老人锻炼的场所。", "target_word": "场所", "complexity_tier": "T3", "furigana": "chǎng suǒ", "sentence_source": "generated"}, {"text": "医院是需要安静的场所。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个场所抽烟是不对的。", "target_word": "场所", "complexity_tier": "T3", "furigana": "chǎng suǒ", "sentence_source": "generated"}, {"text": "这个公园是孩子们玩的场所。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂是工人工作的场所。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商场和电影院都是人多的场所。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个场所晚上十点以后不让小孩进去。", "target_word": "场所", "complexity_tier": "T3", "furigana": "chǎng suǒ", "sentence_source": "generated"}, {"text": "学校是学生学习的主要场所。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进入这类场所，要先戴好口罩。", "target_word": "场所", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个场所", "label": "量词"}, {"form": "公共场所", "label": "复合"}, {"form": "娱乐场所", "label": "复合"}], "register": "中性", "sense_fingerprint": "人们活动、工作、学习所在的特定地方或空间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eb372b5-146c-44b4-9a82-c006352a078d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13230, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "场所", "is_correct": true, "explanation": "正确：图书馆是学习活动的场所，符合句意。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜是吃的东西，图书馆不是学习的饭菜。"}, {"text": "床", "is_correct": false, "explanation": "搭配：「好床」指睡觉用的，与「学习」搭配不当。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果与学习无关，不能说「学习的好水果」。"}], "explanations": {"场所": "正确：图书馆是学习活动的场所，符合句意。", "饭菜": "语义：饭菜是吃的东西，图书馆不是学习的饭菜。", "床": "搭配：「好床」指睡觉用的，与「学习」搭配不当。", "水果": "语义：水果与学习无关，不能说「学习的好水果」。"}, "sentence_index": 0, "correct_answer": "场所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事花了三个小时的场所才做完。", "explanation": "这里应该用〈时间〉。场所指人们活动的地方，不指时间长短；花了多长时间要用〈时间〉。"}, {"text": "他是我的场所，每天教我们数学。", "explanation": "这里应该用〈老师〉。场所指地方或空间，不能用来指人；教数学的人要说〈老师〉。"}, {"text": "这家饭店的场所很好吃。", "explanation": "这里应该用〈菜〉。场所是地方，不能吃；饭店里好吃的是〈菜〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13230, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "场所", "is_correct": true, "explanation": "正确：商场、电影院都是人多的公共场所，符合句意。"}, {"text": "时候", "is_correct": false, "explanation": "语义：商场和电影院是空间，不是时间，不能说「人多的时候」。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是物品，商场和电影院不是玩具。"}, {"text": "公式", "is_correct": false, "explanation": "搭配：「人多」形容场所或场合，不能修饰公式。"}], "explanations": {"场所": "正确：商场、电影院都是人多的公共场所，符合句意。", "时候": "语义：商场和电影院是空间，不是时间，不能说「人多的时候」。", "玩具": "语义：玩具是物品，商场和电影院不是玩具。", "公式": "搭配：「人多」形容场所或场合，不能修饰公式。"}, "sentence_index": 6, "correct_answer": "场所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章的场所很长，大家都读不完。", "explanation": "这里应该用〈篇幅〉。场所指人们活动的地方，不能用来形容文章的长短。"}, {"text": "他的场所很好听，大家都喜欢。", "explanation": "这里应该用〈声音〉。场所指地方，不能用来形容声音好听。"}, {"text": "他下班后回到了场所，好好休息。", "explanation": "这里应该用〈住处〉。场所指活动的地方，不指家或住的地方，下班回家要说〈住处〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13230, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一条安全的场所，孩子可以在这里玩。", "corrected_sentence": "这是一个安全的场所，孩子可以在这里玩。", "error_description": "量词错误：场所是地方，应说「一个场所」，不能用「条」，「条」用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13230, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把学生带了进这个场所。", "corrected_sentence": "老师把学生带进了这个场所。", "error_description": "补语与「了」位置错误：「进」是趋向补语，「了」应放在「带进」之后，应说「带进了这个场所」，不能说「带了进」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106aff3e-3577-4f6f-9ec1-76fbc4878afd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
