INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13246, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从相反或对照的一面来看，引出与前述情况形成对比的另一方。", "primary_collocate": null, "pronunciation": "fǎn guān", "ipa": "fan˨˩˦ kuan˥˥", "syllable_count": 2, "sentences": [{"text": "反观北美地区，政策路径呈现联邦与地方分化的格局。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "去年北方雨水很多，反观南方，一直很干。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥每天早起学习，反观弟弟，总是睡到中午。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店人很多，反观对面那家，一个客人也没有。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里车越来越多，反观乡下，路上很安静。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对工作非常认真，反观自己，常常马虎。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的高铁发展很快，反观一些国家，还没有高铁。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东部城市房价很高，反观西部，价格便宜不少。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说这部电影好看，反观我，却觉得很无聊。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里冬天下了很多雪，反观去年，一点雪也没有。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "从相反的一面来看，引出对比的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f2a7402-8426-418d-9154-8fbf1758617b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13246, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反对", "is_correct": false, "explanation": "语义：“反对”表示对立，不能用来引出北美地区的政策格局，句意不通。"}, {"text": "反观", "is_correct": true, "explanation": "反观：从相反的一面来看，引出对照的情况，“反观北美地区”引出北美的政策格局，句中正确。"}, {"text": "复制", "is_correct": false, "explanation": "搭配：“复制”的对象是文件、内容，不能用于地区，“复制北美地区”不成立。"}, {"text": "缩小", "is_correct": false, "explanation": "语义：“缩小”指变小，与引出政策格局的对照无关，句子不通。"}], "explanations": {"反对": "语义：“反对”表示对立，不能用来引出北美地区的政策格局，句意不通。", "反观": "反观：从相反的一面来看，引出对照的情况，“反观北美地区”引出北美的政策格局，句中正确。", "复制": "搭配：“复制”的对象是文件、内容，不能用于地区，“复制北美地区”不成立。", "缩小": "语义：“缩小”指变小，与引出政策格局的对照无关，句子不通。"}, "sentence_index": 0, "correct_answer": "反观"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "将军反观队伍，满意地点了点头。", "explanation": "这里应该用〈检阅〉。反观指从相反或不同的角度看、引出对比，不表示逐一检查队伍。"}, {"text": "反观说明书，我们装好了这把椅子。", "explanation": "这里应该用〈对照〉。反观是从相反的一面看、引出对比的另一方，不能用来表示依照某物做事。"}, {"text": "站在山顶，他反观远方的大海。", "explanation": "这里应该用〈眺望〉。反观指从相反或不同的角度观察、引出对比，不表示向远处望去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "监督", "is_correct": false, "explanation": "语义：“监督”指督促管理，与高铁发展的对照无关，句子不通。"}, {"text": "反观", "is_correct": true, "explanation": "反观：从相反的一面来看，引出对照的情况，“反观一些国家”引出对比，句中正确。"}, {"text": "挖掘", "is_correct": false, "explanation": "搭配：“挖掘”的对象是资源、潜力，不能用于国家，“挖掘一些国家”不成立。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示接待，与高铁发展的对比不相符，句意不通。"}], "explanations": {"监督": "语义：“监督”指督促管理，与高铁发展的对照无关，句子不通。", "反观": "反观：从相反的一面来看，引出对照的情况，“反观一些国家”引出对比，句中正确。", "挖掘": "搭配：“挖掘”的对象是资源、潜力，不能用于国家，“挖掘一些国家”不成立。", "欢迎": "语义：“欢迎”表示接待，与高铁发展的对比不相符，句意不通。"}, "sentence_index": 6, "correct_answer": "反观"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他反观窗外的雨，久久不说话。", "explanation": "这里应该用〈凝视〉。反观指从相反或不同的角度看、引出对比，不表示定睛长时间注视。"}, {"text": "我们在公园里反观荷花，非常开心。", "explanation": "这里应该用〈观赏〉。反观是引出对照的另一方，不表示欣赏景物。"}, {"text": "他反观全场，找到了朋友。", "explanation": "这里应该用〈扫视〉。反观不表示快速环顾，而是从相反的一面看、引出对比。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "北方冬天很冷，反观，却很暖和。", "corrected_sentence": "北方冬天很冷，反观南方，却很暖和。", "error_description": "缺少宾语：“反观”是动词，后面要直接带对照的对象，此处缺少对象；应说「反观南方」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老家的夏天很凉快，反观的这里，却很闷热。", "corrected_sentence": "老家的夏天很凉快，反观这里，却很闷热。", "error_description": "语法错误：“反观”是动词，后面直接带对照的对象，中间不能加“的”，“反观的这里”不通。正确说法是「反观这里」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
