INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13249, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "按行政划分的区域，如省、市、县。", "primary_collocate": null, "pronunciation": "xíng zhèng qū", "ipa": "ɕiŋ˧˥ ʈʂɤŋ˥˩ tɕʰy˥", "syllable_count": 3, "sentences": [{"text": "联邦层面长期缺乏统一立法，但多个城市与州级行政区自主推行禁令，涵盖塑料吸管、外卖容器及零售包装等领域。", "target_word": "行政区", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "中国有很多不同的行政区。", "target_word": "行政区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个行政区的人口不太多。", "target_word": "行政区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京是一个很大的行政区。", "target_word": "行政区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个行政区都有自己的政府。", "target_word": "行政区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住的行政区离市中心很近。", "target_word": "行政区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的行政区分成了三个部分。", "target_word": "行政区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个行政区的名字很像。", "target_word": "行政区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们市一共有十个行政区。", "target_word": "行政区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个行政区去年建了三所学校。", "target_word": "行政区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "行政區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "按行政管理划分出的区域，如省、市、县", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f2a7402-8426-418d-9154-8fbf1758617b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13249, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行政区", "is_correct": true, "explanation": "行政区指按行政划分的区域，州级行政区可以自主推行禁令，与语境相符。"}, {"text": "法律条文", "is_correct": false, "explanation": "搭配：“推行禁令”的主体应是机构或地区，“法律条文”不能自主推行禁令。"}, {"text": "塑料吸管", "is_correct": false, "explanation": "语义：“塑料吸管”是物品，不是能自主推行禁令的主体，句意不通。"}, {"text": "夜市", "is_correct": false, "explanation": "语义：“夜市”是市场，不是行政主体，不能自主推行禁令。"}], "explanations": {"行政区": "行政区指按行政划分的区域，州级行政区可以自主推行禁令，与语境相符。", "法律条文": "搭配：“推行禁令”的主体应是机构或地区，“法律条文”不能自主推行禁令。", "塑料吸管": "语义：“塑料吸管”是物品，不是能自主推行禁令的主体，句意不通。", "夜市": "语义：“夜市”是市场，不是行政主体，不能自主推行禁令。"}, "sentence_index": 0, "correct_answer": "行政区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把行政区放在书架上。", "explanation": "这里应该用〈苹果〉。行政区是区域概念，不是实物，不能放在书架上。"}, {"text": "这个行政区昨天感冒了。", "explanation": "这里应该用〈孩子〉。行政区是区域，不是人，不会感冒。"}, {"text": "这个行政区很好吃。", "explanation": "这里应该用〈菜〉。行政区是区域概念，不是食物，不能用“好吃”形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13249, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行政区", "is_correct": true, "explanation": "行政区是可以分成部分的区域，“新的行政区分成了三个部分”符合书面语境。"}, {"text": "生日", "is_correct": false, "explanation": "语义：「生日」指某人出生的那一天，是不能分成部分的时间点，「新的生日分成了三个部分」句意不通。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“分成三个部分”一般说具体事物，不搭配抽象的“感情”。"}, {"text": "哥们", "is_correct": false, "explanation": "语域：“哥们”是口语，与书面语的“分成了三个部分”不协调，且指人。"}], "explanations": {"行政区": "行政区是可以分成部分的区域，“新的行政区分成了三个部分”符合书面语境。", "生日": "语义：「生日」指某人出生的那一天，是不能分成部分的时间点，「新的生日分成了三个部分」句意不通。", "感情": "搭配：“分成三个部分”一般说具体事物，不搭配抽象的“感情”。", "哥们": "语域：“哥们”是口语，与书面语的“分成了三个部分”不协调，且指人。"}, "sentence_index": 6, "correct_answer": "行政区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的行政区去年结婚了。", "explanation": "这里应该用〈哥哥〉。行政区是区域概念，不是人，不能结婚。"}, {"text": "行政区今年考上了大学。", "explanation": "这里应该用〈学生〉。行政区是区域概念，不是人，不能考大学。"}, {"text": "行政区每天早上六点起床。", "explanation": "这里应该用〈我〉。行政区是区域概念，不是人，不会起床。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13249, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个省分成了五条行政区。", "corrected_sentence": "这个省分成了五个行政区。", "error_description": "量词错误：“行政区”前应用“个”，“条”多用于河流、道路等细长事物，不能用于“行政区”。正确说法是“这个省分成了五个行政区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13249, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本新的行政区有很多学校。", "corrected_sentence": "这个新的行政区有很多学校。", "error_description": "量词错误：“行政区”前应用“个”，“本”用于书籍等印刷品，不能用于“行政区”。正确说法是“这个新的行政区有很多学校”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'efeec73f-f621-4873-8b4b-b7e45e5eaeb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
