INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13250, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "指从各方面包围或包括在内。", "primary_collocate": null, "pronunciation": "hán gài", "ipa": "xan˧˥ kai˥˩", "syllable_count": 2, "sentences": [{"text": "联邦层面长期缺乏统一立法，但多个城市与州级行政区自主推行禁令，涵盖塑料吸管、外卖容器及零售包装等领域。", "target_word": "涵盖", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "监管不再局限于禁限措施，更涵盖激励机制、信息透明与公众参与等多元工具。", "target_word": "涵盖", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这场以“绿脉计划”为名的植树造林行动，起初只是几位退休教师在村口荒坡上栽下的一百棵杨树苗，如今已演变为涵盖三十多个行政村、年均种植超过五万株本土树种的区域性环境保护实践。", "target_word": "涵盖", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这份报告涵盖了去年全年的数据。", "target_word": "涵盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门课涵盖历史、地理和文化。", "target_word": "涵盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查范围涵盖了全国十个城市。", "target_word": "涵盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的内容涵盖了生活的各个方面。", "target_word": "涵盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新规定涵盖所有在校学生。", "target_word": "涵盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试涵盖了前三个单元的知识。", "target_word": "涵盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的服务涵盖衣食住行。", "target_word": "涵盖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "涵盖了", "label": "体标"}, {"form": "涵盖着", "label": "体标"}, {"form": "涵蓋", "label": "繁体"}], "register": "书面", "sense_fingerprint": "范围、内容把各方面包括在内", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b3bbd23-8942-4e8f-b366-768ba894f710') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13250, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "涵盖", "is_correct": true, "explanation": "正确答案，指从各方面包括在内。"}, {"text": "寒带", "is_correct": false, "explanation": "寒带（hán dài）与涵盖（hán gài）第二音节声母不同（d 与 g），意思是寒冷地带。"}, {"text": "函告", "is_correct": false, "explanation": "函告（hán gào）与涵盖（hán gài）第二音节韵母不同（ao 与 ai），意思是用信函通知。"}, {"text": "寒害", "is_correct": false, "explanation": "寒害（hán hài）与涵盖（hán gài）第二音节声母不同（h 与 g），意思是寒冷造成的灾害。"}], "explanations": {"涵盖": "正确答案，指从各方面包括在内。", "寒带": "寒带（hán dài）与涵盖（hán gài）第二音节声母不同（d 与 g），意思是寒冷地带。", "函告": "函告（hán gào）与涵盖（hán gài）第二音节韵母不同（ao 与 ai），意思是用信函通知。", "寒害": "寒害（hán hài）与涵盖（hán gài）第二音节声母不同（h 与 g），意思是寒冷造成的灾害。"}, "sentence_index": null, "correct_answer": "涵盖"}, "level_3": {"options": [{"text": "涵盖", "is_correct": true, "explanation": "正确答案。句中“禁令”所涉及的范围正是塑料吸管、外卖容器等领域。"}, {"text": "排除", "is_correct": false, "explanation": "语义：“排除”与“推行禁令”的意思相反，禁令不会把塑料吸管排除在外。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”的宾语应是请求或邀请，不能说拒绝“等领域”。"}, {"text": "发明", "is_correct": false, "explanation": "语义：塑料吸管和外卖容器早已存在，禁令不可能“发明”它们，句意不通。"}], "explanations": {"涵盖": "正确答案。句中“禁令”所涉及的范围正是塑料吸管、外卖容器等领域。", "排除": "语义：“排除”与“推行禁令”的意思相反，禁令不会把塑料吸管排除在外。", "拒绝": "搭配：“拒绝”的宾语应是请求或邀请，不能说拒绝“等领域”。", "发明": "语义：塑料吸管和外卖容器早已存在，禁令不可能“发明”它们，句意不通。"}, "sentence_index": 0, "correct_answer": "涵盖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次活动涵盖三位嘉宾。", "explanation": "这里应该用〈包括〉。涵盖强调范围或领域的整体覆盖，不用来一一列举具体的人。"}, {"text": "这个盒子涵盖三支笔。", "explanation": "这里应该用〈包含〉。涵盖说的是范围或领域，不用来说容器里装着的具体物品。"}, {"text": "这块蛋糕涵盖很多奶油。", "explanation": "这里应该用〈含有〉。涵盖用于范围和领域，不用来说食物里含有的成分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13250, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "涵盖", "is_correct": true, "explanation": "正确答案。“内容”所涉及的范围是“生活的各个方面”。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”的对象应是书籍或文章，不说出版“生活的各个方面”。"}, {"text": "拍摄", "is_correct": false, "explanation": "语义：拍摄需要镜头，书的内容不能“拍摄”生活的各个方面。"}, {"text": "缩小", "is_correct": false, "explanation": "搭配：“缩小”的宾语应是可以变小的数量或规模，不能与“生活的各个方面”搭配。"}], "explanations": {"涵盖": "正确答案。“内容”所涉及的范围是“生活的各个方面”。", "出版": "搭配：“出版”的对象应是书籍或文章，不说出版“生活的各个方面”。", "拍摄": "语义：拍摄需要镜头，书的内容不能“拍摄”生活的各个方面。", "缩小": "搭配：“缩小”的宾语应是可以变小的数量或规模，不能与“生活的各个方面”搭配。"}, "sentence_index": 6, "correct_answer": "涵盖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师在黑板上涵盖了三个例子。", "explanation": "这里应该用〈列举〉。涵盖强调范围的整体包含，不用于在黑板上一一列出具体的例子。"}, {"text": "他在作业本上涵盖了五道题。", "explanation": "这里应该用〈列出〉。涵盖表示范围的整体包括，不用于把作业本上的题目一道道写出来。"}, {"text": "他在名册上涵盖了三个名字。", "explanation": "这里应该用〈登记〉。涵盖强调范围的整体包括，不用于把名字逐个记在名册上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13250, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项规定被涵盖了全体员工。", "corrected_sentence": "这项规定涵盖了全体员工。", "error_description": "错误：“被”字句中，“这项规定”成了受事，而“涵盖”又带了宾语“全体员工”，施受关系颠倒且结构重复。应说“这项规定涵盖了全体员工”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13250, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次检查没有涵盖了所有车间。", "corrected_sentence": "这次检查没有涵盖所有车间。", "error_description": "错误：“没有”与“了”不能同用。否定已发生的动作时应说“没有涵盖”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
