INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13254, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事情发展过程中，在某个时间点之后的部分或结果。", "primary_collocate": null, "pronunciation": "hòu xù", "ipa": "xoʊ̯˥˩ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "这次改革只是开始，后续的政策还要慢慢讨论。", "target_word": "后续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议结束后，后续工作由小王负责。", "target_word": "后续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司会处理这件事的后续问题。", "target_word": "后续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手术很成功，后续治疗需要三个月。", "target_word": "后续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把后续的材料都发给我。", "target_word": "后续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "项目的后续工作已经安排好了。", "target_word": "后续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买了新手机，后续的服务也很好。", "target_word": "后续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的后续安排，我们明天通知你。", "target_word": "后续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是第一步，后续还有很多事要做。", "target_word": "后续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说后续的课会更难一点。", "target_word": "后续", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "某个时间点之后的部分或结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a51fb9fe-8abb-41e1-afcc-9db367ee8af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13254, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后续", "is_correct": true, "explanation": "正确。「后续的政策」指之后再出台的政策，「后续」表示接续在后的。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：「厨房的政策」读不通，厨房不是政策，句意不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：「钢琴的政策」读不通，「政策」不能用「钢琴」修饰。"}, {"text": "草莓", "is_correct": false, "explanation": "语义：「草莓的政策」读不通，句意不通。"}], "explanations": {"后续": "正确。「后续的政策」指之后再出台的政策，「后续」表示接续在后的。", "厨房": "语义：「厨房的政策」读不通，厨房不是政策，句意不通。", "钢琴": "搭配：「钢琴的政策」读不通，「政策」不能用「钢琴」修饰。", "草莓": "语义：「草莓的政策」读不通，句意不通。"}, "sentence_index": 0, "correct_answer": "后续"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她怀孕后续身体很不舒服。", "explanation": "近义词误用：这里应该用〈后期〉。后续指接续在某事之后出现的事或工作，表示阶段要说「后期」。"}, {"text": "毕业后续我去了北京工作。", "explanation": "近义词误用：这里应该用〈以后〉。后续指之后接着的事情或部分，不能放在动词短语后面表示“……之后”，表示时间先后要用「以后」。"}, {"text": "他小时候很胖，后续变瘦了。", "explanation": "近义词误用：这里应该用〈后来〉。后续是接续事情的意思，不能作时间副词表示「后来」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e5954d-e01f-4bcd-a537-20930de46b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13254, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后续", "is_correct": true, "explanation": "正确。「后续的服务」指购买之后提供的接续性服务。"}, {"text": "螃蟹", "is_correct": false, "explanation": "语义：「螃蟹的服务」读不通，螃蟹不能提供服务。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是灾害，「地震的服务」读不通。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：「大海」不能拥有「服务」，二者无法搭配。"}], "explanations": {"后续": "正确。「后续的服务」指购买之后提供的接续性服务。", "螃蟹": "语义：「螃蟹的服务」读不通，螃蟹不能提供服务。", "地震": "语义：地震是灾害，「地震的服务」读不通。", "大海": "搭配：「大海」不能拥有「服务」，二者无法搭配。"}, "sentence_index": 6, "correct_answer": "后续"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份报告还有一只后续，大家都在等。", "explanation": "量词误用：「只」用于动物或成对的东西，这里应该用〈个〉或〈项〉。"}, {"text": "会议结束后续，我们去吃饭了。", "explanation": "近义词误用：这里应该用〈之后〉。后续表示接续的事情，不能表示时间上的先后。"}, {"text": "他坐在我后续，一直在讲话。", "explanation": "近义词误用：这里应该用〈后面〉。后续表示接续发生的事，不能表示空间上的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e5954d-e01f-4bcd-a537-20930de46b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13254, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事还有一根后续，大家都在等。", "corrected_sentence": "这件事还有一个后续，大家都在等。", "error_description": "量词误用：「后续」作可数名词时用「个」或「项」，「根」多用于细长的东西，不能计量「后续」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e5954d-e01f-4bcd-a537-20930de46b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13254, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次调查还有一座后续，大家都在等。", "corrected_sentence": "这次调查还有一个后续，大家都在等。", "error_description": "量词误用：「座」用于山、楼等大型固定物，「后续」应用「个」或「项」计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e5954d-e01f-4bcd-a537-20930de46b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
