INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13255, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指具有全国范围的性质或特点。", "primary_collocate": null, "pronunciation": "quán guó xìng", "ipa": "tɕʰɥɛn˧˥ kwɔ˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "然而，此类地方实践常成为后续全国性立法的试验模板，体现政策演化的渐进逻辑。", "target_word": "全国性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这是一次全国性的比赛，很多人都来了。", "target_word": "全国性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题不是地方问题，而是全国性问题。", "target_word": "全国性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年有一场全国性的考试。", "target_word": "全国性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府发出了全国性的通知。", "target_word": "全国性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全国性的大会下个月在北京开。", "target_word": "全国性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日已经成了全国性的活动。", "target_word": "全国性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行是全国性银行，各地都有分行。", "target_word": "全国性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次调查是全国性的，一共问了一万人。", "target_word": "全国性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个比赛太小，不是全国性的。", "target_word": "全国性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "范围覆盖整个国家的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a51fb9fe-8abb-41e1-afcc-9db367ee8af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13255, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全国性", "is_correct": true, "explanation": "正确：全国性指范围覆盖全国，句中“后续全国性立法”与前文的地方实践相接，符合句意。"}, {"text": "突发性", "is_correct": false, "explanation": "语义：突发性指突然发生，与句中体现的渐进推进逻辑相反。"}, {"text": "一次性", "is_correct": false, "explanation": "语义：一次性指只做一回，与“后续”立法及试验模板逐步推广的意思不符。"}, {"text": "爆炸性", "is_correct": false, "explanation": "语义：爆炸性形容来势猛烈、影响巨大的事件，不能修饰“立法”，与句中渐进推进的逻辑也不符。"}], "explanations": {"全国性": "正确：全国性指范围覆盖全国，句中“后续全国性立法”与前文的地方实践相接，符合句意。", "突发性": "语义：突发性指突然发生，与句中体现的渐进推进逻辑相反。", "一次性": "语义：一次性指只做一回，与“后续”立法及试验模板逐步推广的意思不符。", "爆炸性": "语义：爆炸性形容来势猛烈、影响巨大的事件，不能修饰“立法”，与句中渐进推进的逻辑也不符。"}, "sentence_index": 0, "correct_answer": "全国性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是一场全国性的比赛，各国选手都来了。", "explanation": "这里应该用〈国际性〉。全国性指范围只在国内，不能用来形容有多个国家参加的比赛。"}, {"text": "这是一个全国性的小活动，只有本村人参加。", "explanation": "这里应该用〈地方性〉。全国性指范围覆盖全国，只有本村人参加的活动应说地方性。"}, {"text": "我家的狗很全国性。", "explanation": "这里应该用〈普通〉。全国性指具有全国范围的性质，不能用来形容狗的特点，形容狗要说普通或可爱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e5954d-e01f-4bcd-a537-20930de46b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13255, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全国性", "is_correct": true, "explanation": "正确：节日已成为范围覆盖全国的活动，“全国性”符合句意。"}, {"text": "偶发性", "is_correct": false, "explanation": "搭配：偶发性多修饰偶然出现的事件，不能修饰已经成形的活动，搭配不当。"}, {"text": "私人性", "is_correct": false, "explanation": "语义：私人性指只属于个人，与节日已成为大众活动的意思相反。"}, {"text": "个别性", "is_correct": false, "explanation": "语义：个别性指只涉及少数，与“已经成了”所体现的扩大趋势相反。"}], "explanations": {"全国性": "正确：节日已成为范围覆盖全国的活动，“全国性”符合句意。", "偶发性": "搭配：偶发性多修饰偶然出现的事件，不能修饰已经成形的活动，搭配不当。", "私人性": "语义：私人性指只属于个人，与节日已成为大众活动的意思相反。", "个别性": "语义：个别性指只涉及少数，与“已经成了”所体现的扩大趋势相反。"}, "sentence_index": 6, "correct_answer": "全国性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是一个全国性的合作组织，只有三个邻国加入。", "explanation": "这里应该用〈区域性〉。全国性指范围覆盖全国，只有三个邻国加入的组织应说区域性。"}, {"text": "这家店只开在我们村，是一家全国性的小店。", "explanation": "这里应该用〈本地〉。全国性指覆盖全国，只开在一个村的店应说本地的。"}, {"text": "我们班的考试是全国性的，只有十个人参加。", "explanation": "这里应该用〈班内〉。全国性指范围覆盖全国，只有十个人参加的班级考试应说班内。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e5954d-e01f-4bcd-a537-20930de46b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13255, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛是全国性地，很多学校都参加了。", "corrected_sentence": "这次比赛是全国性的，很多学校都参加了。", "error_description": "结构助词误用：「全国性」作谓语时应用「的」，「地」只用于修饰动词，此处应为「是全国性的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e5954d-e01f-4bcd-a537-20930de46b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13255, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告是全国性了的调查结果。", "corrected_sentence": "这份报告是全国性的调查结果。", "error_description": "“全国性”与后面的“的”之间不能插“了”。误加“了”，表示完成的“了”不能插在修饰成分中间，应为“全国性的调查结果”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e5954d-e01f-4bcd-a537-20930de46b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
