INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13256, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为了了解某事物的效果或性能而进行尝试或操作。", "primary_collocate": null, "pronunciation": "shì yàn", "ipa": "ʂɻ̩˥˩ jɛn˥˩", "syllable_count": 2, "sentences": [{"text": "然而，此类地方实践常成为后续全国性立法的试验模板，体现政策演化的渐进逻辑。", "target_word": "试验", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这次试验用了三个月，结果很好。", "target_word": "试验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新药在上市前要做很多试验。", "target_word": "试验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种新手机的防水试验已经通过了。", "target_word": "试验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火箭发射前，工程师做了多次试验。", "target_word": "试验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项试验失败了，但是我们学到了很多。", "target_word": "试验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们把试验的数据都记在本子上。", "target_word": "试验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个试验需要两个人一起做，一个人做不了。", "target_word": "试验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了做这个试验，他们准备了一年。", "target_word": "试验", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家用小白鼠做过很多次试验。", "target_word": "试验", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一次试验", "label": "量词"}, {"form": "一项试验", "label": "量词"}, {"form": "試驗", "label": "繁体"}], "register": "通用", "sense_fingerprint": "为检验效果或性能而做的尝试性操作（名词：一次试验）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1be5a6e3-5db9-4be7-88db-c287895b77cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13256, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "试验", "is_correct": true, "explanation": "试验（shì yàn）：为了检验效果或性能而做的尝试，是正确答案。"}, {"text": "式样", "is_correct": false, "explanation": "式样（shì yàng）与试验只有韵尾不同（yàng 与 yàn），意思是款式、样子。"}, {"text": "食盐", "is_correct": false, "explanation": "食盐（shí yán）两个音节的声调都与试验不同（第二声、第二声 与 第四声、第四声），意思是吃的盐。"}, {"text": "誓言", "is_correct": false, "explanation": "誓言（shì yán）第二个音节为第二声，与试验的 yàn（第四声）声调不同，意思是发誓的话。"}, {"text": "失言", "is_correct": false, "explanation": "失言（shī yán）两个音节的声调都与试验不同，意思是说错了话。"}, {"text": "试演", "is_correct": false, "explanation": "试演（shì yǎn）第二个音节 yǎn（第三声）与试验的 yàn（第四声）声调不同，意思是试着表演。"}], "explanations": {"试验": "试验（shì yàn）：为了检验效果或性能而做的尝试，是正确答案。", "式样": "式样（shì yàng）与试验只有韵尾不同（yàng 与 yàn），意思是款式、样子。", "食盐": "食盐（shí yán）两个音节的声调都与试验不同（第二声、第二声 与 第四声、第四声），意思是吃的盐。", "誓言": "誓言（shì yán）第二个音节为第二声，与试验的 yàn（第四声）声调不同，意思是发誓的话。", "失言": "失言（shī yán）两个音节的声调都与试验不同，意思是说错了话。", "试演": "试演（shì yǎn）第二个音节 yǎn（第三声）与试验的 yàn（第四声）声调不同，意思是试着表演。"}, "sentence_index": null, "correct_answer": "试验"}, "level_3": {"options": [{"text": "试验", "is_correct": true, "explanation": "试验：指正式推广前在局部检验的做法，与“模板”搭配，句意正确。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与“立法”不相干，“立法的颜色模板”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能作为“立法”的模板，句子的意思不通。"}, {"text": "老妈", "is_correct": false, "explanation": "语域：“老妈”是口语，与“体现政策演化的渐进逻辑”这类书面语不合。"}], "explanations": {"试验": "试验：指正式推广前在局部检验的做法，与“模板”搭配，句意正确。", "颜色": "语义：“颜色”与“立法”不相干，“立法的颜色模板”说不通。", "天气": "语义：“天气”不能作为“立法”的模板，句子的意思不通。", "老妈": "语域：“老妈”是口语，与“体现政策演化的渐进逻辑”这类书面语不合。"}, "sentence_index": 0, "correct_answer": "试验"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次试验我考了一百分。", "explanation": "这里应该用〈考试〉。试验是为检验效果而做的操作，不能说“考一百分”，考分数要用“考试”。"}, {"text": "医生每天都要试验病人的体温。", "explanation": "这里应该用〈检查〉。试验是为了解效果而做的操作，给病人量体温、看身体状况要说“检查”。"}, {"text": "他每天早上都去公园试验，锻炼身体。", "explanation": "这里应该用〈锻炼〉。试验是为检验效果而做的操作，早上去公园锻炼身体要说“锻炼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13256, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "试验", "is_correct": true, "explanation": "试验（shì yàn）：为了检验效果或性能而做的尝试，是正确答案。"}, {"text": "食言", "is_correct": false, "explanation": "食言（shí yán）两个音节的声调都与试验不同，意思是不守诺言。"}, {"text": "试样", "is_correct": false, "explanation": "试样（shì yàng）与试验只有韵尾不同（yàng 与 yàn），意思是用来检测的样品。"}, {"text": "石盐", "is_correct": false, "explanation": "石盐（shí yán）两个音节的声调都与试验不同，意思是岩盐这种矿物。"}, {"text": "时延", "is_correct": false, "explanation": "时延（shí yán）两个音节的声调都与试验不同，意思是时间上的延迟。"}], "explanations": {"试验": "试验（shì yàn）：为了检验效果或性能而做的尝试，是正确答案。", "食言": "食言（shí yán）两个音节的声调都与试验不同，意思是不守诺言。", "试样": "试样（shì yàng）与试验只有韵尾不同（yàng 与 yàn），意思是用来检测的样品。", "石盐": "石盐（shí yán）两个音节的声调都与试验不同，意思是岩盐这种矿物。", "时延": "时延（shí yán）两个音节的声调都与试验不同，意思是时间上的延迟。"}, "sentence_index": null, "correct_answer": "试验"}, "level_3": {"options": [{"text": "试验", "is_correct": true, "explanation": "试验：修饰“数据”，指检验效果的操作所得的数据，句意正确。"}, {"text": "故事", "is_correct": false, "explanation": "语义：“故事”没有可以记录的数据，“故事的数据”说不通。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：“笑话”不能产生需要记录的数据，与“记在本子上”的句意不合。"}, {"text": "玩意", "is_correct": false, "explanation": "语义：“玩意”泛指东西、小物件，不会产生需要记录的数据，“玩意的数据”说不通。"}], "explanations": {"试验": "试验：修饰“数据”，指检验效果的操作所得的数据，句意正确。", "故事": "语义：“故事”没有可以记录的数据，“故事的数据”说不通。", "笑话": "语义：“笑话”不能产生需要记录的数据，与“记在本子上”的句意不合。", "玩意": "语义：“玩意”泛指东西、小物件，不会产生需要记录的数据，“玩意的数据”说不通。"}, "sentence_index": 6, "correct_answer": "试验"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司每年都对员工进行试验，评定他们的业绩。", "explanation": "这里应该用〈考核〉。试验是为检验效果而做的操作，评定员工的工作业绩要用“考核”。"}, {"text": "我们每周都去博物馆试验。", "explanation": "这里应该用〈参观〉。试验是为检验效果而做的操作，去博物馆看展览要说“参观”。"}, {"text": "他每年都去农村试验民情。", "explanation": "这里应该用〈考察〉。试验是为检验效果做的操作，了解农村的实际情况要说“考察”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把试验花了两年时间才完成。", "corrected_sentence": "这项试验花了两年时间才完成。", "error_description": "量词用错：“把”用于有把手的器具，不能用来数“试验”。应说“这项试验”（或“一次试验”）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条试验做了三个星期才结束。", "corrected_sentence": "这项试验做了三个星期才结束。", "error_description": "量词用错：“条”用于细长的东西，不能用来数“试验”。应说“这项试验”（或“一次试验”）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c85de76-69f2-4f25-b993-5d99b43c3cc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13257, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
