INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13257, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指具有特定形状、结构或式样，供制作或仿效的模型或标准。", "primary_collocate": null, "pronunciation": "mú bǎn", "ipa": "mu˧˥ pan˨˩˦", "syllable_count": 2, "sentences": [{"text": "然而，此类地方实践常成为后续全国性立法的试验模板，体现政策演化的渐进逻辑。", "target_word": "模板", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "其中，一种名为OpenClaw的模型无关架构，凭借其去中心化的设计哲学和高度可适配的代理范式，正在引发学界与产业界的深层思辨：它是否将在2026年成为个人AI代理的标准模板？", "target_word": "模板", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这份简历模板很清楚，你可以直接用。", "target_word": "模板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我们一个作文模板。", "target_word": "模板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的做法成了全国的模板。", "target_word": "模板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请按这个模板写工作报告。", "target_word": "模板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新员工可以下载合同模板，再改一改内容。", "target_word": "模板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目的形式成了很多电视台的模板。", "target_word": "模板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用了一个现成的模板做海报。", "target_word": "模板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要求大家都用同一个模板写总结。", "target_word": "模板", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "简历模板", "label": "复合"}], "register": "中性", "sense_fingerprint": "供制作或仿效的标准样式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b3bbd23-8942-4e8f-b366-768ba894f710') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13257, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "模板", "is_correct": true, "explanation": "正确答案。句中指可供仿效的试验样式。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与句中书面的“立法”“政策演化”语体不符，也不能作“试验”的对象。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：“宠物”指饲养的动物，不能作为立法的试验对象。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是可供立法参照的样式，与“试验”搭配不通。"}], "explanations": {"模板": "正确答案。句中指可供仿效的试验样式。", "玩意儿": "语域：“玩意儿”是口语说法，与句中书面的“立法”“政策演化”语体不符，也不能作“试验”的对象。", "宠物": "语义：“宠物”指饲养的动物，不能作为立法的试验对象。", "天气": "语义：“天气”不是可供立法参照的样式，与“试验”搭配不通。"}, "sentence_index": 0, "correct_answer": "模板"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生从病人身上取了一份血液模板。", "explanation": "这里应该用〈样本〉。模板是供照着做的样式，不能用来指从人体取出的检验材料。"}, {"text": "博物馆展出了一只鸟的模板。", "explanation": "这里应该用〈标本〉。模板指可仿效的式样，不能用来指制作好的动物实物。"}, {"text": "他把模板吃掉了，还说味道很好。", "explanation": "这里应该用〈饼干〉。模板是供仿效的样式，不能吃，应说“饼干”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13257, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "模板", "is_correct": true, "explanation": "正确答案。合同模板是可以下载并参照修改的样式。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“下载”的对象应是文件或程序，不能说下载饼干。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”无法下载，“下载”不能与“脚步”搭配。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是实物，无法下载，也与“再改一改内容”的意思不符。"}], "explanations": {"模板": "正确答案。合同模板是可以下载并参照修改的样式。", "饼干": "搭配：“下载”的对象应是文件或程序，不能说下载饼干。", "脚步": "搭配：“脚步”无法下载，“下载”不能与“脚步”搭配。", "雨伞": "语义：雨伞是实物，无法下载，也与“再改一改内容”的意思不符。"}, "sentence_index": 6, "correct_answer": "模板"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位模板穿着新款裙子走上了舞台。", "explanation": "这里应该用〈模特〉。模板指供照着做的样式，不指走秀的人。"}, {"text": "妈妈用这个模板煮了一锅粥。", "explanation": "这里应该用〈锅〉。模板指供仿效的样式或标准，不是烹饪用具。"}, {"text": "他用模板给客人倒了一杯茶。", "explanation": "这里应该用〈茶壶〉。模板指供仿效的样式或标准，不是盛器，不能用来倒茶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13257, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这顶模板发给了全班同学。", "corrected_sentence": "他把这个模板发给了全班同学。", "error_description": "错误：量词用错。“顶”用于帽子等物，模板应用“个”，应说“这个模板”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13257, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一只新的模板。", "corrected_sentence": "这是一个新的模板。", "error_description": "错误：量词用错。“只”多用于动物，模板应用“个”，应说“一个新的模板”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7c6b85f-3bc5-496a-a14b-a563be0173e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
