INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13259, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一个国家在国际社会中的整体印象和声誉。", "primary_collocate": null, "pronunciation": "guó jì xíng xiàng", "ipa": "kuo˧˥ tɕi˥˩ ɕiŋ˧˥ ɕiɑŋ˥˩", "syllable_count": 4, "sentences": [{"text": "从全球趋势看，一次性塑料禁令已超越环境议题本身，演变为国家治理能力与国际形象的象征性场域。", "target_word": "国际形象", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "良好的国际形象有助于国家发展。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家一直在努力提升国际形象。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一次丑闻损害了政府的国际形象。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护环境能够改善国家的国际形象。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际形象关系到一个国家的声誉。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大型体育赛事是展示国际形象的机会。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外交部门要维护好国家的国际形象。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府希望通过援助塑造积极的国际形象。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际形象不好，投资者就会犹豫。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "國際形象", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "一个国家在国际社会中的整体印象和声誉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d2bbf4-79da-4014-b207-c5baecb20bf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13259, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国际形象", "is_correct": true, "explanation": "“国际形象”指国家在国际社会中的整体印象，与前文“国家治理能力”并列，句意通顺。"}, {"text": "国际象棋", "is_correct": false, "explanation": "语义：“国际象棋”是棋类游戏，不能作为“国家治理能力”的象征性场域，句意不通。"}, {"text": "国际航班", "is_correct": false, "explanation": "搭配：“象征性场域”不能与“航班”这类具体交通事物搭配。"}, {"text": "个人烦恼", "is_correct": false, "explanation": "语义：“个人烦恼”是个人的心理困扰，与“国家治理能力”这样的宏观概念并列不协调。"}], "explanations": {"国际形象": "“国际形象”指国家在国际社会中的整体印象，与前文“国家治理能力”并列，句意通顺。", "国际象棋": "语义：“国际象棋”是棋类游戏，不能作为“国家治理能力”的象征性场域，句意不通。", "国际航班": "搭配：“象征性场域”不能与“航班”这类具体交通事物搭配。", "个人烦恼": "语义：“个人烦恼”是个人的心理困扰，与“国家治理能力”这样的宏观概念并列不协调。"}, "sentence_index": 0, "correct_answer": "国际形象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中国的国际形象越来越广泛。", "explanation": "这里应该用〈国际影响〉。“广泛”形容范围，形象一般不用“广泛”形容，应说“国际影响越来越广泛”。"}, {"text": "这个国家的国际形象每年增长百分之五。", "explanation": "这里应该用〈国际贸易〉。“增长百分之五”说的是可以计算的数量，贸易额能增长，形象不能用百分比计算增长。"}, {"text": "两国的国际形象一直很密切。", "explanation": "这里应该用〈国际关系〉。“密切”形容关系，不能用来形容形象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13259, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际形象", "is_correct": true, "explanation": "“国际形象”指别国人对一个国家的印象，“展示国际形象的机会”符合句意。"}, {"text": "国际汇率", "is_correct": false, "explanation": "搭配：“汇率”是金融数据，不能作为“展示”的机会内容，句意不通。"}, {"text": "国际身材", "is_correct": false, "explanation": "体貌：“身材”指人的体型，不用于说国家的形象。"}, {"text": "国际口味", "is_correct": false, "explanation": "搭配：“展示”一般不与“口味”搭配，“展示国际口味”不通。"}], "explanations": {"国际形象": "“国际形象”指别国人对一个国家的印象，“展示国际形象的机会”符合句意。", "国际汇率": "搭配：“汇率”是金融数据，不能作为“展示”的机会内容，句意不通。", "国际身材": "体貌：“身材”指人的体型，不用于说国家的形象。", "国际口味": "搭配：“展示”一般不与“口味”搭配，“展示国际口味”不通。"}, "sentence_index": 6, "correct_answer": "国际形象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年的国际形象十分动荡。", "explanation": "这里应该用〈国际局势〉。“动荡”形容局势、社会的不稳定，形象不会“动荡”。"}, {"text": "两国之间的国际形象非常激烈。", "explanation": "这里应该用〈国际争端〉。“激烈”形容争论、冲突，形象不说“激烈”。"}, {"text": "这个国家的国际形象越来越重。", "explanation": "这里应该用〈国际分量〉。“重”形容影响力、分量，形象不说“重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13259, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛让这个国家的国际形像大大提升了。", "corrected_sentence": "这次比赛让这个国家的国际形象大大提升了。", "error_description": "错误：“形像”。正确：“形象”。“形象”的“象”不能写成“像”，应为“国际形象”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a0befb2-7c0f-481b-b847-2f8872445ee7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
